(window.GIM_TS=window.GIM_TS||{})["Gittin.5"]={"from":120,"a":[["\u0003נותנת\u0004 \u0003לה\u0004 \u0003ואוכלת,\u0004 ויש לחשוש שמאכילה אותה דבר שאינו מעושר. ואם כן, \u0003השתא\u0004 \u0005[עכשיו]\u0006 כך אנו חוששים \u0003מיגנב גנבא\u0004 \u0005[הרי\u0006 היא \u0005גונבת]\u0006 משל בעלה ונותנת לחברתה, \u0003חלופי לא מיחלפא\u0004 \u0005[להחליף אינה מחליפה]?\u0006 וכי אפשר לסמוך עליה שלא תחליף? אלא ודאי שחוששים, ואם כן לא רק בחמותו ובפונדקית אנו חוששים להחלפה!","\u0003אמר רב יוסף: התם נמי מוריא ואמרה\u0004 \u0005[שם גם כן מורה\u0006 היתר לעצמה לעשות כן \u0005ואומרת]:\u0006 \u0003תורא מדישיה קאכיל\u0004 \u0005[השור מדישו הוא אוכל]\u0006 והיא סבורה שמפני שהיא עובדת בהכנת האוכל מותר לה ליטול ממנו ואין זו גניבה. ואין ללמוד מכאן לכל עם הארץ שחשוד הוא להחליף.","ועוד בענין תבואה המופקדת בידיו של עם הארץ, \u0003העיד ר' יוסי בן המשולם משום\u0004 \u0005[בשם]\u0006 \u0003ר' יוחנן אחיו שאמר משום ר' אלעזר בן חסמא: אין עושין חלת עם הארץ בטהרה,\u0004 שלא יעשה הגבל (לש הבצק) עבור עם הארץ, את חלק החלה בלבד בטהרה, \u0003אבל עושין עיסת חוליו\u0004 (חולין שלו) כולה \u0003בטהרה, ונוטל הימנה\u0004 (ממנה) \u0003כדי\u0004 שיעור \u0003חלה ומניחה בכפישא\u0004 (מין סל) \u0003או באנחותא\u0004 (מין כלי) שאינם מקבלים טומאה, \u0003וכשבא עם הארץ ליטול\u0004 את מה שעשה לו, \u0003נוטל את שתיהן\u0004 (את העיסה ואת החלה) \u0003ואינו חושש\u0004 הגבל שמא יטמא עם הארץ את החלה. \u0003ו\u0004מאותו טעם \u0003אין עושין\u0004 בבית הבד שמן תרומת \u0003זיתיו\u0004 של עם הארץ \u0003בטהרה,\u0004 \u0003אבל עושין זיתים חוליו\u0004 (חולין שלו) כולם \u0003בטהרה,\u0004 \u0003ונוטל הימנה\u0004 מכל השמן \u0003כדי תרומה ומניחה בכליו של חבר\u0004 שהם טהורים, \u0003וכשבא עם הארץ ליטול\u0004 — \u0003נוטל את שתיהן, ואינו חושש\u0004 הבדד (עושה השמן), לטומאת התרומה.","","ושואלים: \u0003וטעמא מאי\u0004 \u0005[ומה הטעם]\u0006 שמותר לו לעשות כן? \u0003אמר ר' יוחנן: משום כדי חייו\u0004 (פרנסתו) של \u0003גבל\u0004 (האומן שעושה את מלאכת הלישה), \u0003ומשום כדי חייו\u0004 של \u0003בדד\u0004 (האומן העושה שמן מן הזיתים).","ומעירים: \u0003וצריכא\u0004 \u0005[וצריך]\u0006 להשמיע את ההלכה בשני המקרים. \u0003דאי אשמועינן\u0004 \u0005[שאם היה משמיע לנו]\u0006 רק דין \u0003גבל,\u0004 היינו אומרים שדווקא בו הקלו \u0003משום\u0004 ש\u0003לא נפיש אגריה\u0004 \u0005[מרובה שכרו]\u0006 ולכן הוא עני וצריך למזונות, \u0003אבל בדד דנפיש אגריה\u0004 \u0005[שמרובה שכרו]\u0006 — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יקלו עליו. ומצד שני, \u0003אי אשמועינן\u0004 \u0005[אם היה משמיע לנו]\u0006 ב\u0003בדד,\u0004 היינו אומרים שדווקא בו הקלו \u0003משום\u0004 ש\u0003לא שכיח ליה\u0004 \u0005[מצויה לו]\u0006 עבודה אלא בעונה אחת בשנה, של מסיק הזיתים, \u0003אבל גבל דשכיח ליה\u0004 \u0005[שמצויה לו]\u0006 עבודה כל השנה — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא,\u0004 על כן, \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמרו שני הדברים.","ולעצם הדין ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 באותה ברייתא: \u0003נוטל הימנה כדי חלה ומניחה בכפישא או באנחותא, וכשבא עם הארץ ליטול, נוטל את שתיהן ואינו חושש,\u0004 שואלים: \u0003וליחוש דילמא נגע\u0004 \u0005[ונחשוש שמא יגע]\u0006 עם הארץ \u0003בה,\u0004 בחלה! ומשיבים: \u0003דאמרינן ליה\u0004 \u0005[שאומרים אנו לו]:\u0006 \u0003חזי, אי נגעת בה הדרא לטיבלא\u0004 \u0005[ראה, אם אתה נוגע בה,\u0006 בחלה, \u0005תחזור\u0006 העיסה ותיעשה \u0005טבל].\u0006 ושואלים: \u0003וליחוש דילמא\u0004 \u0005[ונחשוש שמא]\u0006 \u0003לא איכפת ליה\u0004 \u0005[לו]\u0006 שהיא חוזרת ונעשית טבל! ומשיבים: \u0003השתא לתקוני קא מיכוין\u0004 \u0005[עכשיו\u0006 הרי \u0005לתקן הוא מכוון]\u0006 ומשום כך לוקח גבל העושה בטהרה, ואתה רוצה לומר כי \u0003מיכפת לא איכפת ליה\u0004 \u0005[לא איכפת לו]\u0006 שתהא עיסתו כראוי?","","ועוד למה ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 בענין שמן: \u0003נוטל הימנה כדי תרומה ומניחה בכליו של חבר, וכשבא עם הארץ ליטול, נוטל את שתיהן ואינו חושש,\u0004 שואלים: \u0003וליחוש דילמא נגע\u0004 \u0005[ונחשוש שמא יגע]\u0006 עם הארץ \u0003בה,\u0004 בתרומת השמן בלא מתכוון! \u0003בשלמא התם\u0004 \u0005[נניח שם\u0006 בחלה\u0005]\u0006 \u0003אית ליה היכרא\u0004 \u0005[יש לו היכר]\u0006 שהוא יודע שהוא שם אותו בכלי מיוחד שאין רגילים להניח בו בצק, אבל \u0003הכא מאי היכרא אית ליה\u0004 \u0005[כאן מה,\u0006 איזה \u0005היכר יש לו]?\u0006 ומשיבים: \u0003דמנח ליה\u0004 \u0005[שמניח אותו]\u0006 את השמן \u0003בכלי גללים, בכלי אבנים, בכלי אדמה\u0004 שאינם מקבלים טומאה. ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003מאי איריא\u0004 \u0005[מה שייך]\u0006 מדוע דווקא בכלים של \u0003חבר? אפילו\u0004 בכלים של \u0003עם הארץ נמי\u0004 \u0005[גם כן]\u0006 יכול להשתמש, שהרי כלים אלה אינם מקבלים כלל טומאה! ומשיבים: \u0003הכי נמי קאמר\u0004 \u0005[כך גם כן אמר],\u0006 שכוונתו היתה לומר \u0003בכלים של עם הארץ\u0004 שאינם מקבלים טומאה, ולכן הם \u0003הראויין להשתמש בהן חבר.\u0004 שנינו במשנה \u0003מחזיקין ידי גוים בשביעית.\u0004 ותוהים: \u0003מחזיקין? והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב דימי בר שישנא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: אין עודרין עם הגוי בשביעית, ואין כופלין \"שלום\" לגוי!\u0004 ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אין הכוונה שמסייעים להם בעבודה ממש, אלא \u0003למימרא להו \"אחזוקו\" בעלמא\u0004 \u0005[לומר להם \"התחזקו\" בלבד],\u0006 \u0003כי הא\u0004 \u0005[כמו זה]\u0006 ש\u0003רב יהודה אמר להו \"אחזוקו\"\u0004 \u0005[היה אומר להם \"התחזקו\"],\u0006 \u0003רב ששת אמר להו \"אשרתא\"\u0004 \u0005[היה אומר להם \"יישר\u0006 כוחכם \u0005\"]\u0006 וביטויים כאלה בוודאי מותרים.","","שנינו במשנה: \u0003ואין כופלין \"שלום\" לגוי.\u0004 ומספרים: \u0003רב חסדא\u0004 היה \u0003מקדים ויהיב להו שלמא\u0004 \u0005[ונותן להם שלום]\u0006 כדי שעל ידי זה לא יצטרך לכפול \"שלום\" בתשובה. ואילו \u0003רב כהנא אמר להו\u0004 \u0005[היה אומר להם,\u0006 לגויים\u0005]\u0006 \u0003\"שלמא למר\"\u0004 \u0005[שלום לאדוני]\u0006 כשהיה עונה להם, ועל ידי זה לא היה צריך לכפול.","","שנינו במשנה: \u0003ושואלין בשלומן.\u0004 ותוהים: \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003אחזוקי מחזקינן\u0004 \u0005[מחזקים אנו]\u0006 את ידיהם, ומעודדים אותם, אם כן \u0003שואלין בשלומן מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]?\u0006 \u0003אמר רב ייבא: לא נצרכא\u0004 \u0005[נצרכה]\u0006 הלכה זו \u0003אלא ליום חגם. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003לא יכנס אדם לביתו של גוי ביום חגו ויתן לו \"שלום\",\u0004 מפני שהוא נראה שהוא מברך אותו לכבוד חגו. אם \u0003מצאו בשוק\u0004 — \u0003נותן לו\u0004 \"שלום\" \u0003בשפה רפה ובכובד ראש\u0004 שלא ייראה כאילו הוא שמח בשמחתו.","ובענין זה של כפילת שלום מסופר: \u0003רב הונא ורב חסדא הוו יתבי\u0004 \u0005[היו יושבים],\u0006 \u0003חליף ואזיל\u0004 \u0005[חלף ועבר]\u0006 החכם \u0003גניבא\u0004 לידם. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003חד לחבריה\u0004 \u0005[אחד לחבירו]:\u0006 \u0003ניקום מקמיה, דבר אוריין\u0004 \u0005[נעמוד מלפניו,\u0006 לכבודו, \u0005שבן תורה]\u0006 \u0003הוא.\u0004 \u0003אמר לו: ומקמי פלגאה ניקום\u0004 \u0005[ו\u0006כי \u0005מלפני בעל מחלוקת נעמוד]?\u0006 \u0003אדהכי אתא איהו לגבייהו\u0004 \u0005[בינתיים בא הוא אצלם],\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003שלמא עלייכו מלכי, שלמא עלייכו מלכי\u0004 \u0005[שלום עליכם מלכים, שלום עליכם מלכים]!\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003מנא\u0004 \u0005[מניין]\u0006 \u0003לך דרבנן איקרו\u0004 \u0005[שחכמים נקראו]\u0006 \u0003מלכים? אמר להו\u0004 \u0005[להם]:\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 בדברי החכמה־התורה בספר משלי \u0003\"בי מלכים ימלכו\"\u0004 (משלי ח, טו). \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003ומנא\u0004 \u0005[ומניין]\u0006 \u0003לך דכפלינן \"שלמא\" למלכי\u0004 \u0005[שכופלים \"שלום\" למלכים]?\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 ש\u0003אמר רב יהודה אמר רב: מנין שכופלין \"שלום\" למלך? שנאמר: \"ורוח לבשה את עמשי ראש השלישים\u0004 לך דויד ועמך בן ישי שלום, שלום לך ושלום לעוזרך\u0003\"\u0004(דברי הימים א יב, יט), משמע שכופלים \"שלום\" למלך.","","\u0003אמרי ליה\u0004 \u0005[אמרו לו]:\u0006 \u0003ליטעום מר מידי\u0004 \u0005[יטעום אדוני דבר מה],\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב יהודה אמר רב: אסור לו לאדם שיטעום כלום עד שיתן מאכל לבהמתו, שנאמר\u0004 בכתוב: \u0003\"ונתתי עשב בשדך לבהמתך\"\u0004 (דברים יא, טו), \u0003והדר\u0004 \u0005[ואחר כך]\u0006 נאמר: \u0003\"ואכלת ושבעת\"\u0004",""],["אדם \u0003האומר\u0004 לחבירו: \u0003\"התקבל גט זה לאשתי\" או\u0004 שאומר לו \u0003\"הולך\u0004 כשליחי \u0003גט זה לאשתי\",\u0004 \u0003אם רצה\u0004 הבעל \u0003לחזור\u0004 בו ולבטל את הגט — \u0003יחזור,\u0004 עד שלא הגיע גט לידה. ואולם \u0003האשה שאמרה\u0004 לשליח: \u0003\"התקבל לי\u0004 (היעשה שליח לקבל עבורי את) \u0003גיטי\"\u0004 ונתן הבעל את הגט לשליח, \u0003אם רצה\u0004 הבעל \u0003לחזור\u0004 — \u0003לא יחזור,\u0004 כי עם מסירת הגט לשליח הרי זה כאילו נמסר ביד האשה עצמה וכבר נתגרשה בו.","\u0003לפיכך, אם אמר לו הבעל\u0004 לשליח קבלה של האשה: \u0003\"אי איפשי\u0004 (אין רצוני) \u0003שתקבל לה, אלא הולך ותן לה\",\u0004 שלא הסכים שתתגרש בשעת קבלת הגט על ידי השליח, אלא שיוליכנו השליח, וימסור ביד האשה כשליחו שלו, ובכך תתגרש, במקרה זה \u0003אם רצה\u0004 הבעל \u0003לחזור\u0004 בו, ולבטל את הגט לפני שהגיע הגט ליד האשה — \u0003יחזור.\u0004","\u0003רבן שמעון בן גמליאל אומר:\u0004 לא רק בלשון \"התקבל\", אלא \u0003אף\u0004 כאשר \u0003ה\u0004אשה \u0003אומרת\u0004 לשליח: \u0003\"טול לי גיטי\",\u0004 כוונתה שיהא שליח לקבל את הגט עבורה, ולפיכך אם רצה הבעל \u0003לחזור\u0004 — \u0003לא יחזור.\u0004","על דברי המשנה שהממנה שליח להוליך גט לאשתו בלשון \"התקבל\" ו\"הולך\" יכול לחזור בו, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אויא לרב אשי:\u0004 יש לדייק ש\u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 במקרה ש\u0003לא שויתיה\u0004 \u0003איהי\u0004 \u0005[מינתה אותו היא\u0006 האשה\u0005]\u0006 \u0003שליח לקבלה,\u0004 אלא במקרה שעשאו הבעל שליח הולכה — יכול הבעל לחזור בו, \u0003הא שויתיה איהי\u0004 \u0005[הרי\u0006 אם \u0005היתה היא ממנה אותו]\u0006 קודם לכן \u0003שליח לקבלה, אף\u0004 אם אמר הבעל לשליח \"הולך\" אם \u0003רצה\u0004 הבעל \u0003לחזור\u0004 — \u0003לא יחזור\u0004 בו. \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שהציווי \u0003\"הולך\" כ\"זכי\" דמי\u0004 \u0005[כמו \"זכה\"\u0006 הוא \u0005נחשב],\u0006 שכיון שאמר \"הולך\" הרי זה כמזכה על ידי השליח, וחלים הגירושין מייד במסירת הגט!","ודוחים: \u0003לא,\u0004 אין מכאן הוכחה, ו\u0003לעולם אימא\u0004 \u0005[\u0006יכול אני \u0005לומר]\u0006 \u0003לך:\u0004 שבאמת \u0003\"הולך\" לאו כ\"זכי\" דמי\u0004 \u0005[אינו נחשב כ\"זכה\"],\u0006 ואין ללמוד מדיוק לשון זה, \u0003ו\"התקבל גט לאשתי\" איצטריכא ליה\u0004 \u0005[הצטרך לו]\u0006 לתנא במשנתנו לומר, ודווקא במשפט זה נמצא החידוש,","\u0003דסלקא דעתך אמינא\u0004 \u0005[שיעלה על דעתך לומר]\u0006 \u0003הואיל ובעל לאו בר שויה\u0004 \u0005[אינו בר מינוי]\u0006 \u0003שליח לקבלה הוא,\u0004 ויכול הוא רק למנות שליח להולכה. ולכן במקרה שאמר הבעל לשליח \"התקבל גט לאשתי\" \u0003אף על גב דמטא גיטא\u0004 \u0005[אף על פי שמגיע הגט]\u0006 \u0003לידה\u0004 \u0003לא להוי גיטא\u0004 \u0005[יהא\u0006 זה \u0005גט],\u0006 שהרי מינויו של הבעל (\"התקבל\") אינו תקף ואין זו שליחות כלל, ומצד שני האשה עצמה לא מינתה אותו כשליח שלה לקבלת הגט, ולכן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שמה שאמר \"התקבל\" כוונתו היתה \u0003\"התקבל\u0004 (קבל, קח) \u0003והולך\" קאמר\u0004 \u0005[הוא אומר]\u0006 ולא מינהו אלא כשליח להולכה. ואין מכאן ראיה ש\"הולך\" כ\"זכי\".","ומנסים להביא ראיה אחרת, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005],\u0006 \u0003האשה שאמרה: \"התקבל לי גיטי\", אם רצה לחזור\u0004 — \u0003לא יחזור. מאי לאו\u0004 \u0005[האם לא]\u0006 נאמרה הלכה זו \u0003לא שנא\u0004 \u0005[שונה]\u0006 אם אמר הבעל לשליח בלשון \u0003קבלה\u0004 (\"התקבל\" לאשתי), \u0003לא שנא\u0004 \u0005[שונה]\u0006 אם אמר בלשון \u0003הולכה\u0004 (\"הולך\") אינו יכול לחזור? ומכאן ש\"הולך\" כ\"זכה\"!","ודוחים: \u0003לא,\u0004 אין הדברים אמורים אלא על לשון \u0003קבלה,\u0004 שאם אמר לשליח \"התקבל גט זה לאשה\" אינו יכול עוד לחזור בו מן השליחות, ולא אם אמר לו \"הולך\".","ומציעים עוד ראיה, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: \u0003לפיכך, אם אמר לו הבעל: \"אי איפשי\u0004 (אין רצוני) \u0003שתקבל לה, אלא הולך ותן לה\", אם רצה\u0004 הבעל \u0003לחזור\u0004 — \u0003יחזור.\u0004 ונדייק: \u0003טעמא\u0004 \u0005[הטעם]\u0006 דווקא במקרה ש\u0003אמר \"אי איפשי\"\u0004 הוא שיכול לחזור, \u0003הא\u0004 \u0005[הרי אם]\u0006 \u0003לא אמר \"אי איפשי\",\u0004 אף שאמר \"הולך\" \u0003אם רצה לחזור\u0004 — \u0003לא יחזור, שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003\"הולך\" כ\"זכי\" דמי\u0004 \u0005[כ\"זכה\" נחשב]!\u0006","ודוחים: אין מכאן ראיה, שכן \u0003דילמא\u0004 \u0005[שמא]\u0006 מדובר פה שאמר לו \u0003ב\"הילך\",\u0004 כלומר, \"הרי לך והרי הוא שלך\", וזו בודאי לשון זיכוי.","בעצם דין השליחות בגט מבררים דברים, ובתחילה מקדימים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 לנו ש\u0003איש הוי\u0004 \u0005[הריהו,\u0006 יכול להיות\u0005]\u0006 \u0003שליח להולכה, שכן בעל מוליך גט לאשתו\u0004 ומשום כך כל איש יכול להיות שליח, מאחר והוא יכול להיות בעצמו נותן גט, \u0003ו\u0004כן פשוט לנו \u0003ש\u0004\u0003אשה\u0004 \u0003הויא\u0004 \u0005[הרי היא נעשית]\u0006 \u0003שליח לקבלה, שכן אשה מקבלת גיטה מיד בעלה.\u0004 אולם במקרים הבאים יש לשאול: \u0003איש\u0004 כשליח \u0003לקבלה\u0004 של גט, \u0003והאשה\u0004 כשליחה \u0003להולכה, מאי\u0004 \u0005[מה]\u0006 דינם? האם יכולים הם לשמש כשליחים שכאלה!","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לכך ממה ששנינו במשנתנו, \u0003האומר: \"התקבל גט זה לאשתי\" או \"הולך גט זה לאשתי\", אם רצה\u0004 הבעל \u0003לחזור\u0004 בו — \u0003יחזור.\u0004 \u0003האשה שאמרה\u0004 לשליח: \u0003\"התקבל לי\u0004 (היעשה שליח לקבל עבורי את) \u0003גיטי\"\u0004 ונתן הבעל את הגט לשליח, \u0003אם רצה\u0004 הבעל \u0003לחזור\u0004 — \u0003לא יחזור, מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר \u0003בחד שליח\u0004 \u0005[בשליח אחד]\u0006 באותו שליח בשני המקרים, \u0003ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 כי השליח ה\u0003כשר לקבלה כשר\u0004 גם \u0003להולכה.\u0004 ודוחים: \u0003לא,\u0004 אפשר לפרש שמדובר במשנתנו \u0003בשני שלוחין\u0004 שונים, ושליח להולכה הוא דווקא גבר, ושליח לקבלה — אשה.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת ממה ששנינו במשנתנו: \u0003לפיכך, אם אמר לו הבעל\u0004 לשליח ששלחה האשה לקבל עבורה את גיטה: \u0003\"אי איפשי שתקבל לה, אלא הולך ותן לה\",\u0004 במקרה זה \u0003אם רצה\u0004 הבעל \u0003לחזור\u0004 בו, ולבטל את הגט לפני שהגיע הגט ליד האשה — \u0003יחזור,\u0004 שהרי הפך השליח לשליח הולכה. \u0003והא הכא\u0004 \u0005[והרי כאן]\u0006 \u0003דחד\u0004 \u0005[שאחד,\u0006 שאותו\u0005]\u0006 \u0003שליח הוא, ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 שמי ש\u0003כשר ל\u0004שליחות \u0003קבלה כשר ל\u0004שליחות \u0003הולכה.\u0004","ומכל מקום \u0003פשוט מינה\u0004 \u0005[תפתור מכאן]\u0006 על כל פנים ש\u0003איש הוי\u0004 \u0005[הרי הוא נעשה]\u0006 \u0003שליח לקבלה,\u0004 ויש טעם לדבר: \u0003שכן אב מקבל גט לבתו קטנה\u0004 במקומה, שהרי היא שאינה בת דעת אינה יכולה לקבל. ואולם \u0003אשה להולכה\u0004 של גט עדיין \u0003תיבעי\u0004 \u0005[תישאל\u0006 השאלה\u0005]\u0006 \u0003לך מאי\u0004 \u0005[מה]\u0006 דינה? \u0003אמר רב מרי, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לכך ממה ששנינו במשנה: \u0003אף הנשים שאין נאמנות לומר\u0004 על אשה ש\u0003מת בעלה\u0004 מפני שחשודות להזיק לה — \u0003נאמנות להביא את גיטה, והתם\u0004 \u0005[ושם]\u0006 בוודאי שליחות \u0003הולכה היא.\u0004","\u0003אמר רב אשי: מסיפא נמי שמע מינה\u0004 \u0005[מסופה\u0006 של אותה משנה \u0005גם כן\u0006 אתה יכול \u0005ללמוד ממנה]\u0006 אותו פתרון, \u0003דקתני סיפא\u0004 \u0005[ששנה\u0006 ב\u0005סופה]:\u0006 \u0003האשה עצמה מביאה את גיטה, ובלבד שהיא צריכה לומר: \"בפני נכתב ובפני נחתם\", ואוקימנא\u0004 \u0005[והעמדנו\u0006 זאת\u0005]\u0006 \u0003בהולכה,\u0004 אם כן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שאשה יכול להיות שליח להולכה.","\u0003איתמר\u0004 \u0005[נאמר],\u0006 אמרה אשה לשליח: \u0003\"הבא לי גיטי\",\u0004 ומשמעות הדברים שרק משעה שהגט יגיע לידי האשה היא מגורשת, \u0003ו\u0004השליח בא ואמר לבעל: \u0003\"אשתך אמרה התקבל לי גיטי\",\u0004 ומשמעות הדברים שמשעה שהגט בידו הרי היא מגורשת, \u0003והוא,\u0004 הבעל, \u0003אמר: \"הילך\u0004 (הרי לך) \u0003כמה שאמרה\",\u0004 מה יהא הדין? האם הולכים אחר דבריו של השליח או אחר דבריה?","\u0003אמר רב נחמן אמר רבה בר אבוה אמר רב:\u0004 במקרה זה \u0003אפילו הגיע גט לידה\u0004 — \u0003אינה מגורשת.\u0004 ומדייקים מדבריו: \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003אדיבורא דידיה קא סמיך\u0004 \u0005[על הדיבור שלו,\u0006 של השליח, \u0005הוא סומך],\u0006 ונותן לו בתורת שליח האשה לקבלה, וכיון שהאשה לא מינתה אותו לכך, ואף הבעל אינו יכול למנותו לתפקיד זה — בטלה שליחותו לגמרי, ולכן אינו גט. \u0003דאי אדיבורא דידה קא סמיך\u0004 \u0005[שאם על הדיבור שלה הוא,\u0006 הבעל, \u0005סומך]\u0006 ועל דעת זו נתן לו את הגט, אם כן \u0003מכי מטי גיטא\u0004 \u0005[מכאשר בא הגט]\u0006 \u0003לידה מיהא תיגרש\u0004 \u0005[על כל פנים תתגרש]\u0006 שהרי לפי דבריה נעשה שליח להולכה עבור הבעל!","\u0003אמר רב אשי: הכי השתא\u0004 \u0005[כך אתה משווה]?\u0006"],["\u0003בשלמא אי איתמר אפכא\u0004 \u0005[נניח אם היה נאמר ההיפך]\u0006 שהאשה אמרה: \u0003\"התקבל לי גיטי\", ו\u0004השליח אמר: \u0003\"אשתך אמרה הבא לי גיטי\", והוא,\u0004 הבעל, \u0003אמר: \"הילך כמה שאמרה\", ו\u0004על כך \u0003אמר רב נחמן אמר רבה בר אבוה אמר רב: כיון שהגיע גט לידו\u0004 של השליח \u0003מגורשת, אלמא\u0004 \u0005[מכאן]\u0006 היינו יכולים באמת ללמוד \u0003אדיבורא דידה\u0004 \u0005[\u0006ש\u0005על הדיבור שלה],\u0006 על דעתה של האשה, \u0003הוא\u0004 הבעל \u0003דקא סמיך\u0004 \u0005[סומך],\u0006 שנשאר השליח בגדר שליח לקבלה.","\u0003אי נמי\u0004 \u0005[או גם כן]\u0006 אם היה אומר רב נחמן שהיא מגורשת משעה שמגיע הגט \u0003לידה,\u0004 היינו באים ללמוד: \u0003אדיבורא דידיה קא סמיך\u0004 \u0005[על הדיבור שלו,\u0006 של השליח, \u0005הוא\u0006 הבעל \u0005סומך]\u0006 ונעשה השליח, כדבריו, שליח להולכה בלבד. \u0003אלא הכא\u0004 \u0005[כאן],\u0006 זה שהגט אינו גט, אינו משום שהבעל סומך על דיבור זה או אחר, אלא \u0003משום דעקריה\u0004 \u0005[שעקר]\u0006 \u0003שליח לשליחותיה\u0004 \u0005[את שליחותו]\u0006 \u0003לגמרי הוא,\u0004 וכיצד? — בזה ש\u0003אמר:\u0004 \u0003שליח לקבלה הוינא\u0004 \u0005[הריני],\u0006 הריהו כאומר: שליח \u0003להולכה לא הוינא\u0004 \u0005[אהיה],\u0006 שאיני רוצה לטרוח ולהביא לה את הגט. ואם כן, גם כאשר אחר כך נמלך והוליך את הגט לאשה, הרי לא עשה זאת לא בשליחות האשה ואף לא בשליחות הבעל, ולכן אין ללמוד מכאן כלל על דברי מי הבעל סומך.","על דברי רב נחמן האמורים למעלה \u0003אמר רב הונא בר חייא, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממשנתנו: \u0003האומר: \"התקבל גט זה לאשתי\" או\u0004 שאומר \u0003\"הולך גט זה לאשתי\",\u0004 אם \u0003רצה\u0004 הבעל \u0003לחזור\u0004 — \u0003יחזור.\u0004 ונדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 אם \u0003רצה\u0004 לחזור בו, \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003לא רצה\u0004 — \u0003הוי\u0004 \u0005[הריהו]\u0006 \u0003גט,\u0004","\u0003ואמאי\u0004 \u0005[ומדוע]\u0006 כאשר אמר הבעל \"התקבל\" הרי זה גט? \u0003הא\u0004 \u0005[הרי]\u0006 \u0003בעל לאו\u0004 \u0005[לא]\u0006 \u0003בר שויא\u0004 \u0005[בר מינוי,\u0006 יכול למנות\u0005]\u0006 \u0003שליח לקבלה הוא!\u0004 \u0003אלא אמרינן\u0004 \u0005[אומרים אנו]\u0006 כך: \u0003כיון שנתן עיניו לגרשה\u0004 והחליט לעשות זאת, \u0003מימר\u0004 \u0005[אמור]\u0006 ש\u0003אמר\u0004 בליבו: \u0003תיגרש כל היכי דמגרשה\u0004 \u0005[תתגרש בכל אופן\u0006 שמועיל \u0005שתתגרש\u0006 בו\u0005],\u0006 אם בקבלה ואם בהולכה, ואין הלשון \"התקבל גט לאשתי\" מעכבת בדבר. \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 במקרה שדן בו רב נחמן, \u0003כיון שנתן עיניו לגרשה, מימר\u0004 \u0005[אמור]\u0006 ש\u0003אמר:\u0004 \u0003תיגרש כל היכי דמגרשה\u0004 \u0005[תתגרש בכל אופן שמתגרשת]\u0006 על ידו!","ודוחים: \u0003הכי השתא\u0004 \u0005[כך אתה משווה]?!\u0006 \u0003התם\u0004 \u0005[שם]\u0006 בענין של האומר \"התקבל לי גט לאשתי\" \u0003אדם יודע שאין שליחות לקבלה\u0004 נעשית על ידי הבעל, \u0003וגמר\u0004 בליבו \u0003ונתן לשם הולכה,\u0004 ו\"התקבל\" שאמר משמעו קבלת הגט לידיו לצורך הולכה לאשה, ולא מעשה גירושין באותה קבלה. אולם \u0003הכא\u0004 — \u0003טעי\u0004 \u0005[כאן\u0006 הוא \u0005טועה]\u0006 וסומך על דיבורו של השליח שאמר לו שהינו שליח קבלה של האשה.","\u0003אמר רבא, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: \u0003קטנה שאמרה\u0004 לשליח: \u0003\"התקבל לי גיטי\"\u0004 — \u0003אינו גט עד שיגיע גט לידה,\u0004 שאין בכוחה של קטנה לעשות שליח. ונדייק מכאן: \u0003כי מטי גיטא\u0004 \u0005[כאשר מגיע הגט]\u0006 \u0003לידה מיהא\u0004 \u0003מגרשה\u0004 \u0005[על כל פנים\u0006 היא \u0005מגורשת],\u0006 \u0003ואמאי\u0004 \u0005[ומדוע]?\u0006 \u0003והא לאו\u0004 \u0005[והרי לא]\u0006 \u0003שליח להולכה שוייה\u0004 \u0005[מינה אותו\u0006 הבעל\u0005]!\u0006 \u0003אלא אמרינן\u0004 \u0005[אומרים אנו]:\u0006 \u0003כיון שנתן עיניו לגרשה, מימר\u0004 \u0005[אמור]\u0006 \u0003אמר\u0004 בליבו: \u0003תיגרש כל היכי דמגרשה\u0004 \u0005[תתגרש בכל אופן שמתגרשת]\u0006 ונעשה השליח שליח הולכה שלו. \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 בדינו של רב נחמן \u0003כיון שנתן עיניו לגרשה, מימר\u0004 \u0005[אמור]\u0006 \u0003אמר\u0004 בליבו: \u0003תיגרש כל היכי דמגרשה\u0004 \u0005[תתגרש בכל אופן שמתגרשת]!\u0006","ודוחים: \u0003הכי השתא\u0004 \u0005[כך אתה משווה]?!\u0006 \u0003התם\u0004 \u0005[שם]\u0006 בקטנה \u0003אדם יודע שאין שליחות לקטן,\u0004 \u0003וגמר\u0004 בליבו \u0003ונתן לה\u0004 לשליח זה \u0003לשום\u0004 (לשם) \u0003הולכה דידיה\u0004 \u0005[שלו],\u0006 שהוא מינה את האיש כשליח שלו להולכה, \u0003הכא טעי\u0004 \u0005[כאן\u0006 בדינו של רב נחמן הוא \u0005טועה]\u0006 בדיבורו של השליח.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו בברייתא: אמרה האשה לשליח \u0003\"הבא לי גיטי\" ו\u0004השליח אומר: \u0003\"אשתך אמרה התקבל לי גיטי\",\u0004 או אמרה האשה: \u0003\"התקבל לי גיטי\" ו\u0004השליח בא ואומר: \u0003\"אשתך אמרה הבא לי גיטי\", והוא,\u0004 הבעל, \u0003אמר\u0004 לשליח באחד הלשונות הללו: \u0003\"הולך, ותן לה, זכי לה, והתקבל לה\",\u0004 אם \u0003רצה\u0004 הבעל \u0003לחזור\u0004 — \u0003יחזור,\u0004 ואולם \u0003משהגיע גט לידה\u0004 — הריהי \u0003מגורשת.\u0004","\u0003מאי לאו\u0004 \u0005[האם אין]\u0006 הכוונה בברייתא שלשונות \u0003קבלה\u0004 שבדברי הבעל (\"זכי לה\", \"התקבל לה\") נאמרים ביחס ללשון \u0003קבלה\u0004 שבדברי השליח (\"אשתך אמרה התקבל\"), \u0003ו\u0004כן לשונות \u0003הולכה\u0004 של הבעל (\"הולך ותן לה\") נאמרים כלפי לשון \u0003הולכה\u0004 של השליח (\"אשתך אמרה הבא\")? ונפסק בברייתא שהגט חל משיגיע לידה. ואם כן במקרה של קבלה וקבלה נסתרים דברי רב נחמן שאם אמרה האשה \"הבא\" והשליח שינה ואמר \"אשתך אמרה התקבל\" שאין האשה מגורשת אף משהגיע הגט לידה!","ודוחים: \u0003לא,\u0004 מדובר בברייתא שהבעל נקט בלשון \u0003קבלה\u0004 לעומת לשון \u0003הולכה\u0004 של השליח, וכדברי האשה, \u0003ו\u0004כן לשון \u0003הולכה\u0004 לעומת לשון \u0003קבלה\u0004 של שליח וכדברי האשה, ומשום כך האשה מגורשת.","ומקשים: \u0003אי\u0004 \u0005[אם]\u0006 מדובר בלשון \u0003קבלה\u0004 של הבעל כלפי לשון \u0003הולכה\u0004 של השליח, וטעמו של דבר — לפי שאף האשה נקטה בלשון \"התקבל\" — אם כן \u0003מכי מטי גיטא לידיה לאלתר ליהוי גיטא\u0004 \u0005[כשמגיע הגט לידו\u0006 של השליח \u0005מייד יהיה גט],\u0006 שהרי השליח נשאר שליח קבלה! ואולם הברייתא אומרת שאין הגט חל אלא רק משעה שיגיע ליד האשה. \u0003שמעת מינה\u0004 \u0005[לומד אתה מכאן]\u0006 \u0003דאדיבורא דידיה קא סמיך\u0004 \u0005[שעל הדיבור שלו,\u0006 של שליח, \u0005הוא סומך]\u0006 ועושה אותו שליח להולכה בלבד, וכפי שרצינו להסיק לעיל מדברי רב נחמן!","ודוחים: \u0003הכי השתא\u0004 \u0005[כך אתה משווה]?!\u0006 \u0003התם קאמר ליה\u0004 \u0005[שם אומר לו]\u0006 \u0003\"הילך כמה שאמרה\"\u0004 ונמצא שתלה במפורש בהוראת האשה, \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003מי קאמר ליה\u0004 \u0005[האם אומר לו]\u0006 \u0003\"הילך כמה שאמרה\"?\u0004 אלא הוא נותן גט סתם, וסומך על דיבורו של השליח.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 אמרה האשה לשליח: \u0003\"התקבל לי גיטי\",\u0004 והשליח בא \u0003ו\u0004אמר לבעל: \u0003\"אשתך אמרה התקבל לי גיטי\", והוא,\u0004 הבעל, \u0003אומר: \"הולך, ותן לה, זכי לה והתקבל לה\",\u0004 אם \u0003רצה\u0004 הבעל \u0003לחזור\u0004 בו — \u0003לא יחזור,\u0004 שהרי מייד כשנתן לשליח הקבלה — חל הגט. \u0003ר' נתן אומר:\u0004 אם אמר הבעל \u0003\"הולך, ותן לה\", רצה לחזור\u0004 — \u0003יחזור,\u0004 שעשה אותו שליח הולכה, וכל עוד לא הגיע הגט לידי האשה יכול הבעל לחזור בו. אבל אם אמר: \u0003\"זכי לה והתקבל לה\",\u0004 אם \u0003רצה לחזור\u0004 — \u0003לא יחזור.\u0004","\u0003רבי אומר: בכולן אם רצה לחזור\u0004 — \u0003לא יחזור,\u0004 לפי שחל הגט מייד בשעה שהגיע לידי השליח. \u0003אבל אם אמר לו\u0004 לשליח במפורש: \u0003\"אי איפשי\u0004 (אין רצוני) \u0003שתקבל לה, אלא הולך ותן לה\",\u0004 אם \u0003רצה לחזור\u0004 — \u0003יחזור.\u0004","ותוהים: דעת \u0003רבי היינו תנא קמא\u0004 \u0005[זוהי\u0006 דעת \u0005התנא הראשון]!\u0006 ומשיבים: \u0003איבעית אימא\u0004 \u0005[אם רצונך לומר]:\u0006 לשון \u0003\"אי איפשי\" אתא לאשמועינן\u0004 \u0005[בא להשמיע לנו],\u0006 שאם הוא מסרב במפורש לעשותו שליח קבלה ועושה אותו שליח הולכה — הריהו מבטל את שליחותו הקודמת. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]:\u0006 \u0003מאן תנא קמא\u0004 \u0005[מיהו התנא הראשון]\u0006 — \u0003רבי\u0004 והרי זה כמפרש ואומר: שרבי אומר.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 ללומדים\u0005]:\u0006 בעל האומר \u0003\"הילך\"\u0004 (הא לך), \u0003ל\u0004דעת \u0003ר' נתן,\u0004 האם \u0003כ\"זכי\" דמי\u0004 \u0005[כאילו\u0006 אומר \u0005\"זכה\"\u0006 הוא \u0005נחשב]\u0006 ואינו יכול לחזור בו, \u0003או לאו כ\"זכי\" דמי\u0004 \u0005[לא כ\"זכה\"\u0006 הוא \u0005נחשב]?\u0006","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: \u0003האומר \"התקבל גט זה לאשתי\" או \"הולך גט זה לאשתי\",\u0004 אם \u0003רצה לחזור\u0004 — \u0003יחזור. האשה שאמרה: \"התקבל לי\u0004 \u0003גיטי\",\u0004 אם \u0003רצה\u0004 הבעל \u0003לחזור\u0004 — \u0003לא יחזור.\u0004"],["\u0003מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר \u0003ב\u0004מקרה שאמר לו הבעל לשליח \u0003\"הילך\", ו\u0004שיטת \u0003ר' נתן\u0004 היא? ודוחים: \u0003לא,\u0004 מדובר \u0003ב\u0004אומר \u0003\"הולך\" ו\u0004כשיטת \u0003רבי\u0004 שלדעתו בכל לשון שאמר הבעל אינו יכול לחזור.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו במשנתנו: \u0003לפיכך, אם אמר לו הבעל: \"אי אפשי\u0004 (אין רצוני) \u0003שתקבל לה אלא הולך ותן לה\",\u0004 אם \u0003רצה לחזור\u0004 — \u0003יחזור.\u0004 ונדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 ש\u0003אמר\u0004 במפורש \u0003\"אי אפשי\", הא\u0004 \u0005[הרי]\u0006 אם \u0003לא אמר \"אי אפשי\",\u0004 אם \u0003רצה לחזור\u0004 — \u0003לא יחזור.\u0004","\u0003מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר \u0003ב\"הילך\" ו\u0004כשיטת \u0003ר' נתן?\u0004 ודוחים: \u0003לא,\u0004 מדובר פה \u0003ב\"הולך\" ו\u0004כשיטת \u0003רבי.\u0004","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו בברייתא: בעל שאמר \u0003\"הולך גט זה לאשתי\",\u0004 אם \u0003רצה\u0004 הבעל \u0003לחזור בו\u0004 — \u0003יחזור,\u0004 \u0003\"הילך גט זה לאשתי\"\u0004 אם \u0003רצה לחזור\u0004 — \u0003לא יחזור. מאן\u0004 \u0005[מי]\u0006 \u0003שמעת ליה דאמר\u0004 \u0005[אותו שאומר]\u0006 \u0003ב\"הולך\",\u0004 שאם \u0003רצה לחזור\u0004 — \u0003יחזור?\u0004 — \u0003ר' נתן\u0004 הוא, \u0003וקאמר\u0004 \u0005[והוא אומר]\u0006 \u0003ב\"הילך\",\u0004 אם \u0003רצה לחזור\u0004 — \u0003לא יחזור, שמע מינה\u0004 \u0005[למד מכאן]\u0006 לדעתו ש\u0003\"הילך\" כ\"זכי\" דמי\u0004 \u0005[כ\"זכה\" נחשב],\u0006 ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן].\u0006","\u0003אתמר\u0004 \u0005[נאמר]:\u0006 אמרה האשה לשליח: \u0003\"התקבל לי גיטי\", ו\u0004השליח בא ואומר: \u0003\"אשתך אמרה התקבל לי גיטי\", והוא,\u0004 הבעל, \u0003אומר: \"הולך ותן לה\", אמר ר' אבא אמר רב הונא אמר רב: נעשה\u0004 השליח גם \u0003שלוחו\u0004 של הבעל להולכה \u0003ו\u0004גם \u0003שלוחה\u0004 של האשה לקבלה. ואם ימות הבעל בלי שיש לה ילדים ממנו בין הזמן שניתן הגט לשליח עד שהגיע לידה — הרי היא \u0003חולצת\u0004 לאחיו, שחוששים שמא אין דינה כמגורשת, וכדי להינשא לאחר צריכה חליצה, אבל אינה מתייבמת לאחי בעלה — שמא מגורשת היא, ואסורה עליו.","ושואלים: \u0003למימרא\u0004 \u0005[האם לומר]\u0006 \u0003דמספקא ליה\u0004 \u0005[שמסופק לו]\u0006 \u0003לרב אי\u0004 \u0005[האם]\u0006 \u0003\"הולך\" כ\"זכי\" דמי\u0004 \u0005[כ\"זכה\" נחשב]\u0006 \u0003אי לאו כ\"זכי\" דמי\u0004 \u0005[אם לא כ\"זכה\" נחשב]?\u0006 \u0003והא אתמר\u0004 \u0005[והרי נאמר]:\u0006 האומר לשליחו: \u0003\"הולך מנה\u0004 (מאה דינרים) \u0003לפלוני שאני חייב לו\", אמר רב: חייב\u0004 המשלח \u0003באחריותו\u0004 של מנה זה, ואם אבד — עדיין צריך לשלם את חובו לבעל החוב. \u0003ו\u0004למרות זאת \u0003אם בא\u0004 המשלח \u0003לחזור\u0004 בו ולקחת מנה זה מן השליח — \u0003אינו חוזר,\u0004 לפי שכבר זכה בו בעל החוב משעת ההולכה. משמע שברור לרב כי \"הולך\" דינו כ\"זכה\"!","ודוחים: יש לחלק בין הדברים: \u0003התם ספק ממונא לקולא\u0004 \u0005[שם ספק ממון]\u0006 הוא ופוסקים \u0003לקולא\u0004 \u0005[להקל],\u0006 ואין מוציאים ממון במקום שיש ספק, ואילו \u0003הכא ספק איסורא\u0004 \u0005[כאן ספק איסור]\u0006 הוא ופוסקים \u0003לחומרא\u0004 \u0005[לחומרה].\u0006","\u0003אמר רב: אין האשה עושה שליח לקבל לה גיטה מיד שליח בעלה, ור' חנינא אמר: אשה עושה שליח לקבל לה גיטה מיד שליח בעלה.\u0004","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003רב\u0004 שאומר שאינה עושה? ומשיבים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 \u0003משום בזיון של הבעל,\u0004 שנראה לבעל שהאשה מבזה אותו, ואינה רוצה לקבל את הגט במישרין משליחו, אלא מקבלת את גיטה על ידי שליח.","\u0003אי בעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 \u0003משום חצרה הבא לאחר מיכן,\u0004 שאם היה הבעל מניח את הגט בחצר שאינה שייכת לאשה, ואחר כך היתה האשה קונה את החצר — אינו גט, מפני שבשעת הנתינה לא נמסר לא לאשה ולא בחצירה של האשה, ומה שעבר אחר כך לרשותה — הרי זה כאילו מצאה את הגט מונח ונטלתו. אף כאן, השליח לקבלה שמינתה האשה (שנעשה לענין זה כידה או חצירה) נתמנה לאחר שנמסר הגט לשליח הבעל, ואם יתירו בכך יחשבו שאף בחצר שקנתה לאחר שנתן הבעל גט לתוכה, יועיל הגט.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה ההבדל\u0006 למעשה \u0005ביניהם]\u0006 בין שני הטעמים? ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005]\u0006 באופן ש\u0003קדמה איהי ושויה\u0004 \u0005[היא ומינתה]\u0006 \u0003שליח מעיקרא\u0004 \u0005[מתחילה]\u0006 לפני שמינה הבעל שליח להולכה, שאז אין כאן חשש משום חצר הבאה לאחר מכן, שאין הדברים דומים, אבל משום ביזיון הבעל יש מקום לחשוש.","מסופר: \u0003ההוא גברא דשדר לה גיטא לדביתהו\u0004 \u0005[איש אחד ששלח גט לאשתו],\u0006 \u0003אזל שליחא אשכחה כי יתבה וקא לישא\u0004 \u0005[הלך השליח מצאה שהיא יושבת ולשה],\u0006 \u0003אמר לה: \"הילך גיטך\", אמרה ליה\u0004 \u0005[לו]\u0006 שידיה מלוכלכות בבצק ולכן \u0003\"ליהוי בידך\"\u0004 \u0005[יהא\u0006 הגט \u0005בידך]\u0006 ותהא כשליח עבורי לקבלתו. \u0003אמר רב נחמן: אם איתא\u0004 \u0005[יש]\u0006 בסיס \u0003ל\u0004דברי \u0003ר' חנינא\u0004 והלכה כמותו, שאשה עושה שליח לקבל גט מיד שליח בעלה, \u0003עבדי בה עובדא\u0004 \u0005[הייתי עושה בה מעשה]\u0006 להתיר את האשה על ידי גט זה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: ואם איתא\u0004 \u0005[יש]\u0006 מקום \u0003ל\u0004דברי \u0003ר' חנינא, עבדת\u0004 \u0005[תעשה]\u0006 \u0003בה עובדא\u0004 \u0005[מעשה]?\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 במקרה הזה \u0003לא חזרה שליחות אצל הבעל,\u0004 שלא נגמרה השליחות עד כדי שיכול השליח לחזור למשלחו ולומר שביצע את שליחותו. שהרי לא גמר השליח את שליחותו של הבעל, וכבר נעשה שליח של האשה, ונמצא שביטל את שליחותו הראשונה ואם כן אין כאן שליחות ובטל הגט!","\u0003שלחוה לקמיה\u0004 \u0005[שלחו\u0006 את השאלה \u0005הזו לפני]\u0006 \u0003ר' אמי, שלח להו\u0004 \u0005[להם]:\u0006 \u0003לא חזרה שליחות אצל הבעל\u0004 ואינו גט. \u0003ור' חייא בר אבא אמר: נתיישב\u0004 (אחשוב) \u0003בדבר.\u0004","לאחר ימים אחדים \u0003הדור שלחוה קמיה\u0004 \u0005[חזרו ושלחוה\u0006 את השאלה \u0005לפני]\u0006 \u0003ר' חייא בר אבא, אמר: כל הני שלחו לה ואזלי\u0004 \u0005[כל כך\u0006 הרבה \u0005הולכים ושולחים לי]?\u0006 \u0003כי היכי דמספקא להו לדידהו, הכי נמי מספקא לן\u0004 \u0003לדידן\u0004 \u0005[כפי שמסופק הדבר להם, כך גם כן מסופק לנו,\u0006 לעצמנו\u0005]\u0006 ואיני יודע מה הפתרון.","ומסכמים: כיון שכך, שלא הוכרעה הבעיה, \u0003הוי\u0004 \u0005[הריהו]\u0006 ספק לגבי \u0003דבר שבערוה,\u0004 אם עדיין אשת איש היא, \u0003ו\u0004בכל מקום שיש ספק ב\u0003דבר שבערוה\u0004 — \u0003חולצת.\u0004 שמחמירים בה מפני הספק, ואם מת בעלה אין אומרים שמותרת לכל מחמת הגירושין, אלא תחלוץ לאחיו מספק, שמא לא בטלו נישואין אלה. ולא תתייבם — שאולי אכן חלו הגירושין, והריהי אסורה על היבם.","ומספרים: \u0003הוה עובדא\u0004 \u0005[היה מעשה]\u0006 כגון זה \u0003ואצרכה\u0004 \u0005[והצריכה]\u0006 \u0003רב יצחק בר שמואל בר מרתא\u0004 את האשה \u0003גט\u0004 נוסף מבעלה, וחליצה. ושואלים: \u0003תרתי\u0004 \u0005[שני]\u0006 דברים סותרים? שאם חזר ונתן לה בעלה גט — ודאי אינה צריכה עוד חליצה! ומסבירים: \u0003גט\u0004 הצריך אותה \u0003מחיים,\u0004 שאם הבעל עודנו חי — יחזור ויתן לה גט, \u0003וחליצה לאחר מיתה,\u0004 שאם לא הספיק לתת לה גט ומת — תחלוץ.","מסופר: \u0003ההיא דהוו קרו\u0004 \u0005[\u0006אשה \u0005אחת שהיו קוראים]\u0006 \u0003לה נפאתה,\u0004 וציווה בעלה לכתוב לה גט ולגרשה בו, \u0003אזול סהדי כתוב\u0004 \u0005[הלכו העדים וכתבו]\u0006 בגט בטעות \u0003תפאתה, אמר רב יצחק בר שמואל בר מרתא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב:\u0004 גט זה עצמו פסול, ואילו לכתוב שוב גט כתיקונו אין הם יכולים, שכן עשו \u0003עדים שליחותן,\u0004 שכבר מילאו וסיימו את שליחותם.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבה: מי קאמר להו \"כתובו חספא והבו לה\"\u0004 \u0005[האם\u0006 הבעל אמר להם \u0005\"כתבו חרס,\u0006 דבר ללא ערך, \u0005ותנו לה\"]?\u0006 הרי אמר להם לכתוב לה גט כראוי, וכל עוד לא נכתב גט כשר על ידם, הרי אלו עדיין לא מילאו את שליחותם! \u0003אלא אמר רבה: ודאי, אי כתוב סהדי גיטא מעליא\u0004 \u0005[אם כתבו העדים גט מעולה]\u0006 \u0003ואבד,\u0004 אז אומרים אנו ש\u0003עשו עדים שליחותן\u0004 ואינם רשאים לכתוב גט חדש. אך אין אומרים כך אם כתבו גט פסול.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב נחמן: מי קאמר להו\u0004 \u0005[האם אמר להם]\u0006 \u0003\"כתבו ואנחוה בכיסייכו\u0004 \u0005[והניחו אותו בכיסכם]\"?\u0006 הרי הורה להם לכתוב ולגרש בו, ובעצם הכתיבה לא נתמלאה שליחותם! \u0003אלא אמר רב נחמן:\u0004 בכל מקרה כזה \u0003כותבין\u0004 העדים גט חדש \u0003ונותנין, אפילו מאה פעמים.\u0004","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רבא מרב נחמן:\u0004 אמר הבעל לעדים \u0003\"כתבו ותנו לשליח\u0004 את הגט \u0003\"\u0004, \u0003מהו?\u0004 האם נאמר כי \u0003סלוקי סליק להו\u0004 \u0005[סילק אותם]\u0006 משליחותם לאחר שנתנו את הגט לשליח, ושוב אינם יכולים לכתוב גט אחר, \u0003או דילמא לטירחא דידהו חייש\u0004 \u0005[שמא\u0006 רק \u0005לטירחה שלהם חשש],\u0006 שלא יצטרכו למסור את הגט בעצמם, אבל שליחותם קיימת ויכולים הם לחזור ולכתוב גט, אם יהיה צורך בדבר, עד שתתגרש האשה?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי\u0004 בהמשך לשאלה הקודמת: אם אמר הבעל לעדים \u0003\"\u0004כתבו ותנו לשליח \u0003ויוליך לה\", מהו?\u0004 האם ממה שהוסיף \"ויוליך לה\" מוכח שנתכוון לומר שעדים אלה צריכים לדאוג שאכן יוליך לה השליח ויגיע לידה, ולפיכך קיימת שליחותם עד שיגיע הגט בפועל לידיה, או שמא אין זו משמעות דבריו, ובטלה שליחותם עם הכתיבה? שאלות אלה לא נפתרו ונשארו ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","שנינו במשנה ש\u0003רבן שמעון בן גמליאל אומר: אף האומרת \"טול לי גיטי\", אם רצה\u0004 הבעל \u0003לחזור\u0004 — \u0003לא יחזור,\u0004 שהרי הוא שליח לקבלה, וכבר נתגרשה האשה כשהגיע הגט לידו. ומביאים: כיוצא בזה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 אם אמרה האשה לשליח אחד מלשונות אלה: \u0003\"טול לי\",\u0004 או \u0003\"שא לי\",\u0004 או \u0003\"יהא לי בידך\"\u0004 — \u0003כולן לשון קבלה הן,\u0004 שנתכוונה שיהא שליח לקבלה, ותתגרש משהגיע הגט לידו.","\u0003האשה שאמרה\u0004 לשליח: \u0003\"התקבל\u0004 (תהיה שליח לקבל) \u0003לי גטי\"\u0004 — \u0003צריכה\u0004 כדי לאשר שהיא אכן התגרשה על ידי קבלתו של אותו שליח \u0003שתי כיתי\u0004 (קבוצות) \u0003עדים,\u0004 כת אחת של \u0003שנים\u0004 עדים \u0003שאומרים:\u0004 \u0003\"בפנינו אמרה\u0004 לשליח לקבל עבורה את הגט \u0003\",\u0004 \u0003ושנים\u0004 נוספים שאומרים: \u0003\"בפנינו קבל\u0004 השליח את הגט \u0003וקרע\".\u0004 אבל שתי העדויות הללו אין צורך שתהיינה דווקא בשתי קבוצות נבדלות, אלא \u0003אפילו הן\u0004 אותם העדים \u0003הראשונים והן האחרונים\u0004 מעידים על שני הדברים,"],["\u0003או אחד מן\u0004 כת \u0003הראשונים ואחד מן\u0004 כת \u0003האחרונים\u0004 מעידים, \u0003ואחד\u0004 נוסף \u0003מצטרף עמהן\u0004 בשתי העדויות.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו בשאלה זו: \u0003בעל אומר\u0004 שהגט שנתן בידי אדם אחר היה \u0003לפקדון\u0004 בלבד ולא לגירושין, ואין האשה מגורשת, \u0003ושליש\u0004 (מי שהושלש, הופקד, בידו) \u0003אומר\u0004 שהגט ניתן לו \u0003ל\u0004שם \u0003גירושין, מי\u0004 מהם \u0003נאמן? רב הונא אמר: בעל נאמן, ורב חסדא אמר: שליש נאמן.\u0004","ומסבירים את שיטותיהם: \u0003רב הונא אמר בעל נאמן,\u0004 ש\u0003אם\u0004 \u0003איתא\u0004 \u0005[יש]\u0006 מקום לומר ש\u0003לגירושין יהביה ניהליה\u0004 \u0005[נתן אותו לו\u0006 לשליש\u0005],\u0006 \u0003לדידה הוה יהיב לה ניהלה\u0004 \u0005[לה עצמה היה נותן\u0006 את הגט\u0005]\u0006 ומדוע הוצרך לשליש? אלא ודאי רצה רק להפקיד את הגט בידו. \u0003ורב חסדא אמר: שליש נאמן, דהא\u0004 \u0005[שהרי]\u0006 הבעל עצמו \u0003הימניה\u0004 \u0005[האמין לו],\u0006 ונתן לו ביד ייפוי כוח גמור.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003ר' אבא\u0004 לרב הונא ממה ששנינו: \u0003הודאת בעל דין כמאה עדים דמי\u0004 \u0005[נחשבת],\u0006 \u0003ושליש נאמן משניהם,\u0004 משני הצדדים המתדיינים ביניהם, \u0003כיצד?\u0004 אם צד \u0003זה אומר\u0004 שחייב לו \u0003כך,\u0004 סכום מסויים, \u0003וזה,\u0004 הצד השני, \u0003אומר כך,\u0004 שחייב פחות מכן, \u0003שליש\u0004 שנתנו בידו את הכסף שימסרנו לבעל החוב \u0003נאמן\u0004 לומר מה היה החוב, וקשה מכאן לשיטת רב הונא שאמר שהבעל נאמן ולא השליש!","ודוחים: מכאן אין להוכיח, שכן \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003ממון, דאיתיהיב\u0004 \u0005[שניתן]\u0006 \u0003למחילה,\u0004 שכיון שנתן המלווה לשליח האמין לו וסמך עליו, וגם אם השליח שינה מן הדברים — הרי זה ממון בלבד, וניתן למחילה, והרי זה כאילו מחל לו מראש. ואין להוכיח מכאן לענין גיטין, שאין בכוח אחד מהם לשנות את העובדות על ידי ויתור.","ומקשים: \u0003והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003וכן\u0004 הוא הדין, שנאמן השליש, \u0003לגיטין!\u0004 ומשיבים: אין הכוונה לגיטין של גירושין אלא ל\u0003גיטי ממון,\u0004 כלומר, סתם שטרות. ומקשים על כך: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 אחרת: \u0003וכן לשטרות,\u0004 ואם כן האמור \"וכן לגיטין\" אמור בגיטי נשים, שהרי לא היה נשנה אותו דין פעמיים בלשונות שונות!","ודוחים: \u0003מידי גבי הדדי תניא\u0004 \u0005[וכי זו אצל זו\u0006 הן \u0005שנויות]\u0006 אילו היה נאמר בברייתא אחת \"וכן לגיטין וכן לשטרות\", היה ברור שגיטין הם גיטי נשים ושטרות הם שאר שטרות, אבל כיון שאלה הן שתי ברייתות נבדלות, שמא האחת קוראת לשטרות גיטין, והשניה קוראת להם שטרות.","ומנסים להביא ראיה ממשנתנו, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005],\u0006 \u0003האשה שאמרה: \"התקבל לי גיטי\"\u0004 — \u0003צריכה שתי כיתי עדים, שנים שיאמרו: \"בפנינו אמרה\", ושנים שיאמרו: \"בפנינו קבל וקרע\". ואמאי\u0004 \u0005[ומדוע]?\u0006 \u0003ליהמניה\u0004 \u0005[שיאמינו לו]\u0006 \u0003לשליש\u0004 שמסר הבעל לידו את הגט, שיהא נאמן בדיבורו בלבד, בלא עדים!","ודוחים: \u0003מי קא נפיק גיטא\u0004 \u0005[האם יוצא הגט]\u0006 \u0003מתותי ידיה דליהמניה\u0004 \u0005[מתחת ידו שנאמין לו]?\u0006 שהרי השליש נאמן רק כאשר הדבר שעליו דנים נמצא בידו, שכיון שבכוחו לעשות בו כרצונו, נאמן בדיבורו. אבל כאן — הלא כבר אין הגט בידו, ואין לו עוד דין שליש ונאמנות של שליש.","ומקשים: \u0003תינח\u0004 \u0005[נניח]\u0006 שצריכים עדים ש\u0003אמרה,\u0004 שמינתה אותו שליח, אבל עדים שיעידו ש\u0003קיבל למה לי?\u0004 הלא הגט מצוי בידו, ואין צריך להעיד על כך! \u0003אמר רבה: הא מני\u0004 \u0005[זו\u0006 כשיטת \u0005מי היא]?\u0006 שיטת \u0003ר' אלעזר היא,\u0004 ש\u0003אמר: עדי מסירה כרתי\u0004 \u0005[כורתים],\u0006 כלומר, עיקר חלות הגט הוא במסירתו בעדים, ולכן יש צורך בעדות על מסירת הגט בשעה שבה הוא חל.","ותוהים לעצם פירוש הדברים במשנה: \u0003קרע למה לי?\u0004 מדוע צריך השליש לקרוע את הגט? \u0003אמר רב יהודה אמר רב: בשעת הגזירה שנו,\u0004 שאסרה המלכות לכתוב גיטין, ולכן מייד אחר שחל הגט היו קורעים אותו, כדי שלא תהא הוכחה ביד השלטונות.","\u0003אמר רבה: ומודה רב הונא,\u0004 אף שאמר שהבעל נאמן, \u0003דאי אמרה איהי\u0004 \u0005[שאם אומרת היא]\u0006 האשה: \u0003לדידי\u0004 \u0005[לי עצמי]\u0006 \u0003אמר לי\u0004 ה\u0003שליש\u0004 ש\u0003לגירושין יהביה ניהליה\u0004 \u0005[נתן אותו\u0006 בעלי \u0005לו]\u0006 — \u0003מהימנא\u0004 \u0005[נאמנת].\u0006 ותוהים על דברי רבה: \u0003מי איכא מידי\u0004 \u0005[האם יש דבר],\u0006 ש\u0003שליש גופיה\u0004 \u0005[עצמו]\u0006 \u0003לא מהימן\u0004 \u0005[נאמן]\u0006 לדעת רב הונא, \u0003ואיהי מהימנא\u0004 \u0005[והיא נאמנת]\u0006 כשאומרת בשם השליש?","\u0003אלא,\u0004 כך אמר רבה: מודה רב הונא ש\u0003אי אמרה קמאי דידי\u0004 \u0005[אם היתה אומרת: בפני שלי]\u0006 \u0003לגרושין יהביה ניהליה\u0004 \u0005[נתן אותו לו]\u0006 — \u0003מהימנא\u0004 \u0005[נאמנת],\u0006 והטעם: \u0003מיגו דאי בעיא אמרה לדידה יהביה ניהליה בעל\u0004 \u0005[מתוך שאם היא רוצה\u0006 היתה יכולה \u0005לומר\u0006 ש\u0005לה עצמה נתן אותו הבעל]\u0006 ונתגרשה בו, על כן כשהיא אומרת שנתנו הבעל לשליח לשם גירושין — נאמנת.","ועוד דיון בנושא דומה, \u0003בעל אמר\u0004 שנתן לשליח גט \u0003ל\u0004שם \u0003גירושין, ו\u0004אף \u0003שליש אומר\u0004 ש\u0003לגירושין\u0004 נמסר לו, \u0003והיא אומרת: נתן לי\u0004 השליח את הגט, \u0003ו\u0004אולם \u0003אבד\u0004 הגט, \u0003אמר ר' יוחנן: הוה\u0004 \u0005[הרי זה]\u0006 ספק שאירע ב\u0003דבר שבערוה, ואין דבר שבערוה\u0004 נגמר \u0003פחות משנים\u0004 המעידים על כך.","ושואלים: \u0003ואמאי\u0004 \u0005[ומדוע]?\u0006 \u0003וליהימניה\u0004 \u0005[ושיאמינו לו]\u0006 \u0003לשליש\u0004 שמסר אותו, שהרי אמרנו שהוא נאמן משניהם! ואומרים: \u0003מי קא נפיק גיטא מתותי ידיה דלהימניה\u0004 \u0005[האם יוצא גט מתחת ידו שנאמין לו]?\u0006","ומקשים: \u0003ולהימניה\u0004 \u0005[ושיאמינו לו]\u0006 \u0003לבעל,\u0004 שהרי \u0003אמר רב חייא בר אבין אמר ר' יוחנן: בעל שאמר \"גירשתי את אשתי\"\u0004 — \u0003נאמן!\u0004 ודוחים: \u0003מי קאמר\u0004 \u0005[האם אומר]\u0006 הבעל במקרה זה \u0003גירשתי?\u0004 הלא הוא אומר רק שמסר לשליח!","ומקשים עוד: \u0003ולימא\u0004 \u0005[ונאמר]\u0006 ונסמוך על מה שאמרו: \u0003חזקה שליח עושה שליחותו!\u0004 ש\u0003אמר ר' יצחק, האומר לשלוחו: \"צא וקדש לי אשה\" סתם,\u0004 איזו שהיא, \u0003ומת שלוחו\u0004 ואין האיש יודע אם קידש אשה ואת מי קידש — \u0003אסור\u0004 האיש \u0003בכל הנשים שבעולם,\u0004 שהרי על כל אשה יש מקום לחשוש שמא היא אחות או בת או קרובה אחרת של אותה אשה שהשליח קידש, ולכן אנו אוסרים עליו לשאת כל אשה. ודבר זה נסמך על ההנחה שהשליח אכן קידש אשה כלשהי, כי \u0003חזקה שליח עושה שליחותו,\u0004 ונמצא שאף בדבר שבערווה סומכים על חזקה זו!"],["ומשיבים: \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא \u0003לחומרא\u0004 \u0005[להחמיר]\u0006 שלענין זה חוששים משום שחזקה ששליח עשה שליחותו, \u0003אבל לקולא\u0004 \u0005[להקל]\u0006 \u0003לא\u0004 סומכים על כך.","ושואלים: \u0003וליהמנה לדידה\u0004 \u0005[ושנאמין לה עצמה]\u0006 \u0003מ\u0004תוך דברי \u0003רב המנונא,\u0004 ש\u0003אמר רב המנונא: האשה שאמרה לבעלה \"גירשתני\"\u0004 — הרי היא \u0003נאמנת,\u0004 שכן \u0003חזקה אין האשה מעיזה פניה בפני בעלה\u0004 לשקר בדבר כגון זה!","ומשיבים: \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא \u0003היכא דליכא דקא\u0004 \u0005[במקום שאין דבר]\u0006 ש\u0003מסייע לה,\u0004 ואין אנו מניחים שתתחצף לשקר לגמרי, \u0003אבל היכא\u0004 \u0005[במקום]\u0006 שיש אדם ה\u0003מסייע לה,\u0004 שהרי הבעל עצמו אומר ששלח גט ואף השליש אומר כן — \u0003מעיזה ומעיזה\u0004 פנים, ואינה נאמנת על פי דבריה בלבד, אלא כשגיטה בידה.","\u0003נערה המאורסה, היא\u0004 עצמה או \u0003אביה\u0004 \u0003מקבלין את גיטה,\u0004 ומשעה שקיבל אחד מהם את הגט — הריהי מגורשת. \u0003אמר ר' יהודה: אין שתי ידים זוכות כאחת,\u0004 שלא ייתכן שלגבי אדם אחד יהיו שתי \"ידיים\" של יכולת זכייה. \u0003אלא אביה מקבל את גיטה בלבד. ו\u0004עוד כלל גדול אמרו: \u0003כל\u0004 אשה \u0003שאינה יכולה לשמור את גיטה, אינה יכולה להתגרש.\u0004","ומבררים: \u0003במאי קמיפלגי\u0004 \u0005[במה,\u0006 באיזה עקרון \u0005נחלקו]\u0006 חכמים (סתם משנה) ור' יהודה במשנתנו? — \u0003רבנן סברי\u0004 \u0005[חכמים סבורים]:\u0006 \u0003ידא יתירתא זכי לה רחמנא\u0004 \u0005[יד יתירה זכתה לה התורה],\u0006 כלומר, נתנה התורה גם לה זכות לקבל את גיטה, אף שיד אביה כידה, והוא יכול לקבלו עבורה. \u0003ור' יהודה סבר: במקום אביה,\u0004 כאשר האב קיים, \u0003יד דילה\u0004 \u0005[שלה]\u0006 \u0003לאו\u0004 \u0005[לא]\u0006 \u0003כלום היא,\u0004 אינה נחשבת, ולכן אין היא יכולה לקבל גיטה.","שנינו במשנה ש\u0003כל\u0004 אשה \u0003שאינה יכולה לשמור את גיטה\u0004 אינה יכולה להתגרש. ובענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003קטנה היודעת לשמור את גיטה\u0004 — \u0003מתגרשת, ושאינה יודעת לשמור את גיטה\u0004 — \u0003אינה מתגרשת. ואיזו היא קטנה\u0004 שנחשבת \u0003כיודעת לשמור את גיטה?\u0004 \u0003כל שמשמרת גיטה ודבר אחר.\u0004","ותוהים: \u0003מאי קאמר\u0004 \u0005[מה אמר],\u0006 מה משמעות הדבר שמשמרת את גיטה ודבר אחר? \u0003אמר ר' יוחנן, הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003כל שמשמרת דבר אחר מחמת גיטה,\u0004 כגון שאבד לה גיטה עצמו, והיא שומרת דבר אחר משום שהיא סבורה שהוא הגט.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב הונא בר מנוח: הא\u0004 \u0005[זו]\u0006 \u0003שוטה בעלמא\u0004 \u0005[סתם]\u0006 \u0003היא,\u0004 שמשמרת דבר אחר משום גיטה! \u0003אלא אמר רב הונא בר מנוח משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא:\u0004 הכוונה היא, \u0003כל שמבחנת בין גיטה לדבר אחר,\u0004 ושומרת את גיטה ולא דבר אחר.","ובאותו ענין של תינוקות \u0003אמר רב יהודה אמר ר' אסי:\u0004 תינוק שנותנים לו \u0003צרור\u0004 (אבן) \u0003וזורקו\u0004 משום שמבין כי הוא חסר ערך, אבל אם נותנים לו \u0003אגוז\u0004 הריהו מכיר בו \u0003ונוטלו\u0004 — הריהו \u0003זוכה\u0004 בדברים \u0003לעצמו,\u0004 אבל \u0003אין זוכה לאחרים\u0004 שאינו יכול לזכות עבור אחרים. אבל אם הילד יש בו דעת עד כדי כך שנותנים לו \u0003חפץ ומחזירו\u0004 לבעליו \u0003לאחר שעה,\u0004 משום שמבין שהחפץ שייך לו — \u0003זוכה\u0004 בדברים \u0003בין לעצמו ובין לאחרים.\u0004","\u0003כי אמריתה\u0004 \u0005[כאשר אמרתי ]\u0006 את הדבר הזה של ר' אסי \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003שמואל, אמר לי: דא ודא\u0004 \u0005[זו וזו]\u0006 \u0003אחת היא.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"דא ודא\u0004 \u0005[זו וזו]\u0006 \u0003אחת היא\"?\u0004 \u0003אמר רב חסדא: אחד זה ואחד זה\u0004 — \u0003זוכה לעצמו ואין זוכה לאחרים,\u0004 ואין מבחינים בדרגות הבנה שונות של הקטן.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב חיננא וורדאן\u0004 (מהעיר וורדוניא) ממה ששנינו: \u0003כיצד\u0004 בני המבוי \u0003משתתפין במבוי\u0004 כדי לאפשר להם לטלטל בתוכו בשבת? — \u0003מניח\u0004 אדם אחד \u0003את החבית\u0004 שמכילה יין או שמן שייעד אותה לצורך זה, \u0003ואומר: \"הרי זו\u0004 החבית שייכת \u0003לכל בני המבוי\", ומזכה להם,\u0004 לכל אחד ואחד את חלקו, \u0003על ידי בנו ובתו הגדולים\u0004 שהם יכולים לזכות עבור אחרים, \u0003ועל ידי עבדו ושפחתו העברים.\u0004","ונברר: \u0003האי\u0004 \u0005[אותה]\u0006 \u0003שפחה\u0004 הנזכרת כאן \u0003היכי דמי\u0004 \u0005[כיצד בדיוק מדובר\u0006 בה\u0005]?\u0006 \u0003אי דאתיא\u0004 \u0005[אם ש\u0006כבר \u0005הביאה]\u0006 \u0003שתי שערות\u0004 במקום הערווה, והרי הן סימן להיותה בוגרת, \u0003מאי בעיא גביה\u0004 \u0005[מה\u0006 היא \u0005עושה אצלו]?\u0006 הרי אמה עבריה משתחררת מיד בסימנים אלו מן העבדות! \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר כאן ש\u0003לא אתיא\u0004 \u0005[הביאה]\u0006 עדיין \u0003שתי שערות,\u0004 ועדיין קטנה היא, \u0003וקתני\u0004 \u0005[ושנה]\u0006 שהיא \u0003זוכה לאחרים,\u0004 משמע שקטן יכול לזכות גם לאחרים!","ודוחים: מכאן אין להוכיח, כי \u0003שאני\u0004 \u0005[שונים]\u0006 \u0003שיתופי מבואות\u0004 שהם כולם \u0003דרבנן\u0004 \u0005[מדברי סופרים],\u0006 וחכמים עצמם הקלו בדבר, שקטן יזכה גם לאחרים.","\u0003אמר רב חסדא: אישתיק\u0004 \u0005[שתק]\u0006 \u0003וורדאן\u0004 ולא ענה על כך. ושואלים: \u0003מאי הוה ליה למימר\u0004 \u0005[מה היה לו לומר,\u0006 לענות\u0005]?\u0006 ומשיבים: היה יכול לענות: \u0003כל\u0004 דבר \u0003דתקון רבנן\u0004 \u0005[שתקנו חכמים]\u0006 —"],["\u0003כעין דאורייתא תקון\u0004 \u0005[של תורה תקנו]\u0006 ולא יצרו הלכות שונות לגמרי.","\u0003ואידך\u0004 \u0005[והאחר]\u0006 ר' חיננא וורדאן מדוע שתק? סבור הוא \u0003כי אמרינן\u0004 \u0005[כאשר אנו אומרים]\u0006 \u0003כל דתקון רבנן\u0004 \u0005[שתקנו חכמים]\u0006 \u0003כעין דאורייתא תקון\u0004 \u0005[של תורה תקנו]\u0006 הרי זה דווקא \u0003במילתא דאית לה\u0004 \u0005[בדבר שיש לו]\u0006 \u0003עיקר מן התורה\u0004 וחכמים הוסיפו בו תקנות, \u0003אבל מילתא דלית לה\u0004 \u0005[דבר שאין לו]\u0006 \u0003עיקר מן התורה\u0004 כמו דין עירוב — \u0003לא\u0004 התקינו בו שיהא כעין דין תורה.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב אויא\u0004 עוד על דברי שמואל, וכפי שפירשם רב חסדא שאין קטן זוכה עבור אחרים, ממה ששנינו: \u0003מערימין על מעשר שני\u0004 כדי שלא יצטרך הפודה אותו להוסיף חומש על מחירו. שכן אם בעל המעשר עצמו הוא הפודה — חייב להוסיף חומש. \u0003כיצד?\u0004 — \u0003אומר אדם לבנו ובתו הגדולים,\u0004 או \u0003לעבדו ושפחתו העברים: \"הא לכם מעות הללו ופדו בהן מעשר שני זה\"\u0004 ולאחר שפדוהו נותנים לו את המעשר \u0003ואוכלו, בלא\u0004 להוסיף \u0003חומש\u0004 עליו.","ונברר: \u0003האי\u0004 \u0005[זו]\u0006 ה\u0003שפחה\u0004 שמדובר בה כאן \u0003היכי דמי\u0004 \u0005[כיצד בדיוק הדבר]?\u0006 \u0003אי דאתיא\u0004 \u0005[אם ש\u0006כבר \u0005הביאה]\u0006 \u0003שתי שערות, מאי בעיא גביה\u0004 \u0005[מה\u0006 היא \u0005עושה אצלו],\u0006 שהרי היא משתחררת בסימני בגרות? \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 המדובר ש\u0003לא אתיא\u0004 \u0005[הביאה]\u0006 \u0003שתי שערות?\u0004 ומכאן משמע שאף קטנה יכולה לזכות עבור אחרים! ודוחים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003במעשר בזמן הזה\u0004 שהוא רק \u0003דרבנן\u0004 \u0005[מדברי סופרים],\u0006 ובזה חכמים עצמם הקלו.","ושואלים: \u0003ואמה העבריה בזמן הזה מי איכא\u0004 \u0005[האם יש]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אין עבד עברי נוהג אלא בזמן שהיובל נוהג.\u0004 ואם כן כבר בטל דין עבד עברי עוד לפני ימי בית שני, וכל שכן בזמן הזה! \u0003אלא\u0004 צריכים לומר שאף שמדובר בזמן שדין יובל נוהג, מכל מקום כאן מדובר במעשר שני כזה שבא מצמחים שגדלו \u0003בעציץ שאינו נקוב,\u0004 שכל חיובו הוא רק \u0003דרבנן\u0004 \u0005[מדברי סופרים].\u0006","ועוד, בענין זה של זכיית קטנים \u0003אמר רבא, שלש מדות\u0004 (מדרגות) יש \u0003בקטן:\u0004 קטן כזה שאם נותנים לו \u0003צרור וזורקו, אגוז ונוטלו\u0004 — \u0003זוכה לעצמו ואין זוכה לאחרים, וכנגדן\u0004 ברמה זו של הבנה \u0003בקטנה\u0004 — הרי היא \u0003מתקדשת\u0004 על ידי בני משפחתה (כגון אמה ואחיה) קידושין מדברי סופרים, שהתרתם צריכה \u0003למיאון.\u0004","וסוג אחר הוא \u0003הפעוטות\u0004 — \u0003מקחן מקח וממכרן ממכר במטלטלין, וכנגדן בקטנה\u0004 — \u0003מתגרשת בקידושי אביה,\u0004 שגם כאשר קיבל אביה את הקידושין עבורה, שאז קידושיה מדין תורה, מתגרשת כאשר היא מקבלת בעצמה גט.","הסוג השלישי, כאשר \u0003הגיעו לעונת נדרים\u0004 — \u0003נדריהן נדר והקדשן הקדש,\u0004 \u0003וכנגדן בקטנה\u0004 — \u0003חולצת.\u0004 \u0003ו\u0004לענין זכותו של אדם \u0003למכור\u0004 קרקעות \u0003בנכסי אביו\u0004 — אין זה חל \u0003עד שיהא בן עשרים\u0004 שנה.","\u0003קטנה שאמרה\u0004 לשליח: \u0003\"התקבל לי גיטי\"\u0004 — \u0003אינו גט עד שיגיע גט לידה\u0004 ממש, \u0003לפיכך, אם רצה הבעל לחזור\u0004 ולבטל את הגט — \u0003יחזור\u0004 כל עוד לא הגיע הגט לידה. וטעמו של דבר — \u0003שאין קטן עושה שליח,\u0004 וממילא אין השליח נחשב שליח קבלה שהאשה מתגרשת עם קבלת הגט, אלא שליח הולכה של הבעל בלבד, ומתגרשת בגט רק כשמקבלתו מידו.","\u0003ואם אמר לו,\u0004 לשליח, \u0003אביה\u0004 של הקטנה: \u0003\"צא והתקבל לבתי גיטה\", אם רצה\u0004 הבעל \u0003לחזור\u0004 — \u0003לא יחזור.\u0004 שכן האב, שיכול לקבל גט עבור בתו, יכול למנות שליח קבלה, ונתגרשה הקטנה עם קבלת הגט על ידי השליח.","ועוד בענייני שליחות הגט, \u0003האומר\u0004 לשליח: \u0003\"תן גט זה לאשתי במקום פלוני\",\u0004 ושינה השליח בשליחותו \u0003ונתנו לה במקום אחר\u0004 — הרי זה \u0003פסול.\u0004 אבל אם אמר לו: \u0003\"הרי היא במקום פלוני\",\u0004 ולא הורה במפורש שיתננו לה שם, \u0003ונתנו לה במקום אחר\u0004 — \u0003כשר.\u0004","\u0003האשה שאמרה\u0004 לשליח קבלה בעת שמינתה אותו לשליח עבורה: \u0003\"התקבל לי גיטי במקום פלוני\", וקיבלו לה במקום אחר\u0004 — \u0003פסול,\u0004 ו\u0003ר' אלעזר מכשיר.\u0004 אבל אם אמרה לו: \u0003\"הבא לי גיטי ממקום פלוני\", והביאו לה ממקום אחר\u0004 — \u0003כשר,\u0004 שבשליחות הולכה אין האשה מקפידה באיזה מקום ניתן הגט לשליח, שהרי הגירושין חלים רק כשהגט מגיע לידה, במקומה.","לגבי האמור במשנה בשליח ששינה מקום מסירת הגט, שואלים: \u0003ור' אלעזר, מאי שנא רישא\u0004 \u0005[\u0006ב\u0005מה שונה\u0006 ב\u0005תחילה]\u0006 ששינה מדברי הבעל \u0003דלא פליג\u0004 \u0005[שאינו חולק]\u0006 על סתם משנה, ופוסל, \u0003ומאי שנא סיפא\u0004 \u0005[ומה שונה\u0006 ב\u0005סוף]\u0006 \u0003דפליג\u0004 \u0005[שחולק]\u0006 ומכשיר גם אם הביא השליח את גיטה ממקום אחר מזו שאמרה האשה?","ומשיבים: \u0003איהו דמדעתיה\u0004 \u0005[הוא,\u0006 האיש, \u0005שמדעתו]\u0006 הוא \u0003מגרש\u0004 את אשתו — \u0003קפיד\u0004 \u0005[מקפיד]\u0006 שיהו הגירושין במקום מסויים דווקא, ואולם \u0003איהי\u0004 \u0005[היא]\u0006 ש\u0003בעל כרחה\u0004 היא \u0003מתגרשת\u0004 — רק \u0003מראה מקום היא לו,\u0004 ואינה יכולה להקפיד שיהא דווקא במקום מסויים.","אשה שהיתה בת ישראל הנשואה לכהן, וכל עוד היא אשתו היא אוכלת תרומה, שאמרה לשליח: \u0003\"הבא לי גיטי\",\u0004 שמינתה אותו רק כשליח הולכה להביא לידיה את הגט — הרי זו \u0003אוכלת בתרומה\u0004 מכוח בעלה הכהן \u0003עד שיגיע גט לידה.\u0004 אבל אם אמרה \u0003\"התקבל לי גיטי\"\u0004 שיהא הוא שליח לקבלה עבורה, ומתגרשת היא בקבלתו את הגט — \u0003אסורה לאכול בתרומה מיד,\u0004 שמא מצא את הבעל במקום סמוך, ומייד כשהגיע הגט לידו היא גרושה, ואסורה לאכול בתרומה לפי ששוב אינה אשת כהן. אמרה לו: \u0003\"התקבל לי גיטי במקום פלוני\"\u0004 — הריהי \u0003אוכלת בתרומה עד שיגיע גט לאותו מקום, ר' אלעזר אוסר\u0004 עליה לאכול \u0003מיד.\u0004","על האמור במשנה שאם אמרה לשליח שיקבל עבורה את גיטה במקום פלוני אוכלת בתרומה עד שיגיע הגט לשם, שואלים: \u0003וגיטא מיהא הוי\u0004 \u0005[וגט הוא מכל מקום]\u0006 בשעה שיגיע לשם אף על פי שקיבל השליח את הגט במקום אחר? \u0003והאמרת רישא\u0004 \u0005[והרי אמרת\u0006 ב\u0005תחילה],\u0006 במשנה הקודמת, שבמקרה שמשנה השליח מדבריה \u0003לא הוי גיטא\u0004 \u0005[אינו גט]\u0006 כלל!","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה],\u0006 אלא במקרה ש\u0003אמרה ליה\u0004 \u0005[לו]\u0006 כך: \u0003\"התקבל לי גיטא\u0004 \u0005[את ה\u0006\u0005גט]\u0006 \u0003ב\u0004עיר \u0003מתא מחסיא, וזימנין דמשכחת ליה\u0004 \u0005[ופעמים שתמצא אותו]\u0006 \u0003ב\u0004עיר \u0003בבל\".\u0004 \u0003והכי קאמרה ליה\u0004 \u0005[וכך אמרה לו]\u0006 זו היא משמעות דבריה: \u0003\"משקל כל היכא דמשכחת ליה שקליה מיניה\u0004 \u0005[לקחת\u0006 את הגט, \u0005בכל מקום שאתה מוצא אותו קח אותו ממנו],\u0006"],["ואולם \u0003גיטא לא הוי עד דמטית\u0004 \u0005[לא יהא\u0006 זה \u0005גט עד שאתה מגיע]\u0006 \u0003למתא מחסיא.\u0004","שנינו במשנה: שכאשר אמרה האשה לשליח \"התקבל לי גיטי במקום פלוני\" ש\u0003ר' אלעזר אוסר\u0004 עליה לאכול \u0003מיד.\u0004 ומקשים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 \u0003דהא\u0004 \u0005[שהרי]\u0006 לפי סברתו שלו רק \u0003מראה מקום היא לו,\u0004 ולא אמרה לו שיקבלנו דווקא במקום מסויים וממילא מובן שנאסרת בתרומה מיד!","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה],\u0006 אלא לאופן \u0003דאמרה ליה\u0004 \u0005[שאומרת לו]:\u0006 \u0003זיל\u0004 \u0005[לך]\u0006 \u0003למזרח דאיתיה\u0004 \u0005[ש\u0006הוא \u0005ישנו]\u0006 \u0003במזרח, וקא אזל\u0004 \u0005[והוא הלך]\u0006 \u0003ל\u0004צד \u0003מערב, מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003במערב הא ליתיה\u0004 \u0005[הרי איננו],\u0006 ובוודאי לא ימצאנו שם, ולא יהא גט עד לאחר זמן, על כן \u0003קא\u0004 \u0003משמע לן\u0004 \u0005[השמיע לנו],\u0006 \u0003דילמא בהדי דקאזיל מיגס גאיס ביה ויהב ליה גיטא\u0004 \u0005[שמא בתוך\u0006 אותו זמן \u0005שהלך פגע בו\u0006 במקרה \u0005ונתן לו\u0006 את \u0005הגט].\u0006","אגב דברים אלה מביאים הלכה אחרת, שנינו: \u0003האומר לשלוחו \"ערב לי\u0004 עירוב תחומים \u0003בתמרים\" ועירב לו בגרוגרות\u0004 (תאנים יבשות), או שאמר לו \u0003\"\u0004ערב לי \u0003בגרוגרות\" ועירב לו בתמרים, תני חדא\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחת]\u0006 ש\u0003עירובו עירוב, ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003אין עירובו עירוב!\u0004","\u0003אמר רבה: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זו]\u0006 כשיטת \u0003רבנן, הא\u0004 \u0005[זו]\u0006 כשיטת \u0003ר' אלעזר.\u0004 ומסביר: \u0003הא רבנן דאמרי\u0004 \u0005[זו\u0006 כשיטת \u0005חכמים שאומרים]:\u0006 \u0003קפידא\u0004 \u0005[הקפדה],\u0006 שהמשלח שליח מקפיד שימלא את דבריו בדיוק, ואם משנה משהו — בטלה שליחותו. \u0003הא\u0004 \u0005[זו]\u0006 שיטת \u0003ר' אלעזר,\u0004 ש\u0003אמר: מראה מקום היא לו,\u0004 ואם אין השינוי משמעותי — השליחות קיימת.","\u0003ורב יוסף אמר: הא והא\u0004 \u0005[זו וזו]\u0006 כשיטת \u0003רבנן\u0004 \u0005[חכמים],\u0006 שיש קפידה בשינוי, אבל לא בכל שינוי. ויש להסביר: \u0003כאן בשלו, כאן בשל חבירו.\u0004 אם הוא מערב בשלו, אנו אומרים שאינו מקפיד במה בדיוק יערבו לו, אבל בשל חבירו — לא קיבל רשות.","\u0003אמר\u0004 לו \u0003אביי, ואלא הא דתניא\u0004 \u0005[זו ששנינו\u0006 בברייתא\u0005],\u0006 \u0003האומר לשלוחו: \"ערב לי,\u0004 כלומר, הנח את העירוב \u0003במגדל\" ועירב לו\u0004 והניח אותו \u0003בשובך,\u0004 או אמר לו \u0003\"בשובך\"\u0004 — \u0003ועירב לו במגדל, דתניא חדא\u0004 \u0005[ששנויה\u0006 ברייתא \u0005אחת]\u0006 ש\u0003עירובו עירוב, ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]\u0006 ש\u0003אין עירובו עירוב, התם\u0004 \u0005[שם]\u0006 \u0003מאי\u0004 \u0005[מה,\u0006 איזו\u0005]\u0006 חלוקה של \u0003שלו ושל חבירו איכא?\u0004","ומשיבים: \u0003התם נמי איכא פירי\u0004 \u0005[שם גם כן יש פירות]\u0006 של \u0003מגדל ופירי\u0004 \u0005[ופירות]\u0006 של \u0003שובך,\u0004 שלא התכוון לומר לו להניח את העירוב במקום זה, אלא כוונתו היתה שישתמש בפירות הנמצאים במקום זה או אחר, ומניחים שהפירות במקום אחר אינם שייכים לו.","בעל \u0003האומר\u0004 לשניים: \u0003\"כתבו גט ותנו לאשתי\",\u0004 או אמר: \u0003\"גרשוה\",\u0004 או: \u0003\"כתבו איגרת ותנו לה\"\u0004 — \u0003הרי אלו יכתבו ויתנו,\u0004 שכל אלה הן כוונת דבריו ברורה והרי הם הוראה לגרש את האשה.","אבל אם אמר: \u0003\"פטרוה\",\u0004 או שאמר \u0003\"פרנסוה\",\u0004 או \u0003\"עשו לה כנימוס\"\u0004 (כחוק), או \u0003\"עשו לה כראוי\"\u0004 — \u0003לא אמר כלום,\u0004 שכל אלה אינם בהכרח לשון גט.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בעל שאמר \u0003\"שלחוה\",\u0004 או שאמר \u0003\"שבקוה\",\u0004 או \u0003\"תרכוה\"\u0004 — הרי אלה לשונות גט, ולפיכך \u0003הרי אלו יכתבו ויתנו.\u0004 ואם אמר \u0003\"פטרוה\",\u0004 או \u0003\"פרנסוה\",\u0004 או \u0003\"עשו לה כנימוס\",\u0004 או \u0003\"עשו לה כראוי\"\u0004 — \u0003לא אמר כלום.\u0004","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' נתן אומר:\u0004 אם אמר הבעל \u0003\"פטרוה\"\u0004 — \u0003דבריו קיימין,\u0004 וצריכים לתת לה גט, אבל אם אמר: \u0003\"פיטרוה\"\u0004 — \u0003לא אמר כלום. אמר רבא: ר' נתן דבבלאה\u0004 \u0005[שבבלי]\u0006 \u0003הוא ודייק בין \"פיטרוה\" ל\"פטרוה\",\u0004 שהוא מחלק בין \"פיטרוה\" שהוא מלשון פטור (ההיפך מחובה), ולשון \"פטרוה\" במובן של שלחוה, \u0003ואולם ה\u0004\u0003תנא דידן\u0004 \u0005[שלנו]\u0006 \u0003דבר\u0004 \u0005[שבן]\u0006 \u0003ארץ ישראל הוא, לא דייק\u0004 \u0005[אינו מדייק],\u0006 אינו מחלק בזה.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 ללומדים\u0005]\u0006 אם אמר: \u0003\"הוציאוה\", מהו?\u0004 אם אמר: \u0003\"עזבוה\", מהו? \"התירוה\", מהו? \"הניחוה\", מהו? \"הועילו לה\", מהו? \"עשו לה כדת\", מהו?\u0004","ומשיבים: \u0003פשוט מיהא חדא\u0004 \u0005[פתור על כל פנים אחת]\u0006 מן השאלות הללו, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 אם אמר \u0003\"עשו לה כדת\",\u0004 או שאמר \u0003\"עשו לה כנימוס\",\u0004 או \u0003\"עשו לה כראוי\"\u0004 — בכל אלה \u0003לא אמר כלום,\u0004 ואין זה גט. משמע שלשון \"עשו לה כדת\" אינה הוראה מוגדרת לגירושין.","\u0003בראשונה היו אומרים: היוצא בקולר\u0004 שמוליכים אותו בשלשלאות על מנת להוציאו להורג, \u0003ואמר: \"כתבו גט לאשתי\"\u0004 — \u0003הרי אלו יכתבו ויתנו,\u0004 אף על פי שלא פירש ואמר \"תנו\". \u0003חזרו לומר: אף המפרש\u0004 בים, \u0003והיוצא בשיירא\u0004 לדרך רחוקה, ואמר \"כתבו\" כוונתו לכתוב ולתת. \u0003ר' שמעון שזורי אומר: אף\u0004 חולה \u0003המסוכן,\u0004 אם אמר בלשון כזו — כותבים ונותנים.","מסופר בענין זה: \u0003גניבא יוצא בקולר הוה\u0004 \u0005[היה ]\u0006 ליהרג, \u0003כי הוה קא נפיק\u0004 \u0005[כאשר היה יוצא],\u0006 \u0003אמר\u0004 לאנשים שהיו שם בדרך צוואה: \u0003הבו ארבע מאה זוזי\u0004 \u0005[תנו ארבע מאות זוז]\u0006 \u0003לר' אבינא,\u0004 \u0003מחמרא\u0004 \u0005[מן היין]\u0006 שיש לי בעיר \u0003נהר פניא. אמר ר' זירא:\u0004"],["\u0003דרא\u0004 \u0005[ישא]\u0006 \u0003ר' אבינא לסילתיה ואזל לגבי\u0004 \u0005[את סלו וילך אצל]\u0006 \u0003רב הונא רביה\u0004 \u0005[רבו]\u0006 כלומר, כדי לזכות בדבר צריך הוא לסמוך על מה שאמר רבו. ש\u0003אמר רב הונא: גיטו\u0004 של אדם הוא \u0003כמתנתו, מה מתנתו\u0004 שנתן כאשר היה שכיב מרע וחשב שהוא עומד למות, \u0003אם עמד\u0004 (הבריא) ממחלתו — \u0003חוזר, אף גיטו, אם עמד\u0004 מחוליו — \u0003חוזר.\u0004","\u0003ו\u0004מהשוואה זו אפשר ללמוד עוד לצד האחר: \u0003מה גיטו\u0004 של העומד למיתה, \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא פריש\u0004 \u0005[פירש],\u0006 \u0003כיון\u0004 ש\u0003אמר\u0004 \u0003\"כתבו\"\u0004 — \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא אמר \"תנו\"\u0004 — הרי זה גט, וכפי ששנינו במשנתנו, \u0003אף מתנתו, כיון\u0004 ש\u0003אמר \"תנו\"\u0004 — \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא קנו מיניה\u0004 \u0005[עשו קנין עימו]\u0006 — הרי הוא קונה. ואם כן, יכול ר' אבינא להסתמך על ההשוואה בין גט למתנה, ויקבל את המתנה.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003ר' אבא: אי\u0004 \u0005[אם]\u0006 כך אתה אומר, הרי אפשר להמשיך את ההשוואה ולומר: \u0003מה מתנה ישנה\u0004 וחלה \u0003לאחר מיתה, אף גט ישנו לאחר מיתה!\u0004 והרי אין הדבר כן! ודוחים: \u0003הכי השתא\u0004 \u0005[כך אתה משווה]?!\u0006 \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003מתנה איתה\u0004 \u0005[ישנה]\u0006 \u0003לאחר מיתה, אלא גט לאחר מיתה מי איכא\u0004 \u0005[האם ישנו]?\u0006 שהרי הגט הוא ניתוק הקשר בין איש ואשתו, וכאשר אין הבעל קיים — אין משמעות לגט, ובוודאי אין להשוות לענין זה.","\u0003אלא, ר' אבא הכי קא קשיא ליה\u0004 \u0005[כך היה קשה לו]:\u0006 הלא ציווי זה של גניבא \u0003מתנת שכיב מרע במקצת היא\u0004 כאשר אין נותן את כל רכושו, \u0003ומתנת שכיב מרע במקצת בעיא\u0004 \u0005[צריכה]\u0006 \u0003קנין!\u0004 ותוהים: האם \u0003מכלל\u0004 הדברים אתה למד ש\u0003רב הונא\u0004 לפיו זוכה ר' אבינא במתנה \u0003סבר\u0004 \u0005[סבור]\u0006 שמתנת שכיב מרע במקצת \u0003לא בעיא\u0004 \u0005[אינה צריכה]\u0006 \u0003קנין? והא קיימא לן\u0004 \u0005[והרי מוחזק בידינו]\u0006 על מתנת שכיב מרע במקצת \u0003דבעיא\u0004 \u0005[שצריכה]\u0006 \u0003קנין!\u0004 ומתרצים: \u0003שאני הכא\u0004 \u0005[שונה כאן]\u0006 ש\u0003מצוה מחמת מיתה הוא.\u0004 ואין בכך רק דין מתנת שכיב מרע, אלא יש לעשות כדבריו משום שהוא מצווה מחמת מיתה, ומצוה לקיים דברי המת אף שלא נעשו בקנין, ואף אם היתה זו מתנה במקצת.","ותוהים: \u0003מכלל\u0004 הדברים אתה למד ש\u0003ר' אבא סבר: מצוה מחמת מיתה בעיא\u0004 \u0005[צריכה]\u0006 \u0003קנין? והא קיימא לן\u0004 \u0005[והרי מוחזק לנו]\u0006 בענין המצווה מחמת מיתה ש\u0003לא בעי\u0004 \u0005[צריך]\u0006 \u0003קנין!\u0004 ואם כן, מדוע נתקשה בדבר?","\u0003אלא ר' אבא הכי קא קשיא ליה\u0004 \u0005[כך היה קשה לו]:\u0006 הלא \u0003\"\u0004ארבע מאות \u0003זוז\u0004 \u0003חמרא\"\u0004 \u0005[\u0006\u0005יין]\u0006 \u0003לא קאמר\u0004 \u0005[אמר]\u0006 גניבא שיתנו לר' אבינא, \u0003\"דמי\u0004 ארבע מאות זוז \u0003חמרא\"\u0004 \u0005[יין]\u0006 \u0003לא קאמר\u0004 \u0005[אמר],\u0006 \u0003\"\u0004ארבע מאות זוז \u0003מחמרא\"\u0004 \u0005[מן היין]\u0006 \u0003קאמר\u0004 \u0005[אמר]!\u0006 והשאלה היא: למה התכוון בדיבור סתום זה? \u0003ואידך\u0004 \u0005[והאחרים]\u0006 שאינם חושבים שזה קושי, סבורים שמה שאמר \u0003\"מחמרא\"\u0004 \u0005[\"מן היין\"],\u0006 אמר \u0003כדי לייפות את כחו.\u0004 כלומר, גניבא רצה לתת לר' אבינא מתנה בערך מסויים, וכדי לייפות את כוחו, שיהיה לו ממה לגבות ושלא ידחוהו היורשים בתואנות, פירש ממה יגבה את הכסף. ומעירים: אכן, \u0003שלחו מתם\u0004 \u0005[משם\u0006 מארץ ישראל\u0005]\u0006 ואמרו: מה שאמר \u0003\"מחמרא\"\u0004 \u0005[מן היין],\u0006 הרי זה \u0003כדי לייפות את כחו\u0004 של ר' אבינא.","\u0003מי שהיה מושלך לבור,\u0004 וחשב שהוא הולך למות, \u0003ואמר:\u0004 \u0003\"כל השומע את קולו\u0004 (קולי) \u0003יכתוב גט לאשתו\u0004 (לאשתי) \u0003\"\u0004ואמר את שמו ושמה ושאר פרטים נחוצים — \u0003הרי אלו\u0004 השומעים \u0003יכתבו ויתנו\u0004 למרות שלא ראו את האיש ואינם מכירים אותו.","שואלים: \u0003וליחוש\u0004 \u0005[ונחשוש]\u0006 \u0003שמא שד הוא!\u0004 שהרי לא ראו את האיש שבבור אלא שמעו את קולו בלבד! \u0003אמר רב יהודה:\u0004 מדובר \u0003כשראו לו,\u0004 לזה שבבור, \u0003דמות אדם.\u0004","ומקשים: \u0003אינהו נמי אידמויי אידמו\u0004 \u0005[אלו\u0006 השדים \u0005גם כן נדמים]\u0006 לבני אדם כשירצו בכך, ואין זו הוכחה שהוא אדם ולא שד! ומשיבים: \u0003דחזו ליה בבואה\u0004 \u0005[שרואים לו צל].\u0006 ושואלים: \u0003אינהו נמי אית להו בבואה\u0004 \u0005[הם,\u0006 השדים \u0005גם כן יש להם צל]!\u0006 ומשיבים: \u0003דחזו ליה בבואה דבבואה\u0004 \u0005[שרואים לו צל של צל].\u0006 ושואלים: \u0003ודלמא אינהו נמי אית להו\u0004 \u0005[ושמא הם גם כן יש להם]\u0006 צל כזה? \u0003אמר ר' חנינא: לימדני יונתן בני: בבואה אית להו\u0004 \u0005[צל יש להם],\u0006 ואילו \u0003בבואה דבבואה לית להו\u0004 \u0005[צל של צל אין להם].\u0006","ושואלים: \u0003ו\u0004נחשוש \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003צרה היא,\u0004 כלומר, שבבור היתה צרתה של אותה אשה, ומחמת ששונאת אותה רוצה לגרום לה לקלקול, ואומרת בשם הבעל שציווה לתת גט, ותבוא האשה להינשא לאחר שלא כדין, ותפסיד הכל! ומשיבים: \u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: בשעת הסכנה, כותבין ונותנין\u0004 גט \u0003אף על פי שאין מכירין\u0004 את האיש, ואין יודעים אם הוא באמת הבעל, משום שיש חשש גדול יותר שתישאר עגונה. וכיוצא בזה במקרה של המושלך לבור, שאין אפשרות להמתין ולברר את הדבר כראוי.","\u0003הבריא שאמר: \"כתבו גט לאשתי\"\u0004 ולא אמר שיתנו לה — אנו אומרים ש\u0003רצה לשחק\u0004 (לצחוק, להרגיז) \u0003בה,\u0004 שהרי אמר רק לכתוב ולא אמר לתת, ואין זה גט.","מסופר: \u0003מעשה בבריא אחד שאמר \"כתבו גט לאשתי\", ועלה\u0004 אחר כך \u0003לראש הגג ונפל ומת, אמר רבן שמעון בן גמליאל: אם מעצמו נפל,\u0004 כלומר, שאיבד עצמו לדעת — \u0003הרי זה גט,\u0004 שמובן ממעשיו שידע שהוא הולך למות ובוודאי התכוון לתת לה גט, ו\u0003אם הרוח דחתו\u0004 (הפילה אותו) ובתאונה נפל — \u0003אינו גט,\u0004 שמתחילה לא התכוון לתת לה גט.","ותוהים על השנוי במשנה: \u0003מעשה לסתור?\u0004 וכי מביאים מעשה מייד לאחר ההלכה כדי לסתור אותה? שהרי קודם אמרו שגט כזה של בריא אינו גט, ואילו ממעשה זה משמע שפעמים אף גט שאמר בריא לכתוב הוא בכל זאת גט!","ומשיבים: \u0003חסורי מיחסרא והכי קתני\u0004 \u0005[חסרה\u0006 המשנה \u0005וכך שנה\u0006 בה\u0005]:\u0006 הבריא שאמר \"כתבו גט לאשתי\" — רצה לשחק בה, ואולם \u0003אם הוכיח סופו על תחילתו\u0004 שהוא הולך למות — \u0003הרי זה גט, ומעשה נמי\u0004 \u0005[גם כן]\u0006 \u0003בבריא שאמר \"כתבו גט לאשתי\", ועלה לראש הגג ונפל ומת, ואמר רבן שמעון בן גמליאל: אם מעצמו נפל\u0004 — \u0003הרי זה גט, אם הרוח דחתו\u0004 — \u0003אינו גט.\u0004","מסופר: \u0003ההוא גברא דעל לבי כנישתא\u0004 \u0005[אדם אחד שנכנס לבית הכנסת],\u0006 \u0003אשכח מקרי ינוקא ובריה דיתבי ויתיב איניש אחרינא גבייהו\u0004 \u0005[מצא מלמד תינוקות ובנו שיושבים\u0006 יחד, \u0005ויושב איש אחר אתם],\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003בי תרי מינייכו נכתבו גיטא לדביתהו\u0004 \u0005[שנים מכם שיכתבו גט לאשתי],\u0006 \u0003לסוף שכיב מקרי ינוקא\u0004 \u0005[מת מלמד התינוקות],\u0006 והשאלה היתה: \u0003מי משוו אינשי ברא שליחא במקום אבא\u0004 \u0005[האם ממנים אנשים\u0006 את \u0005הבן שליח במקום האב]\u0006 ואותו אדם התכוון שגם בנו של מלמד התינוקות יוכל להיות שליח, אף שאביו נמצא שם, \u0003או לא?\u0004 שנתכוון רק לאב ולאדם השלישי ולא מינה את הבן לשליח, ועכשיו שמת האב אין עוד שני עדים לגט זה.","\u0003רב נחמן אמר: לא משוו אינשי ברא שליחא\u0004 \u0005[אין אנשים ממנים\u0006 את \u0005הבן שליח]\u0006 \u0003במקום אבא,\u0004 \u0003ורב פפי אמר: משוו אינשי ברא שליחא\u0004 \u0005[ממנים אנשים\u0006 את \u0005הבן שליח]\u0006 \u0003במקום אבא. אמר רבא, הילכתא\u0004 \u0005[הלכה\u0006 היא\u0005]:\u0006 \u0003משוו אינשי ברא שליחא\u0004 \u0005[ממנים אנשים\u0006 את \u0005הבן שליח]\u0006 \u0003במקום אבא\u0004 \u0005[האב].\u0006","\u0003אמר\u0004 הבעל \u0003לשנים: \"תנו גט לאשתי\",\u0004"],["\u0003או\u0004 אם אמר \u0003לשלשה: \"כתבו גט ותנו לאשתי\"\u0004 — \u0003הרי אלו יכתבו\u0004 בעצמם \u0003ויתנו.\u0004 \u0003אמר לשלשה: \"תנו גט לאשתי\"\u0004 — \u0003הרי אלו יאמרו לאחרים ויכתבו, מפני שעשאן בית דין,\u0004 אלו \u0003דברי ר' מאיר.\u0004","\u0003וזו הלכה\u0004 ש\u0003העלה\u0004 (הביא) \u0003ר' חנינא איש אונו מבית האסורין\u0004 בשמו של ר' עקיבא שהיה כלוא שם: \u0003מקובל אני,\u0004 כך קיבלתי מרבותי, \u0003באומר לשלשה: \"תנו גט לאשתי\"\u0004 — \u0003שיאמרו לאחרים ויכתבו, מפני שעשאן בית דין,\u0004","\u0003אמר ר' יוסי, נומינו\u0004 (אמרנו) \u0003לשליח,\u0004 כלומר, לר' חנינא איש אונו: \u0003אף אנו מקובלין\u0004 אבל לא כדבריך, \u0003שאפילו אמר לבית דין הגדול שבירושלים \"תנו גט לאשתי\"\u0004 — \u0003שילמדו\u0004 לכתוב \u0003ויכתבו\u0004 הם בעצמם \u0003ויתנו.\u0004","\u0003אמר לעשרה: \"כתבו ותנו גט לאשתי\"\u0004 — \u0003אחד\u0004 מהם \u0003כותב ושנים חותמין,\u0004 ואם אמר: \u0003\"כולכם כתובו\"\u0004 — \u0003אחד כותב וכולם חותמין, לפיכך אם מת אחד מהן\u0004 — \u0003הרי זה גט בטל,\u0004 שהרי עמד על כך שיהיו כולם שותפים בכך.","\u0003אמר ר' ירמיה בר אבא:\u0004 \u0003שלחו ליה\u0004 \u0005[לו]\u0006 \u0003מבי\u0004 \u0005[מבית\u0006 מדרשו\u0005]\u0006 של \u0003רב\u0004 אחרי מותו של רב \u0003לשמואל: ילמדנו רבינו,\u0004 אם \u0003אמר\u0004 הבעל \u0003לשנים:\u0004 \u0003\"כתבו ותנו גט לאשתי\", ואמרו\u0004 הם \u0003לסופר וכתב וחתמו הן, מהו? שלח להו\u0004 \u0005[להם]:\u0006 \u0003תצא\u0004 האשה מבעלה אם נישאה על סמך גט זה, \u0003והדבר צריך תלמוד,\u0004 שצריך עדיין לברר את ההלכה, משום שיש ספק עקרוני בדבר.","ושואלים: \u0003מאי\u0004 \u0005[מה,\u0006 פירוש\u0005]\u0006 \u0003\"הדבר צריך תלמוד\"?\u0004 מהו הדבר שצריך פה עיון? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003משום דהוו להו מילי\u0004 \u0005[שהיו כאן\u0006 רק \u0005דברים],\u0006 שהרי לא נתן הבעל להם דבר ממשי בידם, אלא דברים בלבד, הוראה נתן להם, \u0003ומספקא ליה\u0004 \u0005[והיה מסופק לו]\u0006 לשמואל, \u0003מילי אי מימסרן\u0004 \u0005[דברים האם\u0006 הם \u0005נמסרים]\u0006 \u0003לשליח\u0004 כאילו נמסר בידו דבר ממשי, והוא עכשיו ברשות השליח, ולכן יוכל השליח לעשות שליח אחר, \u0003אי\u0004 \u0005[\u0006או \u0005אם]\u0006 \u0003לא מימסרן\u0004 \u0005[נמסרים]\u0006 \u0003לשליח\u0004 ואינו יכול למוסרם לאחר. ואף כאן, היה שמואל מסופק אם יכולים השניים שאמר להם הבעל למסור שליחותם לסופר.","\u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003שמואל אמר רבי: הלכה כ\u0004שיטת \u0003ר' יוסי,\u0004 ש\u0003אמר:\u0004 \u0003מילי\u0004 \u0005[דברים]\u0006 \u0003לא מימסרן\u0004 \u0005[נמסרים]\u0006 \u0003לשליח!\u0004","\u0003אלא\u0004 צריך לומר כך, ש\u0003לשמואל הא קא מיבעיא ליה\u0004 \u0005[זו\u0006 מה \u0005שנשאלה לו]\u0006 ובזה היה ספיקו: \u0003האי\u0004 \u0005[זה]\u0006 שאמר הבעל לשנים \u0003\"כתובו\",\u0004 מה היתה כוונתו? \u0003אי\u0004 \u0005[אם]\u0006 ל\u0003כתב ידן\u0004 התכוון, כלומר, חתימתם בלבד, ויכולים הם למסור את כתיבת הגט לסופר, \u0003אי\u0004 \u0005[\u0006או \u0005אם]\u0006 רצה מהם את \u0003כתב הגט,\u0004 שהם עצמם יכתבו את שטר הגט?","ושואלים: \u0003ותיפשוט ליה ממתניתין\u0004 \u0005[ויפתור\u0006 את הבעיה הזו \u0005מ\u0006מה ששנינו ב\u0005משנתנו]:\u0006 \u0003אמר לשנים \"תנו גט לאשתי\", או\u0004 שאמר \u0003לשלשה \"כתבו גט ותנו לאשתי\"\u0004 — \u0003הרי אלו יכתבו ויתנו.\u0004 משמע שהם עצמם צריכים לכתוב!","ומשיבים: \u0003היא,\u0004 המשנה \u0003גופא\u0004 \u0005[עצמה]\u0006 \u0003קא מיבעיא ליה\u0004 \u0005[נסתפקה לו]:\u0006 האם \u0003\"כתובו\"\u0004 שבמשנה, \u0003כתב ידן הוא,\u0004 \u0003או כתב הגט הוא?\u0004 ומשיבים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 ש\u0003כתב הגט הוא, דקתני סיפא\u0004 \u0005[ש\u0006הרי \u0005שנה בסופה]\u0006 של המשנה: \u0003אמר ר' יוסי, נומינו\u0004 \u0005[אמרנו]\u0006 \u0003לשליח: אף אנו מקובלין, שאפילו\u0004 אם \u0003אמר לבית דין הגדול שבירושלים \"תנו גט לאשתי\"\u0004 — \u0003שילמדו ויכתבו ויתנו לה.\u0004","ומעתה \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 \u0003כתב הגט הוא,\u0004 שצריכים לכתוב את הגט ממש — \u0003שפיר\u0004 \u0005[יפה]\u0006 מובן הדבר, שיש צורך במומחיות כדי לדעת לכתוב גט כראוי. \u0003אלא אי אמרת\u0004 \u0005[אם אתה אומר]\u0006 \u0003כתב ידן הוא\u0004 כלומר, חתימתם בלבד, \u0003מי איכא בי דינא דלא ידעי מחתם חתימת ידייהו\u0004 \u0005[האם יש בית דין שאינם יודעים לחתום חתימת ידם]?\u0006 ואומרים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003איכא בי דינא חדתא\u0004 \u0005[יש בית דין חדש]\u0006 שלא למדו לחתום חתימה הידועה לרבים.","ושואלים: \u0003ואי סבירא לן\u0004 \u0005[ואם סבורים אנו]\u0006 \u0003דהאי\u0004 \u0005[שזה]\u0006 הביטוי \u0003\"כתובו\" כתב ידן\u0004 (חתימתם) \u0003הוא,\u0004 \u0003הא\u0004 \u0005[האם]\u0006 \u0003כתב הגט\u0004 שמסרו לאחרים שיכתבוהו — \u0003כשר? והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003שמואל, אמר רבי: הלכה כ\u0004שיטת \u0003ר' יוסי,\u0004 ש\u0003אמר: מילי\u0004 \u0005[דברים]\u0006 \u0003לא מימסרן\u0004 \u0005[נמסרים]\u0006 \u0003לשליח!\u0004","ומשיבים: \u0003אמרי\u0004 \u0005[אומרים]\u0006 תשובה לדבר: \u0003אי סבירי לן\u0004 \u0005[אם סבורים אנו]\u0006 ש\u0003\"כתובו\" כתב ידן הוא,\u0004 אם כן לגבי \u0003כתב הגט נעשה כאומר\u0004 לאותם שליחים: \u0003\"אמרו\u0004 לאחרים לעשות זאת \u0003\",\u0004 \u0003ומודה ר' יוסי באומר \"אמרו\u0004 לאחר שיכתוב \u0003\"\u0004שהוראה זו יכולה להימסר לשליח שיכול למנות שליח לכך. ושואלים: \u0003ומי\u0004 \u0005[האם]\u0006 \u0003מודה ר' יוסי באומר \"אמרו\"? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 גט שיש בו \u0003כתב סופר,\u0004 שהסופר מזהה את כתב ידו, \u0003ו\u0004היה \u0003עד\u0004 אחד שאפשר לאשר את חתימתו — הרי זה \u0003כשר\u0004 כעדות שנים, \u0003ואמר ר' ירמיה: חתם סופר שנינו\u0004 ולא כתב סופר,","\u0003ואמר רב חסדא: מתניתין\u0004 \u0005[משנתנו]\u0006 המכשירה חתימת סופר \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]?\u0006 — שיטת \u0003ר' יוסי היא,\u0004 ש\u0003אמר: מילי\u0004 \u0005[דברים]\u0006 \u0003לא מימסרן\u0004 \u0005[נמסרים]\u0006 \u0003לשליח\u0004 ואין לחשוש שהסופר חתם בלא שהבעל עצמו ציווה עליו לחתום.","\u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך\u0006 לומר\u0005]\u0006 ש\u0003מודה ר' יוסי באומר \"אמרו\", נפיק מינה חורבה\u0004 \u0005[תצא מכאן תקלה],\u0006 כיצד? \u0003דזימנין דאמר להו\u0004 \u0005[שפעמים שאומר להם]\u0006 \u0003לשנים:\u0004"],["\u0003\"אמרו לסופר ויכתוב ולפלוני ופלוני ויחתמו\", ומשום כיסופא\u0004 \u0005[בושה]\u0006 של ה\u0003סופר,\u0004 שאומר: וכי אינכם חושבים אותי לאדם כשר הראוי לחתום כעד? \u0003חיישי ומחתמי חד מהנך סהדי\u0004 \u0005[חוששים\u0006 לבושתו \u0005ומחתימים אחד מאותם העדים]\u0006 \u0003ו\u0004את ה\u0003סופר בהדייהו\u0004 \u0005[יחדיו],\u0006 \u0003ובעל לא אמר הכי\u0004 \u0005[כך],\u0006 ואם כן הגט פסול, שלא נעשתה מצוות הבעל, ויכשירו אותו שלא כדין!","ומשיבים: \u0003כיון\u0004 ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 (כמפורש להלן) שבמקרה זה \u0003\"כשר, ו\u0004אולם \u0003לא תעשה כן בישראל\"\u0004 — \u0003לא שכיח\u0004 \u0005[מצוי]\u0006 שיעשו כן, ואין לגזור גזירה משום דבר שאינו שכיח.","ושואלים: \u0003וליחוש דילמא אמר להו\u0004 \u0005[ונחשוש שמא יאמר להם]\u0006 \u0003לבי תרי\u0004 \u0005[לשנים]:\u0006 \u0003\"אמרו לסופר ויכתוב, ואתם חתומו\", ואזלי הנך משום כיסופא\u0004 \u0005[והולכים אלה משום בושתו]\u0006 של ה\u0003סופר ומחתמי ליה\u0004 \u0005[ומחתימים אותו]\u0006 את ה\u0003סופר בהדי חד מינייהו\u0004 \u0005[יחד עם אחד מהם],\u0006 \u0003ובעל לא אמר הכי\u0004 \u0005[כך],\u0006 והרי זה גט פסול! \u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003הא נמי\u0004 \u0005[זה גם כן]\u0006 \u0003\"כשר ולא תעשה\" הוא,\u0004 ומשום כך אין הוא מצוי ולכן אין לחשוש לדבר.","ומשיבים: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006דעת \u0005מי שאומר]\u0006 (כמפורש להלן) שדבר זה \u0003\"כשר ולא תעשה\", אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003\"כשר ותעשה\"\u0004 שמותר לעשות כך לכתחילה, אם כן \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006","\u0003אלא\u0004 יש לחזור מן ההסבר הקודם ולומר כך: \u0003ר' יוסי תרתי\u0004 \u0005[שתי]\u0006 הלכות שונות \u0003אמר,\u0004 האחת, שדברים אינם נמסרים לשליח, וכן אמר שאף כאשר אמר הבעל \"אמרו\" אינם רשאים למסור לאחר, \u0003ושמואל סבר לה כוותיה בחדא\u0004 \u0005[סבור כשיטתו ב\u0006דבר \u0005אחד]\u0006 שדברים אינם נמסרים לשליח, \u0003ופליג עליה בחדא\u0004 \u0005[וחולק עליו באחד],\u0006 ולדעתו של שמואל אם הורה הבעל במפורש לעדים שיאמרו לאחרים לכתוב — הרי זה כשר.","\u0003גופא\u0004 \u0005[לגופו]\u0006 של דבר שהזכרנו קודם: \u0003אמר שמואל, אמר רבי: הלכה כ\u0004שיטת \u0003ר' יוסי,\u0004 ש\u0003אמר: מילי\u0004 \u0005[דברים]\u0006 \u0003לא מימסרן\u0004 \u0005[נמסרים]\u0006 \u0003לשליח. אמר לפניו ר' שמעון ברבי\u0004 (בן רבי) לפני רבי: \u0003מאחר שר'\u0004 \u0003מאיר וחנינא איש אונו חולקין על ר' יוסי,\u0004 ואומרים שאפשר למסור דברים לשליח, \u0003מה\u0004 אם כן \u0003ראה רבי לומר\u0004 ש\u0003הלכה כ\u0004שיטת \u0003ר' יוסי?\u0004","\u0003אמר לו: שתוק, בני, שתוק, לא ראית את ר' יוסי, אילמלי ראיתו\u0004 (אם היית רואה אותו) היית יודע ש\u0003נמוקו\u0004 (טעמו) \u0003עמו,\u0004 שהיה לו תמיד טעם מספיק לדבריו, ואני סומך עליו ביותר.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003איסי בן יהודה היה מונה שבחן של חכמים,\u0004 והיה נותן לכל אחד מהם תואר: \u0003ר' מאיר\u0004 — \u0003חכם וסופר, ר' יהודה\u0004 — \u0003חכם לכשירצה, ר' טרפון\u0004 — \u0003גל של אגוזין,\u0004 שכדרך גל של אגוזים, כאשר ניטל אחד מהם הרי כולם נופלים האחד על השני, כך ר' טרפון, כשהיה תלמיד שואלו בענין כלשהו היה מביא לו ראיות מכל חלקי התורה, הכל יחד, \u0003ר' ישמעאל\u0004 — \u0003חנות מיוזנת\u0004 (מלאה כל טוב), \u0003ר' עקיבא\u0004 — \u0003אוצר בלום\u0004 (מלא) של דברים, \u0003ר' יוחנן בן נורי\u0004 — \u0003קופת הרוכלים\u0004 שיש בה מעט מכל מין הדרוש, \u0003ר' אלעזר בן עזריה\u0004 — \u0003קופה של בשמים\u0004 שכל מה שהוא אומר מבושם ובעל טעם, \u0003משנת ר' אליעזר בן יעקב\u0004 — \u0003קב ונקי\u0004 (מעט, אבל הכל נקי), \u0003ר' יוסי\u0004 — \u0003נמוקו עמו, ר' שמעון\u0004 — \u0003טוחן הרבה ומוציא קימעא\u0004 (מעט).","\u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 להסביר זאת: הכוונה היא שר' שמעון \u0003משכח קימעא\u0004 \u0005[מעט]\u0006 מתלמודו, \u0003ומה שמוציא,\u0004 כלומר, אותם הדברים המועטים שהוא מוציא, שאינו זוכר אותם \u0003אינו מוציא אלא סובין,\u0004 כלומר, פסולת. \u0003וכן אמר ר' שמעון לתלמידיו: בניי, שנו מדותי,\u0004 כלומר קבלו את פסקי ההלכה שלי, \u0003שמדותי תרומות\u0004 הנבחרות \u0003מ\u0004תוך \u0003תרומות\u0004 (המובחרות) של \u0003מידותיו של ר' עקיבא.\u0004","\u0003גופא\u0004 \u0005[לגופה]\u0006 של אותה הלכה שאמרנו: \u0003אמר לשנים \"אמרו לסופר ויכתוב ולפלוני ופלוני ויחתמו\", אמר רב הונא אמר רב:\u0004 גט כזה \u0003כשר, ו\u0004אולם \u0003לא תעשה זאת בישראל\u0004 לכתחילה, אלא צריך הבעל עצמו למנות את הסופר והעדים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003עולא לרב נחמן, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שאמר \u0003רב נחמן לעולא: מאחר\u0004 ש\u0003כשר, אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא תעשה זאת בישראל? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003שמא תשכור\u0004 האשה \u0003עדים.\u0004 שכיון שמותר לעשות על ידי שליח והעדים עצמם אינם יודעים מה אמר הבעל, הרי יכולה האשה לשכור אדם שיאמר לאחרים לכתוב גט עבורה שלא ברצון הבעל כלל.","ושואלים: \u0003ומי חיישינן\u0004 \u0005[והאם אנו חוששים]\u0006 לכגון זה? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003עדים החתומין על שדה מקח\u0004 (מכר) \u0003ועל גט אשה, לא חשו חכמים לדבר זה\u0004 של זיוף, שמא נכתבו שטרות אלה שלא מרצון בעליהם! ומשיבים: \u0003מעשה לא עבדי\u0004 \u0005[אינם עושים]\u0006 לכתוב שטר מזוייף, אבל \u0003דבורא קאמרי\u0004 \u0005[\u0006ב\u0005דיבור אומרים]\u0006 ולכן ייתכן שאדם אחד אומר לחבירו דבר שקר, והחבר עושה זאת לתומו, שאינו יודע שעושה שלא כדין.","והלכה נוספת: \u0003אמר לשנים \"אמרו לסופר ויכתוב ואתם חתומו\", רב חסדא אמר:\u0004 גט זה \u0003כשר ולא תעשה,\u0004 שאסור לעשות כך לכתחילה, \u0003רבה בר בר חנה אמר: כשר ותעשה\u0004 לכתחילה.","ובאותו נושא נחלקו גם אמוראים נוספים, \u0003רב נחמן אמר: כשר ולא תעשה, רב ששת אמר: כשר ותעשה, רבה אמר: כשר ולא תעשה, רב יוסף\u0004 \u0003אמר: כשר ותעשה.\u0004"],["\u0003ואיכא דאפיך להו\u0004 \u0005[ויש\u0006 מי \u0005שהופך אותן],\u0006 את שיטות רבה ורב יוסף בענין זה.","שנינו במשנה: \u0003אמר לעשרה \"כתבו גט\u0004 לאשתי \u0003\"\u0004— אחד כותב ושנים חותמים. ועוד \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בענין זה: \u0003אמר לעשרה: \"כתבו גט ותנו לאשתי\"\u0004 — \u0003אחד כותב על ידי\u0004 (עבור) \u0003כולם.\u0004 אם אמר: \u0003\"כולכם כתובו\"\u0004 — \u0003אחד כותב במעמד כולם.\u0004 אם אמר: \u0003\"הוליכו גט לאשתי\"\u0004 — \u0003אחד מוליך על ידי\u0004 (עבור) \u0003כולם.\u0004 אם אמר \u0003\"כולכם הוליכו\u0004 גט \u0003\"\u0004— \u0003אחד מוליך במעמד כולם.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]:\u0006 אם \u0003מנה אותן,\u0004 שפירש שפלוני ופלוני ופלוני יעשו זאת, \u0003מהו\u0004 הדין? האם יכול אחד מהם לעשות זאת עבור כולם ככל האומר לכמה אנשים \"כתבו גט\", או שהכוונה היתה כאומר \"כולכם כתבו\" — וצריך לכתוב במעמד כולם? \u0003רב הונא אמר: מנה\u0004 — \u0003אינו כ\"כולכם\", ר' יוחנן משום\u0004 (בשם) \u0003ר' אלעזר\u0004 ש\u0003מן רומה אמר: מנה\u0004 — \u0003הרי הוא כ\"כולכם\".\u0004","\u0003אמר רב פפא, ולא פליגי\u0004 \u0005[חלוקים]:\u0006 \u0003הא\u0004 \u0005[זה]\u0006 מדבר במקרה ש\u0003מנה כולהו\u0004 \u0005[\u0006את \u0005כולם],\u0006 \u0003והא\u0004 \u0005[וזה]\u0006 מדבר במקרה ש\u0003מנה\u0004 רק \u0003מקצתייהו\u0004 \u0005[מקצתם].\u0006 \u0003אמרי לה להאי גיסא, ואמרי לה להאי גיסא\u0004 \u0005[יש אומרים זאת לצד זה, ויש אומרים זאת לצד זה],\u0006 יש אומרים שאם מנה את כולם, דיקדק בדבר שכולם יעשו זאת יחד, אבל אם מנה את מקצתם, הוכיח בזה שאינו עומד על כך שיעשו כולם כאחד, ונקב בשמות אלה לומר שרצונו שיבחרו מן המנויים כאלה שיעשו זאת. ויש אומרים שאם מנה את מקצתם גילה את דעתו בזה שהוא מקפיד שדווקא אנשים אלה שמנה יעשו יחד את הדבר בעצמם, מה שאין כן כשמנה את כולם ולא ציין במפורש \"כולכם\".","מסופר: \u0003אתקין\u0004 \u0005[התקין]\u0006 \u0003רב יהודה בגיטא\u0004 \u0005[בגט]\u0006 של \u0003\"כולכם\",\u0004 כלומר, כאשר האיש אומר \"כולכם כתבו\", שיאמר הדבר בנוסח זה: \u0003\"כתובו או כולכון\u0004 \u0005[כולכם]\u0006 \u0003או כל חד וחד מינכון\u0004 \u0005[אחד ואחד מכם],\u0006 \u0003חתומו או כולכון\u0004 \u0005[כולכם]\u0006 \u0003או כל תרי מינכון\u0004 \u0005[שנים מכם],\u0006 \u0003אובילו\u0004 \u0005[הובילו]\u0006 \u0003או כולכון\u0004 \u0005[כולכם]\u0006 \u0003או כל חד וחד מינכון\u0004 \u0005[אחד ואחד מכם]\u0006 \u0003\".\u0004 ועל ידי כך לא יהא חשש שייפסל הגט אם אחד מהם לא ישתתף במעשה. \u0003אמר רבא:\u0004 תקנה זו עדיין משאירה מקום למכשול, כי מאחר שתיקן רב יהודה נוסח ארוך ומסובך \u0003זימנין דגאיז ליה לדיבוריה\u0004 \u0005[פעמים ש\u0006הוא \u0005חותך,\u0006 מקצר, \u0005את דיבורו]\u0006 \u0003ואמר \"כולכון\"\u0004 \u0005[ואומר \"כולכם\"]\u0006 \u0003ולא אמר\u0004 \u0005[ואינו אומר]\u0006 \u0003\"כל חד מינכון\u0004 \u0005[אחד מכם]\u0006 \u0003\",\u0004 \u0003ואתי לאיפסולי\u0004 \u0005[ויבוא\u0006 הגט \u0005להיפסל]!\u0006","","\u0003אלא אמר רבא:\u0004 צריך לומר בנוסח זה: \u0003\"כתובו כל חד מינכון\u0004 \u0005[אחד מכם],\u0006 \u0003חתומו כל תרי מינכון\u0004 \u0005[שניים מכם],\u0006 \u0003אובילו\u0004 \u0005[הובילו]\u0006 \u0003כל חד מינכון\u0004 \u0005[אחד מכם]\u0006\u0003\",\u0004 ולא יאמר \"כולכם\" כדי שלא יבוא לידי מכשול אם אחד מהם לא יוכל לעשות זאת.","","\u0003מי שאחזו\u0004 (תקפו) \u0003קורדייקוס\u0004 שהוא מין שיגעון התוקף אנשים לזמן מסויים, \u0003ואמר: \"כתבו גט לאשתי\"\u0004 — \u0003לא אמר כלום,\u0004 אין משמעות לדבריו, לפי שאין דעתו צלולה באותו זמן. אם \u0003אמר: \"כתבו גט לאשתי\"\u0004 בדעה צלולה \u0003ו\u0004אחרי כן \u0003אחזו קורדייקוס וחזר ואמר\u0004 באותו זמן: \u0003\"לא תכתבנו\"\u0004 — \u0003אין דבריו האחרונים כלום.\u0004","ודין נוסף: בכל מקרה ש\u0003נשתתק\u0004 הבעל ואינו יכול לדבר, \u0003ואמרו לו: \"נכתוב גט לאשתך\" והרכין בראשו\u0004 לסימן כן, \u0003בודקין אותו שלשה פעמים\u0004 בשאלות שונות, \u0003אם אמר\u0004 בהרכנת ראשו על שאלה שראוי להשיב עליה \u0003\"לאו\"\u0004 — אכן ענה \u0003\"לאו\",\u0004 \u0003ועל\u0004 שאלה שראוי להשיב עליה \u0003\"הן\"\u0004 — ענה \u0003\"הן\",\u0004 שמוכח מתוך כך שהוא מבין מה שאומרים לו ומגיב כראוי — \u0003הרי אלו יכתבו ויתנו\u0004 את הגט לפי הסכמתו בהנעת ראשו, ואין צורך באמירה מפורשת.","שואלים: \u0003מאי\u0004 \u0005[מה\u0006 הוא\u0005]\u0006 \u0003קורדייקוס\u0004 זה הנזכר במשנה? \u0003אמר שמואל:\u0004 אדם \u0003דנכתיה חמרא חדתא דמעצרתא\u0004 \u0005[שנשכו,\u0006 הזיק לו, \u0005יין חדש ש\u0006בא \u0005מן הגת].\u0006 ושואלים: \u0003וליתני\u0004 \u0005[ושישנה]\u0006 התנא במשנתנו במפורש: \u0003מי שנשכו יין חדש!\u0004 ומשיבים: \u0003הא קא משמע לן, דהא רוחא\u0004 \u0005[הרי זה משמיע לנו שרוח\u0006 רעה \u0005זו]\u0006 \u0003קורדייקוס שמה.\u0004","ושואלים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מזה],\u0006 ומה זה משנה שזהו שמה? ומשיבים: \u0003לקמיעא,\u0004 שאם כותבים לו קמיע לרפואה, צריך הכותב לדעת את שם המחלה. ושואלים: \u0003מאי אסותיה\u0004 \u0005[מה תרופתו]\u0006 של החולה בזה? ומשיבים: יאכל \u0003בישרא סומקא אגומרי\u0004 \u0005[בשר אדום,\u0006 רזה, שניצלה \u0005על גחלים],\u0006 \u0003ו\u0004ישתה \u0003חמרא מרקא\u0004 \u0005[יין קלוש]\u0006 מהול בכמות רבה של מים.","\u0003אמר אביי, אמרה לי אם\u0004 (אמא): כתרופה \u0003לשימשא\u0004 \u0005[ל\u0006מחלת \u0005חום]\u0006 \u0003בת יומא\u0004 \u0005[יום]\u0006 — ישתה \u0003כוזא דמיא\u0004 \u0005[קנקן מים].\u0006 התרופה למחלת חום \u0003בת תרי יומי\u0004 \u0005[שני ימים]\u0006 — \u0003סיכורי\u0004 \u0005[הקזת דם].\u0006 למחלה \u0003בת תלתא יומי\u0004 \u0005[שלושה ימים]\u0006 — אכילת \u0003בשרא סומקא אגומרי\u0004 \u0005[בשר אדום\u0006 שניצלה \u0005על גחלים]\u0006 \u0003ו\u0004ישתה \u0003חמרא מרקא\u0004 \u0005[יין קלוש].\u0006 \u0003לשימשא עתיקתא\u0004 \u0005[ל\u0006מחלת \u0005חום ישנה]\u0006 הנמשכת זמן רב — \u0003ליתי תרנגולתא אוכמתי\u0004 \u0005[יקח תרנגולת שחורה]\u0006 \u0003וליקרעה\u0004 \u0005[ויקרע אותה]\u0006 \u0003שתי וערב\u0004 (לאורכה ולרוחבה), \u0003וליגלחיה למציעתא דרישיה ולותביה עילויה\u0004 \u0005[ויגלח את אמצע ראשו ויניח אותה,\u0006 את התרנגולת, \u0005עליו],\u0006 \u0003וננחיה עילויה\u0004 \u0005[ויניחנה עליו]\u0006 \u0003עד דמיסרך\u0004 \u0005[שידבק בו\u0006 הדם\u0005],\u0006","\u0003ולינחות וליקום במיא\u0004 \u0005[וירד ויעמוד במים]\u0006 \u0003עד צואריה\u0004 \u0005[צווארו]\u0006 \u0003עד דחליש עלמא עילויה\u0004 \u0005[שיהיה קרוב להתעלף],\u0006 \u0003ולימוד ולסליק וליתיב\u0004 \u0005[ויצלול\u0006 במים \u0005ויעלה וישב\u0006 וינוח\u0005].\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 יוכל לעשות כל זאת, \u0003ליכול כרתי\u0004 \u0005[שיאכל כרישים],\u0006 \u0003ולינחות וליקום במיא\u0004 \u0005[וירד ויעמוד במים]\u0006 \u0003עד צואריה\u0004 \u0005[צווארו]\u0006 \u0003עד דחליש עלמא עילויה\u0004 \u0005[שיהא קרוב להתעלף\u0006 מרוב חולשה\u0005],\u0006 \u0003ולימוד ולסליק וליתיב\u0004 \u0005[ויצלול ויעלה וישב].\u0006","תרופה \u0003לשימשא\u0004 \u0005[ל\u0006מחלת \u0005חום]\u0006 — \u0003בישרא סומקא אגומרי וחמרא מרקא\u0004 \u0005[בשר אדום\u0006 שניצלה \u0005על גחלים ויין קלוש].\u0006 \u0003לתלגא\u0004 \u0005[לשלג,\u0006 למכת קור\u0005]\u0006 — \u0003בישרא שמינא אגומרי וחמרא חייא\u0004 \u0005[בשר שמן על גחלים ויין חי].\u0006","מסופר: \u0003רב עמרם חסידא\u0004 \u0005[החסיד]\u0006 \u0003כי הוה מצערין ליה בי ריש גלותא\u0004 \u0005[כאשר היו מצערים אותו\u0006 בני \u0005בית ראש הגולה],\u0006 \u0003הוו מגנו ליה אתלגא\u0004 \u0005[היו משכיבים אותו\u0006 לישון \u0005על שלג]\u0006 כל הלילה, \u0003למחר אמרו ליה\u0004 \u0005[למחרת היו אומרים לו]:\u0006 \u0003מאי ניחא ליה למר דלייתו ליה\u0004 \u0005[מה נוח לאדוני שיביאו לו\u0006 לאכול\u0005]?\u0006 \u0003אמר\u0004 בליבו: \u0003הני\u0004 \u0005[אלה]\u0006 \u0003כל\u0004 מה \u0003דאמינא להו\u0004 \u0005[שאומר להם]\u0006 \u0003מיפך אפכי\u0004 \u0005[\u0006יעשו \u0005ההיפך],\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003בישרא סומקא אגומרי וחמרא מרקא\u0004 \u0005[בשר אדום\u0006 שניצלה \u0005על גחלים ויין קלוש],\u0006 \u0003אייתו ליה אינהו\u0004 \u0005[הביאו לו הם]\u0006 באמת ההיפך: \u0003בישרא שמינא אגומרי וחמרא חייא\u0004 \u0005[בשר שמן על גחלים ויין חי],\u0006 והרי כאמור זו היתה התרופה למכת הקור שממנה סבל.","\u0003שמעה ילתא\u0004 אשת רב נחמן מה עשו לו בני בית ראש הגולה, ושהוא סובל מקור \u0003ומעיילה ליה לבי מסותא ומוקמי ליה במיא דבי מסותא\u0004 \u0005[והכניסה אותו למרחץ והעמידו אותו במים של בית מרחץ]\u0006 \u0003עד דמהפכי מיא דבי מסותא והוו דמא\u0004 \u0005[שהפכו המים של בית המרחץ והיו\u0006 נעשים אדומים כ\u0005דם],\u0006 \u0003וקאי בישריה פשיטי פשיט\u0004 \u0005[ועמד\u0006 ונעשה \u0005בשרו\u0006 בהרות בהרות כעין \u0005מטבעות].\u0006","ומסופר: \u0003רב יוסף\u0004 כשהיה סובל מקור \u0003איעסק בריחיא\u0004 \u0005[היה עוסק\u0006 בטחינה \u0005בריחיים]\u0006 כדי להתחמם. \u0003רב ששת\u0004 כשהיה סובל מקור \u0003איעסק בכשורי\u0004 \u0005[היה עוסק ב\u0006נשיאת \u0005קורות]\u0006 \u0003אמר: גדולה מלאכה שמחממת את בעליה.\u0004","אגב הסיפור על רב עמרם שהציקו לו עבדי ראש הגולה מספרים סיפור דומה, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ריש גלותא\u0004 \u0005[ראש הגולה]\u0006 \u0003לרב ששת: מאי טעמא לא סעיד מר גבן\u0004 \u0005[מה טעם אין אדוני סועד\u0006 \u0005אצלנו]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003דלא מעלו עבדי\u0004 \u0005[שהעבדים אינם בני מעלה],\u0006 \u0003דחשידי\u0004 \u0005[ש\u0006הם \u0005חשודים]\u0006 על אכילת \u0003אבר מן החי. אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מי יימר\u0004 \u0005[יאמר,\u0006 יוכיח\u0005]\u0006 שהם חשודים על כך? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003השתא מחוינא\u0004 \u0005[עכשיו אראה]\u0006 \u0003לך. אמר ליה\u0004 \u0005[לו]\u0006 רב ששת \u0003לשמעיה\u0004 \u0005[לשמשו]:\u0006 \u0003זיל\u0004 \u0005[לך]\u0006 \u0003גנוב, אייתי\u0004 \u0005[הבא]\u0006 \u0003לי חדא כרעא מחיותא\u0004 \u0005[רגל אחת מן הבהמה]\u0006 ששחטו עבדי ראש הגולה לסעודה.","\u0003אייתי ליה\u0004 \u0005[הביא לו].\u0006 אחר כך \u0003אמר להו\u0004 \u0005[להם]\u0006 רב ששת לאנשי ראש הגולה: \u0003אהדמו לי הדמי דחיותא\u0004 \u0005[סדרו לפני את חלקי הבהמה],\u0006 \u0003אייתו תלת כרעי אותיבו קמיה\u0004 \u0005[הביאו שלוש רגלים והניחו לפניו]\u0006 שהרי את הרגל הרביעית לקח השמש. \u0003אמר להו\u0004 \u0005[להם]\u0006 רב ששת: וכי \u0003הא\u0004 \u0005[\u0006בהמה \u0005זו]\u0006 \u0003בעלת שלש רגלים הואי\u0004 \u0005[היתה]?\u0006 שמעו זאת, \u0003פסוק, אייתו חדא מעלמא אותיבו קמיה\u0004 \u0005[חתכו\u0006 מבהמה אחרת חיה, ו\u0005הביאו אחת מהחוץ\u0006 ו\u0005הניחו לפניו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003לשמעיה\u0004 \u0005[לשמשו]:\u0006 \u0003אותביה נמי להך דידך\u0004 \u0005[הנח גם כן את זו שלך]\u0006 שאתה לקחת, \u0003אותבה\u0004 \u0005[הניח אותה].\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003האי\u0004 \u0005[\u0006בהמה \u0005זו]\u0006 \u0003בת חמש רגלים הואי\u0004 \u0005[היתה]?\u0006 כיון שראה ראש הגולה שבאמת אי אפשר לסמוך על עבדיו \u0003אמר ליה\u0004 \u0005[לו]\u0006 לרב ששת: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003ליעבדו קמיה שמעיה דמר וליכול\u0004 \u0005[שיעשו\u0006 יכינו את הבשר לאכילה \u0005לפני שמשו של אדוני ו\u0006אז יוכל \u0005לאכול]\u0006 בלי חשש, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לחיי\u0004 \u0005[בבקשה].\u0006 \u0003קריבו תכא קמייהו\u0004 \u0005[הביאו שולחן לפניהם],\u0006 \u0003ואייתו קמיה בישרא\u0004 \u0005[והביאו לפניו בשר]\u0006 \u0003ואותיבו קמיה ריסתנא דחנקא חמתא\u0004 \u0005[והניחו\u0006 העבדים \u0005לפניו\u0006 בתוך הבשר \u0005עצם קטנה שיכולה לחנוק],\u0006 שחשבו שמפני שהיה רב ששת עיוור לא ישים לב וייחנק בה, \u0003גששיה ושקלה\u0004 \u0005[מישש אותה ולקחה]\u0006 את כל החתיכה \u0003כרכה בסודריה\u0004 \u0005[בסודרו]\u0006 שחשש שמא יינזק בעצמות הקטנות שאינו רואה.","","\u0003לבתר דאכיל\u0004 \u0005[אחרי שאכלו]\u0006 שראו העבדים מה עשה רצו העבדים להראות לראש הגולה שרב ששת לא אכל מן הבשר שנתנו לו, \u0003אמרי ליה\u0004 \u0005[אמרו לו]\u0006 העבדים לראש הגולה:"],["\u0003איגניב לן כסא דכספא\u0004 \u0005[נגנבה לנו כוס כסף]!\u0006 ובדקו את כולם. \u0003בהדי דקא מעייני ואתי\u0004 \u0005[בזמן שהיו בודקים ובאים],\u0006 \u0003אשכחוה\u0004 \u0005[מצאוה]\u0006 את חתיכת הבשר שהיא \u0003כרוכה בסודריה\u0004 \u0005[בסודרו].\u0006","\u0003אמרי ליה\u0004 \u0005[אמרו לו]\u0006 העבדים לראש הגולה: \u0003חזי מר\u0004 \u0005[יראה אדוני]\u0006 ש\u0003לא מיכל קא בעי\u0004 \u0005[לאכול הוא רוצה]\u0006 \u0003אלא\u0004 רק \u0003לצעורן\u0004 \u0005[לצער אותנו]!\u0006 שהרי אחרי כל מה שנעשה למענו — לא אכל מסעודת ראש הגולה. \u0003אמר להו\u0004 \u0005[להם]\u0006 רב ששת: \u0003אנא מיכל אכלי, וטעמי ביה טעמא דחיורא\u0004 \u0005[אני אכלתי וטעמתי בו טעם של שחין]\u0006 ולכן לא גמרתי לאכול. \u0003אמרי ליה\u0004 \u0005[אמרו לו]\u0006 לראש הגולה: \u0003חיורא לא עביד לן האידנא\u0004 \u0005[\u0006בהמה בעלת \u0005שחין לא עשינו,\u0006 הכנו לאכילה, \u0005עכשיו\u0006 היום\u0005],\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 רב ששת: \u0003בדקו בדוכתיה\u0004 \u0005[במקומו]\u0006 באותו מקום שלקחתי, ש\u0003אמר רב חסדא: אוכמא בחיורא וחיורא באוכמתא\u0004 \u0005[שחור ב\u0006\u0003תוך\u0004 עור \u0005לבן ולבן ב\u0006תוך עור \u0005שחור]\u0006 — \u0003לקותא היא\u0004 \u0005[ליקוי הוא]\u0006 וסימן של חולי. \u0003בדוק אשכחוה\u0004 \u0005[בדקו ומצאו]\u0006 כדבריו, וכעסו העבדים עליו יותר.","\u0003כי קא נפיק, כרו ליה בירא ושדו ליה ציפתא עילויה\u0004 \u0005[כאשר היה יוצא\u0006 מבית ראש הגולה \u0005כרו לו בור ושמו מחצלת עליו]\u0006 שלא יוכר הדבר, \u0003ואמרי ליה\u0004 \u0005[ואמרו לו]:\u0006 \u0003ליתי מר לינח\u0004 \u0005[יבוא אדוני וינוח\u0006 קצת\u0005],\u0006 והתכוונו שיפול שם ויינזק. \u0003נחר ליה\u0004 \u0005[נחר לו]\u0006 השמיע קול \u0003רב חסדא מאחוריה\u0004 \u0005[מאחוריו]\u0006 לרמוז לו, \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב ששת \u0003לינוקא\u0004 \u0005[לילד]\u0006 שהיה שם: \u0003פסוק לי פסוקיך\u0004 \u0005[פסוקך]\u0006 שלמדת היום, \u0003אמר ליה\u0004 \u0005[לו]\u0006 את הפסוק: \u0003\"נטה לך על ימינך או על שמאלך\"\u0004 (שמואל ב ב, כא). \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב ששת, שהיה עיוור, \u0003לשמעיה\u0004 \u0005[לשמשו]:\u0006 \u0003מאי קא חזית\u0004 \u0005[מה אתה רואה]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ציפיתא דשדיא\u0004 \u0005[מחצלת שמוטלת]\u0006 על הקרקע, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הדר מינה\u0004 \u0005[פנה ממנה]\u0006 ונלך מסביב.","\u0003לבתר דנפק\u0004 \u0005[אחרי שיצא]\u0006 מבית ראש הגולה, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חסדא: מנא הוה ידע מר\u0004 \u0005[מניין היה אדוני יודע]\u0006 שיש בור כרוי במקום? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003חדא, דנחר לי מר\u0004 \u0005[אחת, שאדוני נחר לי]\u0006 והיה זה לי סימן שיש פה חשש. \u0003ועוד,\u0004 ש\u0003פסק לי ינוקא פסוקא\u0004 \u0005[התינוק פסוק]\u0006 שהוא רמז לדבר. \u0003ועוד, דחשידי עבדי דלא מעלו\u0004 \u0005[שחשודים עבדים שאינם בני מעלה]\u0006 והם עלולים לעשות כל דבר רע.","כיון שהוזכר שמו של מזיק בתחילת הענין מביאים עוד דברים מעניינים אלה. נאמר: \u0003\"עשיתי לי שרים ושרות\u0004 \u0003ותענגת בני האדם שדה ושדות\"\u0004 (קהלת ב, ח), ומסבירים: \u0003\"שרים ושרות\"\u0004 — \u0003אלו מיני זמר, \"ותענגת בני האדם\"\u0004 — \u0003אלו בריכות ומרחצאות, \"שדה ושדות\"\u0004 — \u0003הכא תרגימו\u0004 \u0005[כאן,\u0006 בבבל, \u0005תרגמו]\u0006 לשונות אלה: \u0003שידה ושידתין\u0004 \u0005[שד\u0006 זכר \u0005ושדות\u0006 נקיבות\u0005].\u0006 \u0003במערבא אמרי\u0004 \u0005[בארץ ישראל אמרו]:\u0006 \u0003שידתא\u0004 \u0005[שידה]\u0006 כלומר מרכבה.","\u0003אמר ר' יוחנן: שלש מאות מיני שדים היו ב\u0004מקום שנקרא \u0003שיחין, ושידה עצמה איני יודע מה היא.\u0004","\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003הכא תרגימו\u0004 \u0005[כאן תרגמו]:\u0006 \u0003שידא ושידתין\u0004 \u0005[שד ושדות].\u0006 ושואלים: \u0003שידה ושידתין למאי איבעי ליה\u0004 \u0005[למה היה צריך אותם]\u0006 שלמה? ומשיבים: \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בבניין בית המקדש: \u0003\"והבית בהבנתו אבן שלמה מסע נבנה\u0004 ומקבות והגרזן כל כלי ברזל לא נשמע בבית בהיבנותו\u0003\"\u0004 (מלכים א ו, ז), \u0003אמר\u0004 שלמה \u0003להו לרבנן\u0004 \u0005[להם לחכמים]:\u0006 \u0003היכי אעביד\u0004 \u0005[איך אעשה]\u0006 שהאבן תהיה מיושרת ומסותתת בלי להשתמש בברזל? \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003איכא שמירא דאייתי\u0004 \u0005[יש שמיר שהביא]\u0006 \u0003משה\u0004 וחתך בו את \u0003אבני אפוד.\u0004","\u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003היכא אישתכח\u0004 \u0005[היכן\u0006 הוא \u0005מצוי]?\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003אייתי שידה ושידתין כבשינהו אהדדי\u0004 \u0005[הבא שד ושדות,\u0006 ו\u0005תכבשם,\u0006 תלחצם \u0005יחד זה עם זה],\u0006 \u0003אפשר דידעי ומגלו\u0004 \u0005[ש\u0006הם \u0005יודעים ו\u0006מתוך שתלחצם \u0005יגלו]\u0006 \u0003לך.\u0004 עשה כן, \u0003אייתי שידה ושידתין כבשינהו אהדדי\u0004 \u0005[הביא שד ושידות כבשם זה עם זה],\u0006 \u0003אמרי\u0004 \u0005[אמרו]:\u0006 \u0003אנן לא ידעינן, דילמא\u0004 \u0005[אנו איננו יודעים, שמא]\u0006 \u0003אשמדאי מלכא דשידי ידע\u0004 \u0005[מלך השדים יודע].\u0006","\u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003היכא איתיה\u0004 \u0005[היכן\u0006 הוא \u0005נמצא]?\u0006 \u0003אמרי ליה\u0004 \u0005[אמרו לו]:\u0006 \u0003איתיה בטורא פלן\u0004 \u0005[\u0006הוא \u0005נמצא בהר פלוני].\u0006 \u0003כריא ליה בירא ומליא ליה מיא ומיכסיא בטינרא וחתמיה בגושפנקיה\u0004 \u0005[כרה,\u0006 חפר \u0005לו\u0006 שם \u0005בור ומילא אותו מים וכיסה\u0006 אותו בצור, בסלע, \u0005וחתמו בחותמו],\u0006 \u0003וכל יומא סליק\u0004 \u0005[וכל יום\u0006 הוא \u0005עולה]\u0006 \u0003לרקיע, וגמר מתיבתא דרקיעא\u0004 \u0005[ולומד בישיבה של מעלה],\u0006 \u0003ונחית לארעא וגמר מתיבתא דארעא\u0004 \u0005[ויורד לארץ ולומד בישיבה של הארץ],\u0006 \u0003ואתי סייר ליה לגושפנקיה\u0004 \u0005[ובא ובודק את חותמו]\u0006 \u0003ומגלי ליה ושתי, ומכסי ליה וחתים ליה ואזיל\u0004 \u0005[ומגלה אותו ושותה\u0006 מהמים שבבור, \u0005ומכסה אותו וחותם אותו\u0006 שוב \u0005והולך].\u0006","\u0003שדריה\u0004 \u0005[שלחו]\u0006 שלמה \u0003לבניהו בן יהוידע, יהב ליה שושילתא דחקיק עלה\u0004 \u0005[נתן לו שלשלת שחקוק עליה]\u0006 \u0003שם\u0004 קדוש, \u0003ועזקתא דחקיק עלה\u0004 \u0005[וטבעת שחקוק עליה]\u0006 \u0003שם,\u0004 \u0003וגבבי דעמרא וזיקי דחמרא\u0004 \u0005[וגיזות צמר ונאדות יין].\u0006 מה עשה בניהו? \u0003אזל כרא בירא מתתאי\u0004 \u0005[הלך כרה בור מלמטה],\u0006 מתחת הבור של אשמדאי \u0003ושפינהו למיא וסתמינהו בגבבי דעמרא\u0004 \u0005[ומשך את המים וסתם אותו בגיזות הצמר],\u0006 שישאר הבור של מעלה ריק ממים, \u0003וכרא בירא מעילאי\u0004 \u0005[וכרה בור מלמעלה]\u0006 מעל הבור של אשמדאי \u0003ושפכינהו לחמרא\u0004 \u0005[ושפך את היין]\u0006 באופן שירד היין אל תוך בורו של אשמדאי \u0003וטמינהו\u0004 \u0005[וסתם אותם]\u0006 את שני הבורות שחפר: התחתון והעליון. \u0003סליק יתיב באילנא\u0004 \u0005[עלה וישב באילן].\u0006","\u0003כי אתא סייריה לגושפנקא\u0004 \u0005[כאשר בא\u0006 אשמדאי \u0005בדק את חותמו],\u0006 \u0003גלייה\u0004 \u0005[פתח אותו]\u0006 את הבור \u0003אשכחיה חמרא\u0004 \u0005[מצא אותו\u0006 שהוא \u0005יין],\u0006 \u0003אמר: כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"לץ היין המה שכר וכל שגה בו לא יחכם\"\u0004 (משלי כ, א), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"זנות ויין ותירוש יקח לב\"\u0004 (הושע ד, יא), ומוטב להיזהר ממנו. \u0003לא אישתי\u0004 \u0005[שתה].\u0006 \u0003כי צחי\u0004 \u0005[כאשר צמא],\u0006 \u0003לא סגיא ליה, אישתי\u0004 \u0005[לא יכול היה\u0006 עוד להתאפק, ו\u0005שתה],\u0006 \u0003רוה וגנא\u0004 \u0005[השתכר וישן].\u0006","\u0003נחית, אתא, שדא ביה שושילתא סתמיה\u0004 \u0005[ירד ובא\u0006 בניהו מן העץ, \u0005זרק עליו\u0006 את \u0005השלשלת וסגר אותו\u0006 בתוכה\u0005].\u0006 \u0003כי אתער הוה קא מיפרזל\u0004 \u0005[כאשר התעורר\u0006 אשמדאי \u0005היה משתדל\u0006 לקרוע] את השלשלת, \u0003אמר ליה\u0004 \u0005[לו]\u0006 בניהו: \u0003שמא דמרך עלך,\u0004 \u0003שמא דמרך עלך\u0004 \u0005[שם אדוניך עליך, שם אדוניך עליך]\u0006 ואל תקרע את השלשלת, שהרי שם שמים כתוב עליה, ואסור להשחיתה.","\u0003כי נקיט ליה ואתי\u0004 \u0005[כאשר לקח אותו\u0006 בניהו את אשמדאי \u0005ובא]\u0006 לירושלים, \u0003מטא דיקלא חף ביה שדייה\u0004 \u0005[הגיע לדקל והתחכך בו, הפילו],\u0006 \u0003מטא לביתא שדייה\u0004 \u0005[הגיע לבית הפיל אותו],\u0006 \u0003מטא גבי כובא דההיא ארמלתא\u0004 \u0005[הגיע ליד צריף קטן של אלמנה אחת],\u0006 \u0003נפקא\u0004 \u0005[יצאה]\u0006 האלמנה"],["\u0003איחננא ליה\u0004 \u0005[התחננה לו]\u0006 שלא יפיל את ביתה, \u0003כפא לקומתיה מיניה\u0004 \u0005[כפף את קומתו ממנה]\u0006 לצד אחר, \u0003איתבר ביה גרמא\u0004 \u0005[נשברה בו עצם],\u0006 \u0003אמר: היינו דכתיב\u0004 \u0005[זהו שנאמר]:\u0006 \u0003\"ולשון רכה תשבר גרם\"\u0004 (משלי כה, טו).","\u0003חזא סמיא דהוה קא טעי באורחא, אסקיה לאורחיה\u0004 \u0005[ראה עיוור שהיה תועה בדרך, העלהו על הדרך\u0006 הנכונה\u0005].\u0006 \u0003חזא רויא דהוה קא טעי באורחא, אסקיה לאורחיה\u0004 \u0005[ראה שיכור שהיה תועה בדרך, העלהו על הדרך\u0006 הנכונה\u0005].\u0006 \u0003חזא חדוותא דהוו קמחדי לה\u0004 \u0005[ראה שמחה\u0006 של חתונה \u0005שהיו שמחים בה],\u0006 \u0003בכה. שמעיה לההוא גברא דהוה קאמר לאושכפא\u0004 \u0005[שמע אדם אחד שאמר לסנדלר]:\u0006 \u0003עביד לי מסאני לשב שני\u0004 \u0005[עשה לי נעליים לשבע שנים],\u0006 \u0003אחיך\u0004 \u0005[צחק].\u0006 \u0003חזא ההוא קסמא דהוה קסים, אחיך\u0004 \u0005[ראה קוסם אחד שעושה קסמים, צחק].\u0006","\u0003כי מטא להתם\u0004 \u0005[כאשר הגיע לשם]\u0006 לירושלים, \u0003לא עיילוה לגביה\u0004 \u0005[לא הכניסוהו לפני]\u0006 \u0003שלמה עד תלתא יומי\u0004 \u0005[שלושה ימים].\u0006 \u0003יומא קמא\u0004 \u0005[יום ראשון]\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא קא בעי לי מלכא לגביה\u0004 \u0005[רוצה אותי המלך\u0006 שאבוא \u0005אליו]?\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003אנסיה מישתיא\u0004 \u0005[אנסה אותו השתייה]\u0006 ששתה יותר מדי. \u0003שקל לבינתא אותיב אחברתה\u0004 \u0005[לקח לבינה\u0006 ו\u0005שם על חברתה].\u0006 \u0003אתו\u0004 \u0005[באו]\u0006 \u0003אמרו ליה\u0004 \u0005[לו]\u0006 \u0003לשלמה\u0004 את שעשה. \u0003אמר להו\u0004 \u0005[להם]\u0006 שלמה: \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר לכו\u0004 \u0005[לכם],\u0006 כך רמז: \u0003הדור אשקיוה\u0004 \u0005[חזרו\u0006 ו\u0005השקוהו]\u0006 את המלך.","\u0003למחר אמר להו\u0004 \u0005[להם]\u0006 אשמדאי: \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 \u0003לא קא בעי לי מלכא לגביה\u0004 \u0005[רוצה אותי המלך שאבוא אליו]?\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003אנסיה מיכלא\u0004 \u0005[אנסו,\u0006 הפריע לו \u0005המאכל].\u0006 \u0003שקל לבינתא\u0004 \u0005[הוריד לבינה]\u0006 מחברתה \u0003אותבה אארעא\u0004 \u0005[והניח אותה על הארץ].\u0006 \u0003אתו\u0004 \u0005[באו]\u0006 העבדים \u0003אמרו ליה\u0004 \u0005[לו]\u0006 \u0003לשלמה\u0004 את שעשה. \u0003אמר להו\u0004 \u0005[להם],\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר לכו\u0004 \u0005[לכם]:\u0006 \u0003נגידו מיניה מיכליה\u0004 \u0005[הרחיקו ממנו את מאכלו].\u0006","\u0003לסוף תלתא יומי\u0004 \u0005[שלושה ימים]\u0006 \u0003עייל לקמיה\u0004 \u0005[בא לפניו].\u0006 \u0003שקל קניא ומשח ארבעה גרמידי ושדא קמיה\u0004 \u0005[לקח\u0006 אשמדאי \u0005קנה ומדד ארבע אמות וזרק לפניו],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 לשלמה: \u0003מכדי כי מיית ההוא גברא לית ליה בהדין עלמא\u0004 \u0005[הרי כאשר ימות אותו אדם אין לו בעולם הזה]\u0006 \u0003אלא ארבעה גרמידי\u0004 \u0005[אמות]\u0006 של קבר, \u0003השתא כבשתיה לכולי עלמא\u0004 \u0005[עכשיו כבשתו את כל העולם]\u0006 \u0003ולא שבעת\u0004 \u0005[ואינך שבע]\u0006 \u0003עד\u0004 ש\u0003כבשת\u0004 \u0003נמי לדידי\u0004 \u0005[שתכבוש גם כן אותי]?\u0006","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא קא בעינא מינך מידי\u0004 \u0005[אין אני רוצה ממך דבר],\u0006 \u0003בעינא דאיבנייה\u0004 \u0005[רוצה אני שאבנה]\u0006 את \u0003בית המקדש וקא מיבעי\u0004 \u0005[ונצרך]\u0006 \u0003לי\u0004 לשם כך \u0003שמירא\u0004 [שמיר]. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לדידי\u0004 \u0005[לעצמי]\u0006 \u0003לא מסיר\u0004 \u0005[מסור]\u0006 \u0003לי, לשרא דימא מסיר ליה\u0004 \u0005[לשר הים\u0006 הוא \u0005מסור לו],\u0006 \u0003ולא יהיב ליה\u0004 \u0005[נותן אותו]\u0006 \u0003אלא לתרנגולא ברא דמהימן ליה אשבועתיה\u0004 \u0005[לתרנגול הבר שהוא נאמן לו בשבועתו]\u0006 שיחזירהו,","\u0003ומאי עבד ביה\u0004 \u0005[ומה עושה בו]\u0006 תרנגול הבר? \u0003ממטי ליה לטורי דלית בהו\u0004 \u0005[מביא אותו להרים שאין בהם]\u0006 \u0003ישוב,\u0004 \u0003ומנח לה אשינא דטורא\u0004 \u0005[ושם אותו את\u0006 השמיר \u0005על שן הסלע]\u0006 \u0003ופקע טורא\u0004 \u0005[וההר מתבקע],\u0006 \u0003ומנקיט מייתי ביזרני מאילני ושדי התם והוי\u0004 \u0005[ומביא זרעים מאילנות וזורק שם ונעשה]\u0006 \u0003ישוב. והיינו דמתרגמינן\u0004 \u0005[וזה שמתרגמים אנו]:\u0006 \"דוכיפת\" = \u0003נגר טורא\u0004 \u0005[חותך ההרים].\u0006","\u0003בדקו\u0004 ומצאו \u0003קינא דתרנגולא ברא דאית ליה בני\u0004 \u0005[קן של תרנגול בר שיש לו בנים\u0006 אפרוחים\u0005],\u0006 \u0003וחפויה לקיניה זוגיתא חיורתי\u0004 \u0005[וחיפו את הקן בזכוכית לבנה,\u0006 שקופה\u0005].\u0006 \u0003כי אתא בעי למיעל ולא מצי\u0004 \u0005[כאשר בא\u0006 התרנגול \u0005רצה להיכנס ולא היה יכול],\u0006 \u0003אזל אייתי שמירא ואותביה עלויה\u0004 \u0005[הלך הביא שמיר והושיב אותו עליו]\u0006 שתיבקע הזכוכית, \u0003רמא ביה קלא\u0004 \u0005[הטיל בו\u0006 שליחו של שלמה \u0005רגב\u0006 אדמה\u0005],\u0006 \u0003שדייה\u0004 \u0005[הפיל]\u0006 העוף את השמיר, \u0003שקליה\u0004 \u0005[ולקח אותו]\u0006 האיש, \u0003אזל חנק נפשיה אשבועתיה\u0004 \u0005[הלך\u0006 תרנגול הבר ו\u0005חנק את עצמו על שבועתו],\u0006 כלומר, שלא היה נאמן בשבועתו, שלא החזיר את השמיר.","לאחר זמן \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003בניהו\u0004 לאשמדאי: \u0003מאי טעמא כי חזיתיה לההוא סמיא דהוה קא טעי באורחא, אסיקתיה לאורחיה\u0004 \u0005[מה הטעם כאשר ראית את העיוור ההוא שתועה בדרך, העלית אותו על דרכו]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מכרזי עליה ברקיעא\u0004 \u0005[מכריזים עליו ברקיע]\u0006 ש\u0003צדיק גמור הוא, ומאן דעבד ליה ניחא נפשיה זכי לעלמא דאתי\u0004 \u0005[ומי שיעשה לו טוב לנפשו יזכה לעולם הבא].\u0006","ועוד שאל אותו: \u0003ומאי טעמא כי חזיתיה לההוא רויא דקטעי באורחא, אסיקתיה לאורחיה\u0004 \u0005[ומה הטעם כאשר ראית את השיכור שתועה בדרך, העלית אותו על דרכו]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מכרזי עליה ברקיעא\u0004 \u0005[מכריזים עליו ברקיע]\u0006 ש\u0003רשע גמור הוא, ועבדי ליה ניחא נפשיה\u0004 \u0005[ועשיתי לו נחת לנפשו]\u0006 \u0003כי היכי דליכליה לעלמא\u0004 \u0005[כדי שיאכל את עולמו],\u0006 את שכרו, בעולם הזה, ולא יהיה לו כל שכר לעולם הבא.","ועוד שאל בניהו: \u0003מאי טעמא כי חזיתיה לההוא חדוותא, בכית\u0004 \u0005[מה טעם כאשר ראית את השמחה\u0006 של החתונה \u0005בכית]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003בעי מימת גברא בגו תלתין יומין\u0004 \u0005[\u0006ידעתי ש\u0005צריך\u0006 אותו \u0005האיש למות בתוך שלושים יום],\u0006 \u0003ובעיא מינטר\u0004 \u0005[ותצטרך\u0006 האשה \u0005לחכות]\u0006 \u0003ליבם קטן תליסרי שנין\u0004 \u0005[שלוש עשרה שנה]\u0006 עד שיגיע לגיל בגרות ויוכל לחלוץ לה.","עוד שאלו: \u0003מאי טעמא כי שמעתיה לההוא גברא דאמר ליה לאושכפא עביד לי מסאני לשב שנין, אחיכת\u0004 \u0005[מה טעם כאשר שמעת את האיש ההוא שאמר לו לסנדלר עשה לי נעליים לשבע שנים, צחקת]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ההוא,\u0004 אותו אדם, \u0003שבעה יומי לית ליה, מסאני לשב שנין בעי\u0004 \u0005[שבעה ימים אין לו\u0006 לחיות, \u0005נעליים לשבע שנים הוא צריך]?!\u0006","ועוד שאל: \u0003מאי טעמא כי חזיתיה לההוא קסמא דהוה קסים, אחיכת\u0004 \u0005[מה טעם כאשר ראית את הקוסם ההוא שהוא עושה קסמים, צחקת]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003דהוה יתיב אבי גזא דמלכא, לקסום מאי דאיכא תותיה\u0004 \u0005[שהיה יושב על אוצר המלך, שיקסום\u0006 וידע \u0005מה שיש מתחתיו]!\u0006","\u0003תרחיה גביה\u0004 \u0005[עיכבו\u0006 שלמה \u0005אצלו]\u0006 \u0003עד דבנייה\u0004 \u0005[ש\u0006גמר \u0005לבנות\u0006\u0005]\u0006 את \u0003בית המקדש.\u0004 \u0003יומא חד הוה קאי לחודיה\u0004 \u0005[יום אחד היה עומד\u0006 שלמה עם אשמדאי \u0005לבדו],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 לאשמדאי: \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"כתועפת ראם לו\"\u0004 (במדבר כד, ח), \u0003ואמרינן\u0004 \u0005[ואמרנו,\u0006 פירשנו\u0005]:\u0006 \u0003\"כתועפת\"\u0004 — \u0003אלו מלאכי השרת, \"ראם\"\u0004 — \u0003אלו השדים, מאי רבותייכו מינן\u0004 \u0005[מה גדולתכם מאיתנו],\u0006 במה כוחכם שהכתוב מתפאר בכוחכם?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003שקול שושילתא מינאי והב לי עיזקתך, ואחוי לך רבותאי\u0004 \u0005[הורד את השלשלת ממני ותן לי את חותמך, ואראה לך את כוחי].\u0006 \u0003שקליה לשושילתא מיניה ויהיב ליה עיזקתיה\u0004 \u0005[הוריד שלמה את השלשלת ממנו ונתן לו את חותמו],\u0006 \u0003בלעיה\u0004 \u0005[בלע אותו]\u0006 את החותם, וגדל מאוד עד ש\u0003אותביה לחד גפיה ברקיעא ולחד גפיה בארעא\u0004 \u0005[שם את כנף אחת שלו ברקיע ואת כנף אחת בארץ].\u0006 \u0003פתקיה ארבע מאה פרסי\u0004 \u0005[זרק אותו,\u0006 את שלמה, משם, מהלך \u0005ארבע מאות פרסות].\u0006 \u0003על ההיא שעתא\u0004 \u0005[אותה שעה]\u0006 \u0003אמר שלמה: \"מה יתרון לאדם בכל עמלו שיעמל תחת השמש\"\u0004 (קהלת א, ג).","ועל אותה שעה אמר שלמה \u0003\"וזה היה חלקי מכל עמלי\"\u0004 (קהלת ב, י) ומביאים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"וזה\"?\u0004 שנראה כמרמז לדבר המצוי בידו ממש, \u0003רב ושמואל\u0004 נחלקו בכך, \u0003חד\u0004 \u0005[אחד]\u0006 מהם \u0003אמר: מקלו,\u0004 זה מה שנשאר בידו, \u0003וחד\u0004 \u0005[ואחד]\u0006 מהם \u0003אמר: גונדו\u0004 (המעיל שלו). \u0003היה מחזר על הפתחים\u0004 למזון, \u0003כל היכא דמטא אמר\u0004 \u0005[בכל מקום שהיה מגיע היה אומר]:\u0006 \u0003\"אני קהלת הייתי מלך על ישראל בירושלם\"\u0004 (קהלת א, יב). \u0003כי מטא גבי\u0004 \u0005[כאשר הגיע\u0006 לבסוף \u0005אצל]\u0006 \u0003סנהדרין\u0004 שבירושלים, \u0003אמרו רבנן\u0004 \u0005[חכמים]:\u0006 \u0003מכדי שוטה בחדא מילתא לא סריך\u0004 \u0005[הרי שוטה אינו נדבק בדבר אחד\u0006 כל הזמן\u0005],\u0006 ואם כן \u0003מאי האי\u0004 \u0005[מהו\u0006 ענין \u0005זה]?\u0006 אולי יש לחשוש שיש ממש בדבריו?","\u0003אמרו ליה\u0004 \u0005[לו]\u0006 \u0003לבניהו: קא בעי לך מלכא לגביה\u0004 \u0005[האם המלך מבקש אותך אליו]?\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003לא. שלחו להו\u0004 \u0005[להם]\u0006 \u0003למלכוותא\u0004 \u0005[למלכות]:\u0006 \u0003קאתי מלכא לגבייכו\u0004 \u0005[\u0006האם \u0005המלך בא אצלכן]?\u0006 \u0003שלחו להו\u0004 \u0005[להם]:\u0006 \u0003אין קאתי\u0004 \u0005[כן, הוא בא].\u0006 \u0003שלחו להו\u0004 \u0005[להן]:\u0006 \u0003בידקו בכרעיה\u0004 \u0005[ברגליו]\u0006 האם הן כרגליו של בן אדם. \u0003שלחו\u0004 המלכות \u0003להו\u0004 \u0005[להם]:\u0006 \u0003במוקי קאתי\u0004 \u0005[בגרביים הוא בא]\u0006 ואי אפשר לראות את רגליו.","וסיפרו עוד עליו, \u0003וקא תבע להו בנידותייהו\u0004 \u0005[והוא תובע אותן\u0006 לתשמיש \u0005ב\u0006זמן \u0005נידתן],\u0006 \u0003וקא תבע לה נמי\u0004 \u0005[והוא תובע גם כן אותה],\u0006 את \u0003בת שבע אימיה\u0004 \u0005[אימו]\u0006 לתשמיש. כיון שכך הבינו שאין זה שלמה אלא אחר, \u0003אתיוה\u0004 \u0005[הביאו]\u0006 את \u0003שלמה והבו ליה עזקתא ושושילתא דחקוק עליה\u0004 \u0005[ונתנו לו חותם ושלשלת שחקוק עליה]\u0006 \u0003שם.\u0004 \u0003כי עייל חזייה, פרח\u0004 \u0005[כאשר נכנס\u0006 שלמה \u0005ראה אותו\u0006 אשמדאי, \u0005ברח].\u0006","ומוסיפים: \u0003ואפילו הכי\u0004 \u0005[כך]\u0006 למרות שברח, \u0003הוה ליה ביעתותא מיניה\u0004 \u0005[היה לו\u0006 לשלמה \u0005פחד ממנו,\u0006 מאשמדאי\u0005].\u0006 \u0003והיינו דכתיב\u0004 \u0005[וזהו שנאמר]:\u0006 \u0003\"הנה מטתו שלשלמה ששים גברים סביב לה מגברי ישראל כלם אחזי חרב מלמדי מלחמה איש חרבו על ירכו מפחד בלילות\"\u0004 (שיר השירים ג, ז-ח).","ועוד נחלקו \u0003רב ושמואל\u0004 בענין שלמה, \u0003חד\u0004 \u0005[אחד]\u0006 מהם \u0003אמר:\u0004 היה \u0003מלך ו\u0004אחר כך נעשה \u0003הדיוט\u0004 ולא חזר למלכותו כמקודם, \u0003וחד\u0004 \u0005[ואחד]\u0006 מהם \u0003אמר: מלך והדיוט ומלך,\u0004 שחזר למלכותו.","ומכאן באים שוב לענין שהתחלנו בו את את הפרק, בענין סגולות ורפואות שונות: התרופה \u0003לדמא דרישא\u0004 \u0005[לדם שבראש],\u0006 כאב ראש הבא מחמת רוב דם — \u0003ליתי שורבינא\u0004 \u0005[יביא ארז]\u0006 \u0003ובינא\u0004 \u0005[וערבה]\u0006 \u0003ואסא דרא\u0004 \u0005[והדס לח],\u0006 \u0003וזיתא\u0004 \u0005[וזית]\u0006 \u0003וחילפא\u0004 \u0005[צפצפה],\u0006 \u0003וחילפי דימא\u0004 \u0005[וערבות ים],\u0006 \u0003ויבלא\u0004 (מין עשב), \u0003ולישלוקינהו בהדי הדדי\u0004 \u0005[ויבשל אותם יחד],\u0006 \u0003ולנטול תלת מאה כסי אהאי גיסא דרישא\u0004 \u0005[וישפוך שלוש מאות כוסות\u0006 מן המשקה הזה \u0005על צד זה של הראש],\u0006 \u0003ותלת מאה כסי אהאי גיסא דרישא\u0004 \u0005[ושלוש מאות כוסות על צד זה של ראשו].\u0006","\u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא,\u0004 אינו מועיל, או אין בידו דברים אלה, \u0003ליתי ורדא חיורא דקאי בחד דרא\u0004 \u0005[יביא ורד לבן שעומד בשורה אחת],\u0006 כלומר, ורד שגדל לבדו \u0003ולישלקיה\u0004 \u0005[ויבשל אותו],\u0006 \u0003ולינטול שיתין כסי אהאי גיסא דרישא\u0004 \u0005[וישפוך שישים כוסות על צד זה של הראש],\u0006 \u0003ושיתין כסי אהאי גיסא דרישא\u0004 \u0005[ושישים כוסות על צד זה של הראש].\u0006","התרופה \u0003לצליחתא\u0004 \u0005[לכאב חצי ראש]\u0006 — \u0003ליתי תרנגולא ברא\u0004 \u0005[יקח תרנגול בר],\u0006 \u0003ולישחטיה בזוזא חיורא\u0004 \u0005[וישחט אותו בדינר כסף]\u0006 \u0003אההוא גיסא דכייב ליה\u0004 \u0005[על אותו צד שכואב לו],\u0006 \u0003ונזדהר מדמיה\u0004 \u0005[ויזהר מדמו]\u0006 ש\u0003לא לסמינהו לעיניה\u0004 \u0005[יעוור את עיניו],\u0006 \u0003וליתלייה בסיפא דבבא\u0004 \u0005[ויתלה אותו בסף הדלת],\u0006 \u0003דכי עייל חייף ביה, וכי נפיק חייף ביה\u0004 \u0005[שכאשר הוא נכנס הוא מתחכך בו, וכאשר הוא יוצא הוא מתחכך בו].\u0006"],["התרופה \u0003לברוקתי\u0004 \u0005[למחלת העין]\u0006 — \u0003ליתי עקרבא דשב חומרי\u0004 \u0005[יקח עקרב של שבעה גוונים]\u0006 \u0003ונייבשיה בטולא\u0004 \u0005[וייבש אותו בצל],\u0006 \u0003ונישחוק תרתי מנתא כוחלא וחדא מנתא מיניה\u0004 \u0005[וישחוק שתי מנות\u0006 של \u0005כחול ומנה אחת ממנו],\u0006 \u0003ולימלי תלתא מכחלי בהאי עינא\u0004 \u0005[וישים שלושה\u0006 מלוא \u0005מכחולים בעין זו]\u0006 \u0003ותלתא מכחלי בהאי עינא\u0004 \u0005[ושלושה מכחולים בעין זו],\u0006 \u0003טפי\u0004 \u0005[יותר]\u0006 \u0003לא לימלי\u0004 \u0005[ישים],\u0006 \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לא\u0004 כן — \u0003פקע עיניה\u0004 \u0005[תפקע עינו].\u0006","התרופה \u0003לשברירי דליליא\u0004 \u0005[לסנוורים של לילה]\u0006 — \u0003ניתי שודרא ברקא\u0004 \u0005[יביא חבל של שיער]\u0006 \u0003וניסר חדא כרעא מיניה וחדא כרעא מכלבא\u0004 \u0005[ויקשור רגל אחת שלו ורגל אחת של הכלב],\u0006 \u0003וניטרפו ינוקי חספא אבתריה\u0004 \u0005[ויזרקו ילדים חרס אחריו],\u0006 \u0003ולימרו ליה\u0004 \u0005[ויאמרו לו]:\u0006 \u0003אסא כלבא אכסא תרנגולא\u0004 \u0005[זקן הכלב שוטה התרנגול],\u0006 \u0003וליגבי שב אומצי\u0004 \u0005[ויגבה שבע אומצות,\u0006 חתיכות בשר\u0005]\u0006 \u0003משבעה בתי\u0004 \u0005[בתים]\u0006 \u0003וליתבינהו ניהליה בצינורא דדשא\u0004 \u0005[ויניחו לו אותן בחור הדלת],\u0006 \u0003וניכלינהו בקלקולי דמתא\u0004 \u0005[ויאכלם על אשפות העיר].\u0006 \u0003בתר הכי לפשוט שודרא ברקא\u0004 \u0005[אחרי זה יתיר את החבל]\u0006 \u0003ונימרו הכי\u0004 \u0005[ויאמרו כך]:\u0006 \u0003\"שברירי\u0004 \u0005[השברירים]\u0006 של \u0003פלוני בר פלוניתא\u0004 \u0005[בן פלונית]\u0006 \u0003שבקינהו לפלוני בר פלוניתא\u0004 \u0005[עזבו את פלוני בן פלונית]\u0006 \u0003וליחרו לכלבא\u0004 \u0003בבביתא דעיניה\u0004 \u0005[ויידבקו לכלב בבבת,\u0006 באישון, \u0005עינו]\u0006\u0003\".\u0004","התרופה \u0003לשברירי דיממא\u0004 \u0005[לסנוורים של יום]\u0006 — \u0003ליתי\u0004 \u0005[יביא]\u0006 \u0003שבעה סומקי מגווא דחיותא\u0004 \u0005[טחולים מתוך בהמות]\u0006 \u0003וניטוינהו אחספא דאומנא\u0004 \u0005[ויצלם על החרס של מקיז דם],\u0006 \u0003וליתיב איהו מגואי\u0004 \u0005[וישב הוא מבפנים]\u0006 \u0003ואיניש אחרינא מאבראי\u0004 \u0005[ואדם אחר מבחוץ],\u0006 \u0003ונימא ליה\u0004 \u0005[ויאמר לו]:\u0006 \u0003עוירא\u0004 \u0005[עיוור],\u0006 \u0003הב\u0004 \u0005[תן]\u0006 \u0003לי דאיכול\u0004 \u0005[שאוכל],\u0006 \u0003ונימא ליה האיך\u0004 \u0005[ויאמר לו האחר]:\u0006 \u0003פתיחא, סב איכול\u0004 \u0005[פיקח, קח ואכול],\u0006 \u0003ובתר דאכיל ליתבריה לחספא\u0004 \u0005[ואחרי שאוכל שישבור את החרס],\u0006 \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לא\u0004 כן — \u0003הדרי עילויה\u0004 \u0005[יחזרו עליו]\u0006 הסנוורים.","התרופה \u0003לדמא דאתי מנחירא\u0004 \u0005[לדם שיוצא מן הנחיריים]\u0006 — \u0003ליתי גברא\u0004 \u0005[יביא אדם]\u0006 \u0003כהן דשמיה\u0004 \u0005[ששמו]\u0006 הוא \u0003לוי,\u0004 \u0003וליכתוב ליה\u0004 \u0005[ויכתוב לו]\u0006 את השם \u0003לוי למפרע\u0004 (הפוך). \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 יכול לעשות כך, \u0003ליתי איניש מעלמא\u0004 \u0005[יביא סתם אדם],\u0006 \u0003וניכתוב ליה\u0004 \u0005[ויכתוב לו]\u0006 בלשון זו: \u0003\"אנא\u0004 \u0005[אני]\u0006 \u0003פפי שילא בר סומקי\".\u0004 ויכתוב זאת \u0003למפרע.\u0004","\u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא, ניכתוב ליה הכי\u0004 \u0005[יכתוב לו כך]:\u0006 \u0003טעם דלי במי כסף טעם דלי במי פגם. ואי\u0004 \u0005[ואם]\u0006 \u0003לא, ליתי עיקרא דאספסתא\u0004 \u0005[יביא שורש של אספסת],\u0006 \u0003ואשלא דפורייא עתיקא\u0004 \u0005[וחבל של מיטה ישנה],\u0006 \u0003וקורטסא\u0004 \u0005[ונייר],\u0006 \u0003ומוריקי\u0004 \u0005[וכרכום],\u0006 \u0003וסומקא דלוליבא\u0004 \u0005[וחלק\u0006 \u0005האדום,\u0006 העטיפה \u0005של הלולב],\u0006 \u0003ונקלינהו בהדי הדדי\u0004 \u0005[וישרוף אותם יחד],\u0006 \u0003וליתי גבבא דעמרא\u0004 \u0005[ויביא גיזת צמר]\u0006 \u0003וניגדול תרתי פתילתא\u0004 \u0005[וישזור\u0006 מהם \u0005שתי פתילות],\u0006 \u0003ולטמיש בחלא\u0004 \u0005[וישים אותן בחומץ]\u0006 \u0003וניגדבל בקיטמא הדין\u0004 \u0005[ויגלגל את הפתילות באפר הזה],\u0006 \u0003וניתיב בנחיריה\u0004 \u0005[וישים\u0006 אותן \u0005בנחיריו].\u0006","\u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא, ליחזי\u0004 \u0005[שיראה]\u0006 \u0003אמת המים דאזלת\u0004 \u0005[שהולכת]\u0006 \u0003ממזרח כלפי מערב, ונפסע וניקום חד כרעא להאי גיסא וחד כרעא להאי גיסא\u0004 \u0005[ויפסע,\u0006 יפתח רגליו, \u0005ויעמיד רגל אחת לצד זה ורגל אחת לצד זה],\u0006 \u0003ונישקול טינא בידיה דימינא מתותי כרעא דשמאליה\u0004 \u0005[ויקח טיט ביד ימינו מתחת רגלו השמאלית],\u0006 \u0003ובידיה דשמאלא מתותי כרעא דימיניה\u0004 \u0005[ובידו השמאלית מתחת רגלו הימנית],\u0006 \u0003וניגדול תרתי פתילתא דעמרא\u0004 \u0005[וישזור שתי פתילות של צמר]\u0006 \u0003וניטמיש בטינא\u0004 \u0005[וישים\u0006 אותן \u0005בטיט],\u0006 \u0003וניתיב בנחיריה\u0004 \u0005[וישים בנחיריו].\u0006","\u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא, ליתיב תותי מרזבא ונייתו מיא ולישדו עליה\u0004 \u0005[ישב תחת המרזב ויביאו מים וישפכו עליו],\u0006 \u0003ולימרו\u0004 \u0005[ויאמרו]:\u0006 \u0003\"כי היכי דפסקי הני מיא, ליפסוק דמיה דפלניא בר פלניתא\u0004 \u0005[כמו שפוסקים המים, שיפסוק דמו של פלוני בן פלונית].\u0006","\u0003לדמא דאתי מפומא\u0004 \u0005[לדם שבא,\u0006 שיוצא \u0005מהפה]\u0006 — \u0003בדקינן ליה בגילא דחיטתא\u0004 \u0005[בודקים אותו בקש של חיטה]\u0006 ורואים, \u0003אי סריך\u0004 \u0005[אם\u0006 הוא \u0005נדבק]\u0006 — \u0003מריאה קאתי\u0004 \u0005[הוא בא]\u0006 \u0003ואית ליה תקנתא\u0004 \u0005[ויש לו תקנה],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 — \u0003מכבדא קאתי ולית ליה תקנתא\u0004 \u0005[מן הכבד הוא בא ואין לו תקנה].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אמי לרב אשי: והאנן איפכא תנן\u0004 \u0005[והרי אנו ההיפך שנינו]:\u0006 אם \u0003ניטל הכבד ולא נשתייר הימנה כלום\u0004 — הרי זו טריפה, \u0003הריאה שניקבה או שחסרה\u0004 עושה טריפה. משמע שפגיעה בריאה מסוכנת יותר מפגיעה בכבד, שכן די שתינקב הריאה כדי לעשות טריפה, ואילו כבד — רק אם ניטל לגמרי! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כיון דמפומיה קאתי\u0004 \u0005[שמפיו יוצא\u0006 הדם\u0005],\u0006 \u0003אימר איתמוחי איתמח\u0004 \u0005[אמור שכבר נמחה]\u0006 הכבד, ולא יוכל לחיות.","\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003מריאה קאתי\u0004 \u0005[יוצא]\u0006 הדם \u0003אית ליה תקנתא\u0004 \u0005[יש לו תקנה].\u0006 ושואלים: \u0003מאי תקנתיה\u0004 \u0005[מה תקנתו]?\u0006 ומשיבים: \u0003ליתי\u0004 \u0005[יביא]\u0006 \u0003שבעה כוני מפירמא דסילקא\u0004 \u0005[מלוא אגרוף מקניבת תרד],\u0006 \u0003ושבעה כוני פירמא דכרתי\u0004 \u0005[מלוא אגרוף של הצמח כרישים],\u0006 \u0003וחמשה כוני פרידא\u0004 \u0005[מלוא אגרוף של מין עשב],\u0006 \u0003ותלתא כוני דטלפחי\u0004 \u0005[ושלושה מלוא אגרוף של עדשים],\u0006 \u0003וכונא דכמונא\u0004 \u0005[ומלוא אגרוף של כמון]\u0006 \u0003וכונא דחבלי\u0004 \u0005[ומלוא אגרוף של חבלים],\u0006 \u0003וכנגדן\u0004 כשיעור אלה \u0003כנתא פטירתא\u0004 \u0005[מעי של בהמה בכורה]\u0006 \u0003וליבשיל\u0004 \u0005[ולבשל]\u0006 את כולם \u0003וליכול\u0004 \u0005[ויאכל]\u0006 את הכל \u0003ולישתי אבתריה שיכרא חריפא דטבת\u0004 \u0005[וישתה אחריו שיכר חריף שטוב].\u0006","התרופה \u0003לככא\u0004 \u0005[ל\u0006כאב \u0005שיניים]\u0006 — \u0003אמר רבה בר רב הונא: ליתי תומא יחידאה ונימרסיה במישחא ומילחא\u0004 \u0005[יביא שום יחיד\u0006 שגדל לבדו \u0005וישחקנו בשמן ומלח],\u0006 \u0003ונתביה אטופראי דאליונא דההוא גיסא דכייב ליה\u0004 \u0005[וישים אותו על הציפורן של הבוהן של אותו צד שכואב לו],\u0006 \u0003ונהדר ליה גדנפא דלישא\u0004 \u0005[וישים לו שוליים של בצק],\u0006 \u0003וניזדהר לבישריה דקשי לחיורא\u0004 \u0005[ויזהר\u0006 שלא יגע \u0005בבשרו\u0006 מפני \u0005ש\u0006הוא \u0005קשה\u0006 ויכול לגרום \u0005לשחין].\u0006","התרופה \u0003לחינכי\u0004 \u0005[ל\u0006כאב \u0005החניכיים]\u0006 — \u0003אמר ר' יוחנן:\u0004 הצמח \u0003חומתי\u0004 טוב \u0003כי\u0004 \u0005[כמו]\u0006 הצמח \u0003ממרו, ועיקרא\u0004 \u0005[והשורש]\u0006 של \u0003חומתי עדיף מממרו, ונינקוט בפומיה\u0004 \u0005[וישים אותם בפיו].\u0006 \u0003הני לאוקומי\u0004 \u0005[אלה להעמיד]\u0006 שהחולי לא יחמיר. \u0003לבשולי\u0004 \u0005[לבשל]\u0006 כלומר, לגרום שהפצעים ייפתחו כדי שיוכל אחר כך להוציא המוגלה מהם — \u0003לייתי פארי דריש נפייא\u0004 \u0005[יביא סובין\u0006 הנמצאים \u0005בראש הנפה],\u0006 כלומר, סובין גדולים שנשארים בחלק העליון של הנפה, \u0003וטלפחי בעפרייהו\u0004 \u0005[ועדשים בעפרם],\u0006 \u0003ושובלילתא\u0004 \u0005[ותלתן]\u0006 \u0003וחומרתא דכשותא\u0004 \u0005[ופרח של הכישות],\u0006 \u0003ונינקוט כאמגוזא בפומיה\u0004 \u0005[ויקח כ\u0006מלוא \u0005אגוז בפיו].\u0006","אם רצונו \u0003לאיפתוחי\u0004 \u0005[לפתוח]\u0006 את הבועות שתצא הליחה — \u0003לינפח ליה חבריה תחלי חיורתא בגילא דחיטתא\u0004 \u0005[שיכניס לו חבירו בגרונו שחליים לבנים בקש של חיטה].\u0006 ואם רצונו \u0003לאסוקי\u0004 \u0005[להעלות]\u0006 בשר שירפא את הבקעים הללו — \u0003ליתי עפרא מטולא\u0004 \u0005[יביא עפר שנמצא בצילו]\u0006 של \u0003בית הכסא, וניגבול בדובשא\u0004 \u0005[ויגבל אותו בדבש]\u0006 \u0003וניכול\u0004 \u0005[ויאכל],\u0006 \u0003דמעלי ליה\u0004 \u0005[שמועיל לו]\u0006 הדבר הזה.","\u0003ל\u0004חולי שקוראים \u0003ברסם\u0004 — \u0003ליתי כי פיסתקא דנישדור\u0004 \u0005[יביא כשיעור אגוז של נשדור,\u0006 אמוניה\u0005],\u0006 \u0003וכי אמגוזא דחלבניתא דובשניתא\u0004 \u0005[וכ\u0006שיעור \u0005אגוז של חלבנה מתוקה],\u0006 \u0003ומלי תרוודא דובשא חיורא\u0004 \u0005[ומלוא תרווד דבש לבן],\u0006 \u0003ומלי נטלא בת מחוזא חמרא נקידא\u0004 \u0005[ומלוא כלי של מחוזא יין צלול],\u0006 \u0003ונישלוקינהו בהדי הדדי\u0004 \u0005[ויבשל אותם יחד],\u0006 \u0003וכי בשיל נשדור בשיל ליה כוליה\u0004 \u0005[וכאשר יתבשל הנשדור יתבשל לו הכל].\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא, ליתי רביעתא דחלבא דעיזא חיוורתי\u0004 \u0005[יביא רביעית חלב של עז לבנה]\u0006"],["\u0003וניטייפיה אתלת\u0004 \u0005[ויטפטף אותו על שלושה]\u0006 \u0003קלחי כרבא\u0004 \u0005[כרוב],\u0006 \u0003וניבחשיה בגווזא\u0004 \u0005[ויבחש אותו בענף]\u0006 של עץ \u0003מרמהין,\u0004 \u0003וכי בשיל גווזא במרמהין בשיל ליה כוליה\u0004 \u0005[וכאשר יתבשל הענף של המרמהין יבשל אותו כולו].\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא, ליתי נפקי דכלבא חיורא\u0004 \u0005[יקח צואה של כלב לבן]\u0006 \u0003וניגבול בנטפא\u0004 \u0005[ויגבל,\u0006 יערבב אותו \u0005בצרי],\u0006 \u0003וכמה\u0004 ש\u0003אפשר נפקא\u0004 \u0005[\u0006ש\u0005צואה]\u0006 \u0003לא ניכול\u0004 \u0005[יאכל]\u0006 משום \u0003דמפריק\u0004 \u0005[ש\u0006גורמת \u0005לפירוק\u0006 איברים\u0005].\u0006","התרופה \u0003לגירא\u0004 \u0005[לכאב של דקירות]\u0006 — \u0003ליתי גירא דלילתא וניפכיה\u0004 \u0005[יקח חץ של לילית,\u0006 מטאור, \u0005ויהפכנו],\u0006 \u0003ונשדי מיא עלויה ונשתי\u0004 \u0005[וישפוך מים עליו וישתה].\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא, ליתי ממיא דאישתי מינייהו כלבא בליליא, וניזדהר מגילויא\u0004 \u0005[יביא ממים ששתה מהם כלב בלילה, ויזהר מגילוי]\u0006 שלא היו המים מגולים בלילה, שמא שתה מהם נחש והטיל בהם ארסו. העצה \u0003לגילויא\u0004 \u0005[לגילוי],\u0006 לשותה ממים שיש חשש ששתה מהם נחש — ישתה \u0003אנפקא דחמרא חייא\u0004 \u0005[רביעית של יין חי].\u0006","התרופה \u0003למורסא\u0004 \u0005[לפצע של מוגלה]\u0006 — \u0003אנפקא דחמרא באהלא תולאנא\u0004 \u0005[רביעית יין בתוך אהל אדום].\u0006","התרופה \u0003לפירחא דליבא\u0004 \u0005[לפריחת הלב],\u0006 שליבו דופק מהר מדי — \u0003ליתי תלת ברושייאתא דשע רי\u0004 \u0005[יביא שלוש חלות של שעורים]\u0006 \u0003ונשטרינהו בכמכא\u0004 \u0005[וישרה אותם בתוך כותח]\u0006 ש\u0003לא עבר עילויה\u0004 \u0005[עליו]\u0006 עדיין \u0003ארבעין יומין\u0004 \u0005[ארבעים יום]\u0006 מאז שנעשה, \u0003וניכול,\u0004 \u0005[ויאכל אותן],\u0006 \u0003ונשתי אבתרייהו חמרא מרקא\u0004 \u0005[וישתה אחריהן יין מזוג].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא מדיפתי לרבינא: וכל שכן דפרח ליביה\u0004 \u0005[שיפרח ליבו]\u0006 מהדברים האלה! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אנא\u0004 \u0005[אני]\u0006 — \u0003ליוקרא דליבא אמרי\u0004 \u0005[\u0006\u0005לכובד הלב אמרתי]\u0006 תרופות אלה, והתרופה","\u0003לפירחא דליבא\u0004 \u0005[לפריחת הלב]\u0006 — \u0003ליתי תלת ברושייאתא דחיטי\u0004 \u0005[יביא שלוש חלות של חיטים]\u0006 \u0003ונישטרינהו בדובשא\u0004 \u0005[וישרה אותן בדבש]\u0006 \u0003וניכול\u0004 \u0005[ויאכל\u0006 אותן\u0005],\u0006 \u0003ונישתי אבתרייהו חמרא חייא\u0004 \u0005[וישתה אחריהן יין חי].\u0006","התרופה \u0003לצרחא דליבא\u0004 \u0005[לכאב הלב]\u0006 — \u0003ליתי תלת ביעי נינייא\u0004 \u0005[יביא\u0006 כשיעור \u0005שלוש ביצים של מנתה]\u0006 \u0003וביעתא דכמונא\u0004 \u0005[ו\u0006כשיעור \u0005ביצה של כמון]\u0006 \u0003וביעתא דשומשימי\u0004 \u0005[וכשיעור ביצה של שומשומים]\u0006 \u0003וליכול\u0004 \u0005[ויאכל].\u0006","התרופה \u0003לכאב מעי\u0004 \u0005[מעיים]\u0006 — \u0003ליתי תלת מאה פלפלי אריכתא\u0004 \u0005[יביא שלוש מאות פלפלים ארוכים],\u0006 \u0003וכל יומי נשתי מאה מינייהו בחמרא\u0004 \u0005[וכל יום ישתה מאה מהם ביין].\u0006 מסופר: \u0003רבין\u0004 ש\u0003מן\u0004 העיר \u0003נרש עבד\u0004 \u0005[עשה]\u0006 \u0003לה לברתיה\u0004 \u0005[לבתו]\u0006 של \u0003רב אשי\u0004 שהיתה חולה בכך \u0003מאה וחמשין מהני דידן\u0004 \u0005[מאה וחמישים מאלה,\u0006 מהפלפלים \u0005שלנו],\u0006 \u0003ואתסיא\u0004 \u0005[והתרפאה].\u0006","התרופה \u0003לכירצא\u0004 \u0005[לכרץ],\u0006 לתולעת שבמעיים — ישתה \u0003אנפקא דחמרא באטרפא דעראה\u0004 \u0005[רביעית יין בעלי דפנה].\u0006 התרופה \u0003לכירצא חיורא\u0004 \u0005[לתולעת לבנה]\u0006 — \u0003ליתי ביזרא גלגילא וניציירה בשיסתג\u0004 \u0005[יביא זרע של גרגיר ויקשרנו בפיסת אריג],\u0006 \u0003וניתייריה במיא ונשתיה\u0004 \u0005[וישרה אותו במים וישתה אותו],\u0006 \u0003ונזדהר מבינתא\u0004 \u0005[ויזהר מן הגרעין],\u0006 \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לא\u0004 יזהר די הצורך — קיים חשש שמא יצמח בהם ו\u0003מנקבא לה למעייניה\u0004 \u0005[ינקב את מעיו].\u0006","העצה \u0003למיסר\u0004 \u0005[\u0006כדי \u0005לעצור]\u0006 את השלשול — צמח \u0003סיסין רטיבא במיא\u0004 \u0005[לח במים].\u0006 והעצה \u0003למישרא\u0004 \u0005[להתיר,\u0006 לשלשל\u0005]\u0006 — \u0003יבישתא במיא\u0004 \u0005[\u0006סיסין \u0005יבשים במים],\u0006 \u0003וסימנך\u0004 שלא תחליף את אלה: \u0003איצא רטיבא דסכר נהרא\u0004 \u0005[עשב לח שסוכרים בו נהרות]\u0006 ומתוך כך יזכור שסיסין לחים הם העוצרים את השלשול.","התרופה \u0003לטחלא\u0004 \u0005[ל\u0006חולי \u0005הטחול]\u0006 — \u0003ליתי שב ביני דמיא\u0004 \u0005[יביא שבע תולעים של מים,\u0006 עלוקות\u0005]\u0006 \u0003ונייבשינהו בטולא\u0004 \u0005[וייבש אותן בצל],\u0006 \u0003וכל יומא נישתי תרתי ותלתא בחמרא\u0004 \u0005[וכל יום ישתה שתים ושלוש\u0006 מהן \u0005ביין].\u0006 \u0003ואי\u0004 \u0005[אם]\u0006 \u0003לא, ליתי טחלא דציפרתא\u0004 \u0005[יביא טחול של עז]\u0006 ש\u0003לא איפתח\u0004 \u0005[ילדה]\u0006 \u0003ונטחיא בתנורא\u0004 \u0005[וישים אותו בתנור],\u0006 \u0003ונוקי להדיה\u0004 \u0005[ויעמוד כנגדו]\u0006 \u0003ונימא: כי היכי דיביש האי טחלא\u0004 \u0005[כמו שמתייבש טחול זה]\u0006 \u0003נייבש טחליא דפלוני בר פלוניתא\u0004 \u0005[יתייבש הטחול של פלוני בן פלונית].\u0006","\u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא, ניטחייה ביני אורבי דביתא חדתא\u0004 \u0005[ישים\u0006 את הטחול \u0005בין הלבנים של בית חדש],\u0006 \u0003ונימא הכי\u0004 \u0005[ויאמר כך]\u0006 אותו דבר. \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא,\u0004 \u0003ליבקי שכבא דשכיב בשבתא\u0004 \u0005[יחפש מת שמת בשבת],\u0006 \u0003ונישקליה לידיה\u0004 \u0005[ויקח את ידו]\u0006 של המת \u0003ונותבה אטחליה\u0004 \u0005[וישים אותה על טחולו],\u0006 \u0003ונימא\u0004 \u0005[ויאמר]:\u0006 \u0003כי היכי דיביש הא ידא\u0004 \u0005[כמו שיבשה יד זו],\u0006 \u0003נייבש טחליא דפלוני בר פלוניתא\u0004 \u0005[יתייבש טחולו של פלוני בן פלונית].\u0006","\u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא, ניתי ביניתא וניטווייה בי נפחא\u0004 \u0005[יקח דג ויצלנו בבית הנפח],\u0006 \u0003וניכליה במיא דבי נפחא\u0004 \u0005[ויאכל אותו במים של בית הנפח]\u0006 שבהם מצנן את המתכת הלוהטת, \u0003ונישתי ממיא דבי נפחא\u0004 \u0005[וישתה מהמים של בית הנפח].\u0006 ובהקשר לכך מסופר: \u0003ההיא עיזא דהות שתיא מיא דבי נפחא\u0004 \u0005[עז אחת שהיתה שותה מים של בית הנפח],\u0006 \u0003אישתחיט\u0004 \u0005[נשחטה]\u0006 \u0003ולא אישתכח\u0004 \u0005[נמצא]\u0006 \u0003לה\u0004 בתוכה \u0003טחלא\u0004 \u0005[טחול].\u0006","\u0003ואי\u0004 \u0005[ואם]\u0006 אף שתיית מים אלו \u0003לא\u0004 הועילו לרפואתו, \u0003ליפתח חביתא דחמרא לשמיה\u0004 \u0005[שיפתחו חבית יין לשמו]\u0006 כלומר, שירבה בשתיית יין. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי: אי אית ליה חביתא דחמרא,\u0004 \u0005[אם יש לו חבית של יין]\u0006 \u0003לא אתי לקמיה דמר\u0004 \u0005[יבוא לפני אדוני]\u0006 לבקש רפואה, שהיין כבר מרפא אותו! \u0003אלא\u0004 מה רפואתו? \u0003מרגל\u0004 \u0005[יתרגל]\u0006 \u0003ב\u0004אכילת \u0003פת שחרית, דמעליא לכולי גופיה\u0004 \u0005[שמועילה לכל גופו].\u0006","התרופה \u0003לרושחתא\u0004 \u0005[ל\u0006מחלת \u0005התחתוניות,\u0006 לטחורים\u0005]\u0006 — \u0003ליתי אקיקא ואילווא\u0004 \u0005[יביא\u0006 צמח \u0005קקולי ואלווי],\u0006 \u0003ואספירכא ומרתכא\u0004 \u0005[וכספית ופסולת כסף],\u0006 \u0003וחומרתא דפילון ושיאפא דחמימתא\u0004 \u0005[וצרור של בשמים וצואת יונים],\u0006 \u0003ונינקט בשחקי דכיתנא בקייטא\u0004 \u0005[ויקח אותם בתוך שחקים,\u0006 בלאות, \u0005של פשתן בקיץ]\u0006 \u0003ודעמר גופנא בסיתוא\u0004 \u0005[ושל צמר גפן בחורף]\u0006 וישים במקום הכאב. \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא, לישתי שיכרא מרקא\u0004 \u0005[ישתה שיכר מזוג].\u0006","\u0003לשיגרונא\u0004 \u0005[לשיגרון]\u0006 — \u0003ליתי פתיא דמוניני\u0004 \u0005[יביא כלי\u0006 מלא \u0005ציר של דגים קטנים],\u0006 \u0003וניגנדריה שיתין זימני אהא מטחתיה ושיתין זימני אהא מטחתיה\u0004 \u0005[ויגלגל אותו שישים פעם על ירך זו ושישים פעם על ירך זו].\u0006","התרופה \u0003לצמירתא\u0004 \u0005[לאבן בדרכי השתן]\u0006 — \u0003ניתי תלת ניטופייתא מישחא דכופרא\u0004 \u0005[יביא שלוש טיפות שמן זפת],\u0006 כלומר, שמן היוצא מזיקוק עצים, \u0003ותלת ניטופייתא איצרא דכרתי\u0004 \u0005[ושלוש טיפות של סחיטת כרישים],\u0006 \u0003ותלת ניטופייתא דחמרא נקידא\u0004 \u0005[ושלוש טיפות של יין נקי],\u0006 \u0003ולישדי ליה\u0004 \u0005[וישים אותו]\u0006 \u0003לאיש באמה\u0004 (איבר המין) \u0003ולאשה באותו מקום\u0004 (במקום יציאת השתן) ויועיל.","\u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא, ליתי אונא דזיקא\u0004 \u0005[יביא אוזן של נאד],\u0006 \u0003ולתלי ליה\u0004 \u0005[ויתלה לו]\u0006 \u0003לאיש באמה\u0004 (באמתו) \u0003ולאשה\u0004 יתלה \u0003בדדין\u0004 (שדיים) שלה. \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא, ליתי חוטא דזהוריתא\u0004 \u0005[יביא חוט זהורית]\u0006 \u0003דשדתיה דומה בת דומה\u0004 \u0005[שטוותה אותו\u0006 אשה \u0005חשודה\u0006 בזנות \u0005בת חשודה],\u0006 \u0003וליתלי ליה\u0004 \u0005[ויתלה לו]\u0006 \u0003לאיש באמה ולאשה בדדין.\u0004","\u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא, ליתי\u0004 \u0005[יביא]\u0006 \u0003כינה\u0004 של \u0003זכר ו\u0004של \u0003נקבה,\u0004 \u0003וליתלי ליה\u0004 \u0005[ויתלה אותם]\u0006 \u0003לאיש באמה ולאשה באותו מקום, וכי\u0004 \u0005[וכאשר]\u0006 \u0003משתין,\u0004 מטיל מים — \u0003נשתין אסיסנא יבישתא\u0004 \u0005[ישתין על ענף יבש]\u0006 \u0003בצינורא דדשא\u0004 \u0005[בציר הדלת]\u0006 \u0003ונעיין בחומרתא דנפקא מיניה\u0004 \u0005[ויבדוק באבן היוצאת ממנו]\u0006 עם השתן, \u0003דמעליא לכולהו צימרא\u0004 \u0005[שמועילה לכל מחלות החום]\u0006 אם ישחקנה וישתמש בה.","התרופה \u0003לצימרא ברא\u0004 \u0005[לחום שבחוץ]\u0006 — \u0003ליתי תלתא גריבי סופלי\u0004 \u0005[יביא שלוש סאין של גרעיני תמרים]\u0006 \u0003ותלתא גריבי אטרף אדרא\u0004 \u0005[ושלוש סאים עלים של\u0006 עץ \u0005אדר],\u0006 \u0003ונישלוקינהו כל חד לחודיה\u0004 \u0005[ויבשל כל אחד לחוד]\u0006 \u0003וליתיב בינייהו\u0004 \u0005[וישב ביניהם],\u0006 \u0003ולתבינהו בתרתי משיכלי\u0004 \u0005[וישים אותם בשני ספלים]\u0006 \u0003וניתי פתורא וננח עילויה\u0004 \u0005[ויביא שולחן וישים עליו],\u0006 \u0003וניקום מעילוי האי ולותיב עילוי האי\u0004 \u0005[ויעמוד מעל זה וישים על זה],\u0006 \u0003ומעילוי האי ולותיב עילוי האי\u0004 \u0005[ומעל זה וישים על זה],\u0006 \u0003עד דניסק ביה הבלא\u0004 \u0005[שיעלה בו הבל]\u0006 שיתחמם מאוד, \u0003ולסחי מינייהו\u0004 \u0005[וירחץ מהם],\u0006 \u0003וכי שתי\u0004 \u0005[וכאשר\u0006 הוא \u0005שותה]\u0006 — \u0003ממיא דאדרא לישתי\u0004 \u0005[מהמים של האדר ישתה],\u0006 \u0003ממיא דסופלי\u0004 \u0005[מהימים של התמרים]\u0006 \u0003לא לישתי\u0004 \u0005[ישתה],\u0006 \u0003משום דמיעקרי\u0004 \u0005[ש\u0006הם \u0005גורמים לעקרות].\u0006","\u0003לצימרא גוונא\u0004 \u0005[לקדחת]\u0006 — \u0003ליתי\u0004 \u0005[יביא]\u0006 \u0003שבעה בוני דסילקא משב משארי\u0004 \u0005[חופנים של תרד משבע ערוגות],\u0006 \u0003ונישלוקינהו בעפרייהו\u0004 \u0005[ויבשל אותם בעפרם]\u0006 \u0003וניכול\u0004 \u0005[ויאכל],\u0006 \u0003ונישתי אטרף אדרא בשיכרא\u0004 \u0005[וישתה מעלי האדר בשיכר]\u0006 \u0003או\u0004"],["\u0003ענבי\u0004 גפן המודלות על גבי \u0003תאלא\u0004 \u0005[דקל]\u0006 שרויות \u0003במים.\u0004","התרופה \u0003לחזזיתא\u0004 \u0005[לחזזית]\u0006 העולה בעור — \u0003ליתי שב חיטי ארזנייתא\u0004 \u0005[יביא שבע חיטים גדולות]\u0006 \u0003וניקלינהו אמרא חדתא\u0004 \u0005[ויקלה אותן על מעדר חדש]\u0006 \u0003ונפיק משחא מינייהו ונישוף\u0004 \u0005[ויוציא שמן מהן, וישפשף\u0006 בעור\u0005].\u0006 מסופר: \u0003רב שימי בר אשי עבד ליה לההוא גוי\u0004 \u0005[עשה\u0006 תרופה \u0005זו לגוי אחד]\u0006 \u0003לדבר אחר\u0004 (לצרעת), \u0003ואיתסי\u0004 \u0005[והתרפא].\u0006","\u0003אמר שמואל: האי מאן דמחו ליה באלונכי דפרסאי\u0004 \u0005[מי שמכים אותו בחניתות של פרסים]\u0006 \u0003מיחייא\u0004 \u0005[לחיות]\u0006 \u0003לא חיי\u0004 \u0005[יחיה]\u0006 למשך זמן, שוודאי ימות מחמת המכות הללו, ואולם \u0003אדהכי והכי\u0004 \u0005[בין כה וכה]\u0006 \u0003ניספו ליה בשרא שמינא אגומרי וחמרא חייא\u0004 \u0005[יאכילו אותו בשר שמן\u0006 שנצלה \u0005על גחלים ויין חי],\u0006 \u0003אפשר דחיי פורתא ומפקיד אביתיה\u0004 \u0005[שיחיה מעט ויצווה לביתו]\u0006 מה יעשו אחר מותו.","בדומה לזה \u0003אמר רב אידי בר אבין: האי מאן דבלע זיבורא\u0004 \u0005[מי שבולע צירעה]\u0006 \u0003מיחייא\u0004 \u0005[לחיות]\u0006 \u0003לא חיי\u0004 \u0005[יחיה],\u0006 ואולם \u0003אדהכי והכי נשקיה רביעתא דחלא שמזג\u0004 \u0005[בין כה וכה ישקו אותו רביעית של חומץ חריף],\u0006 \u0003אפשר דחיי פורתא ומפקיד לביתיה\u0004 \u0005[שיחיה מעט ויצווה לביתו].\u0006","\u0003אמר ר' יהושע בן לוי:\u0004 מי ש\u0003אכל בשר שור בלפת, ולן ב\u0004אור \u0003לבנה בלילי ארבעה עשר או חמשה עשר\u0004 בחודש \u0003בתקופת תמוז\u0004 (בקיץ) — \u0003אחזתו\u0004 (תוקפת אותו) \u0003אחילו\u0004 \u0005[מין קדחת].\u0006","\u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003והממלא כריסו מכל דבר,\u0004 שאוכל יותר מדי — \u0003אחזתו אחילו. אמר רב פפא: אפילו\u0004 אם מילא כריסו \u0003מתמרי\u0004 \u0005[מתמרים].\u0006 ושואלים: \u0003פשיטא\u0004 \u0005[פשוט]!\u0006 הרי אמר ר' יהושע בן לוי \"כל דבר\"! ומשיבים: \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר],\u0006 \u0003הואיל ואמר מר\u0004 \u0005[החכם]\u0006 בשבחם של התמרים: \u0003תמרי\u0004 — \u0003משבען ומשחנן ומשלשלן ומאשרן ולא מפנקן\u0004 \u0005[תמרים\u0006 — \u0005משביעות ומחממות ומשלשלות ומחזקות ולא מפנקות]\u0006 את הגוף, \u0003אימא\u0004 \u0005[אמור]\u0006 כיון שהתמרים הן פירות כה משובחים אף שלא יזיקו כשאוכל מהן יותר מדי, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאף הן מזיקות אם ממלא כריסו מהן.","שואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003אחילו\u0004 זה שהזכרנו? \u0003אמר ר' אלעזר: אש של עצמות.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אש של עצמות\"? אמר אביי:\u0004 מה שנקרא בארמית \u0003אש גרמי.\u0004","\u0003מאי אסותיה\u0004 \u0005[מה תרופתו]?\u0006 \u0003אמר אביי, אמרה לי אם\u0004 (אומנתי): \u0003כולהו שקייני\u0004 \u0005[כל המשקאות]\u0006 ששותים לרפואה — שותים אותם \u0003תלתא ושבעא ותריסר\u0004 \u0005[\u0006\u0005שלושה ושבעה ושנים עשר\u0006 יום\u0005]\u0006 כל אחד לפי עניינו, \u0003והאי\u0004 \u0005[וזה]\u0006 לריפוי של אחילו, צריך לשתות \u0003עד דמתסי\u0004 \u0005[שיתרפא];\u0006","\u0003כולהו שקייני\u0004 \u0005[כל משקאות]\u0006 ששותים לתרופה — שותים אותם \u0003אליבא ריקנא\u0004 \u0005[על לב ריק],\u0006 כלומר, בלי לאכול קודם, \u0003והאי\u0004 \u0005[וזה]\u0006 — \u0003בתר דאכל ושתי\u0004 \u0005[אחרי שאוכל ושותה]\u0006 \u0003ועייל\u0004 \u0005[ונכנס]\u0006 \u0003לבית הכסא ונפיק ומשי ידיה\u0004 \u0005[ויוצא ורוחץ ידיו],\u0006 \u0003ומייתו ליה בונא דשתיתא דטלפחי\u0004 \u0005[ומביאים לו מלוא חופן ממאכל\u0006 \u0005של עדשים]\u0006 \u0003ובונא דחמרא עתיקא\u0004 \u0005[ומלוא חופן של יין ישן],\u0006 \u0003וניגבלינהו בהדי הדדי\u0004 \u0005[ויגבל,\u0006 ילוש \u0005אותם זה בזה]\u0006 \u0003וניכול\u0004 \u0005[ויאכל],\u0006 \u0003וניכרוך בסדיניה וניגניה\u0004 \u0005[ויתעטף בסדינו וישן],\u0006 \u0003וליכא דנוקמיה\u0004 \u0005[ושלא יקימו,\u0006 יעירו, \u0005אותו]\u0006 \u0003עד דקאי מנפשיה\u0004 \u0005[שיקום מעצמו],\u0006 \u0003וכי קאי לישקליה לסדיניה מיניה\u0004 \u0005[וכאשר קם יוריד את סדינו ממנו],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 — \u0003הדר עילויה\u0004 \u0005[יחזור עליו]\u0006 החולי.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אליהו לר' נתן: אכול שליש ושתה שליש והנח שליש,\u0004 שלא תאכל מלוא כריסך, שכך \u0003לכשתכעוס תעמוד על מילואך,\u0004 תוכל לעמוד בדבר, ואם לא תעשה כן, כשאתה כועס יזיק לך הדבר.","\u0003תני\u0004 \u0005[שנה]\u0006 \u0003ר' חייא: הרוצה שלא יבא לידי חולי מעיים, יהא רגיל בטיבול\u0004 לטבול את מאכלו ביין וחומץ, בין ב\u0003קיץ\u0004 בין ב\u0003חורף.\u0004 ועוד אמר: \u0003סעודתך שהנאתך\u0004 (שאתה נהנה) \u0003ממנה\u0004 — \u0003משוך ידך הימנה\u0004 כדי שלא תאכל יותר מדי, \u0003ואל תשהה עצמך בשעה שאתה צריך לנקביך.\u0004","\u0003אמר מר עוקבא: האי מאן דשתי טיליא חיורא\u0004 \u0005[מי ששותה יין רע לבן]\u0006 — \u0003אחזתו\u0004 (תוקפת אותו) \u0003ויתק\u0004 \u0005[חולשה].\u0006 \u0003אמר רב חסדא: שיתין מיני חמרא הוו\u0004 \u0005[שישים מיני יין הם],\u0006 \u0003מעליא דכולהו\u0004 \u0005[המעולה שבהם]\u0006 — \u0003סומקא ריחתנא\u0004 \u0005[\u0006יין \u0005אדום ריחני],\u0006 \u0003גריעא דכולהו\u0004 — \u0003טיליא חיורא\u0004 \u0005[הגרוע שבכולם\u0006 — יין \u0005לבן גרוע].\u0006","\u0003אמר רב יהודה: האי מאן דיתיב בצפרני\u0004 \u0005[מי שיושב בבוקרי]\u0006 \u0003ניסן גבי נורא, ושייף משחא\u0004 \u0005[ליד האש ומושח\u0006 עצמו \u0005בשמן]\u0006 \u0003ונפיק ויתיב בשמשא\u0004 \u0005[ויוצא ויושב בשמש]\u0006 — \u0003אחזתו\u0004 (תוקפת אותו) \u0003ויתק\u0004 \u0005[חולשה].\u0006","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הקיז דם ו\u0004אחרי כן \u0003שימש מטתו\u0004 — \u0003הוויין לו\u0004 \u0005[יהיו לו]\u0006 \u0003בנים ויתקין\u0004 \u0005[חלושים]\u0006 מתשמיש זה. \u0003הקיזו שניהם ושימשו\u0004 — \u0003הוויין להן\u0004 \u0005[יהיו להם]\u0006 \u0003בנים בעלי\u0004 מחלה ששמה \u0003ראתן.\u0004 \u0003אמר רב פפא: לא אמרן\u0004 \u0005[אמרנו]\u0006 דבר זה \u0003אלא\u0004 ש\u0003לא טעים מידי\u0004 \u0005[טעם דבר]\u0006 אחרי ההקזה, \u0003אבל\u0004 אם \u0003טעים מידי לית לן\u0004 \u0005[אם טעם דבר\u0006 \u0003אין לנו]\u0004 \u0003בה\u0004 חשש זה.","\u0003אמר רבה בר רב הונא: בא מן הדרך ושימש מטתו\u0004 מיד — \u0003הוויין לו\u0004 \u0005[יהיו לו]\u0006 \u0003בנים ויתקין\u0004 \u0005[ חלושים ].\u0006 \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הבא מבית הכסא, אל ישמש מטתו עד שישהה שיעור\u0004 הליכה של \u0003חצי מיל,\u0004 \u0003מפני ששד בית הכסא מלוה עמו, ואם שימש\u0004 — \u0003הוויין\u0004 \u0005[יהיו]\u0006 \u0003לו בנים נכפים\u0004 (חולים במחלת הנפילה).","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003המשמש מטתו מעומד\u0004 (כשהוא עומד) — \u0003אוחזתו עוית.\u0004 העושה זאת \u0003מיושב\u0004 — \u0003אוחזתו דלריא\u0004 (רעידה), אם \u0003היא,\u0004 האשה, \u0003מלמעלה והוא,\u0004 הבעל \u0003מלמטה\u0004 בשעת תשמיש — \u0003אוחזתו דלריא.\u0004","שואלים: \u0003מאי\u0004 \u0005[מהי]\u0006 \u0003דלריא?\u0004 ומביאים מה ש\u0003אמר ר' יהושע בן לוי: סם\u0004 הרפואה ל\u0003דלריא\u0004 הוא \u0003דרדרא.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מהי]\u0006 \u0003דרדרא? אמר אביי: מוריקא דחוחי\u0004 \u0005[כרכום של קוצים].\u0006 \u0003רב פפא אליס ובלע ליה\u0004 \u0005[היה לועס ובולע אותו].\u0006 \u0003רב פפי אליס ושדי ליה\u0004 \u0005[היה לועס ויורק,\u0006 פולט, \u0005אותו\u0006 לאחר לעיסה\u0005].\u0006","\u0003אמר אביי: מי שאינו בקי,\u0004 כלומר, אין לו כוח \u0003בדרך ארץ\u0004 (בתשמיש), \u0003ליתי\u0004 \u0005[שיביא]\u0006 \u0003שלשה קפיזי\u0004 (כלים בני שלוש רביעיות) של \u0003קורטמי דחוחי\u0004 \u0005[כרכום של חוחים],\u0006 \u0003ונידוקינהו ונישליקינהו בחמרא ונישתי\u0004 \u0005[ויכתשם ויבשלם ביין וישתה].\u0006 \u0003אמר ר' יוחנן: הן הן\u0004 התרופות אשר \u0003החזירוני לנערותי\u0004 לענין תשמיש.","\u0003שלשה דברים מכחישים\u0004 (מפחיתים) \u0003כחו של אדם, ואלו הן: פחד, דרך, ועון.\u0004 ומפרטים: \u0003פחד, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"לבי סחרחר עזבני כחי\"\u0004 (תהלים לח, יא). \u0003דרך, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ענה בדרך כחי\"\u0004 (תהלים קב, כד). \u0003עון, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כשל בעוני כחי\"\u0004 (תהלים לא, יא).","\u0003שלשה דברים מתיזין\u0004 (שוברים) \u0003גופו של אדם, ואלו הן: אכל מעומד, ושתה מעומד, ושימש מטתו מעומד.\u0004","\u0003חמשה\u0004 דברים שאדם עושה אותם \u0003קרובין\u0004 להביאו \u0003למיתה יותר מן החיים, ואלו הן: אכל ועמד\u0004 מייד, \u0003שתה ועמד, הקיז דם ועמד, ישן ועמד, שימש מטתו ועמד.\u0004","\u0003ששה\u0004 דברים \u0003העושה אותן\u0004 — \u0003מיד מת, ואלו הן: הבא בדרך ונתייגע, הקיז דם, ונכנס לבית המרחץ, ושתה ונשתכר, וישן על גבי קרקע, ושימש מטתו. אמר ר' יוחנן: והוא שעשאן כסידרן\u0004 בזה אחר זה, שאז וודאי שימות.","\u0003אמר אביי:\u0004 אם עושה אותם \u0003כסידרן\u0004 — \u0003מת, שלא כסידרן\u0004 — \u0003חליש\u0004 \u0005[נחלש].\u0006 ושואלים: \u0003איני\u0004 \u0005[כן הוא]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 אשה אחת שקראו לה \u0003מעורת\u0004 \u0003עבדה ליה\u0004 \u0005[עשתה לו]\u0006 \u0003לעבדה תלת מינייהו\u0004 \u0005[שלושה מהם]\u0006 \u0003ומית\u0004 \u0005[ומת\u0006 מהם\u0005]!\u0006 ומשיבים: העבד \u0003ההוא כחוש\u0004 וחלוש \u0003הוה\u0004 \u0005[היה]\u0006","ולכן מת, וסתם אדם רק אם עושה את כולם כסידרם ימות. \u0003שמונה\u0004 דברים — \u0003רובן,\u0004 כלומר, אם מרבה בהם הרי זה \u0003קשה\u0004 לגוף ולנפש, \u0003ומיעוטן יפה, ואלו הן: דרך\u0004 — ללכת בדרכים, \u0003ודרך ארץ\u0004 (תשמיש), \u0003עושר, ומלאכה\u0004 (עבודה), \u0003יין, ושינה, חמין, והקזת דם.\u0004","\u0003שמונה\u0004 דברים \u0003ממעטים את הזרע, ואלו הן: המלח, והרעב, והנתק\u0004 (מחלת עור), \u0003בכייה, ושינה על גבי קרקע, וגדגדניות, וכשות\u0004 שאוכל \u0003שלא בזמנה, והקזת דם\u0004 הנעשית \u0003למטה\u0004 בגוף האדם — מזיקה \u0003כפלים\u0004 מן הדברים האחרים.","\u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003כשם שקשה\u0004 הקזת דם הנעשית \u0003למטה כפלים,\u0004 \u0003כך יפה\u0004 ומועילה אם עושה אותה \u0003למעלה\u0004 — \u0003כפלים. אמר רב פפא:\u0004"],["מה שאמרו \u0003למטה\u0004 כוונתו — שמקיז את הדם במקום בגופו שהוא \u0003למטה מן הביצים\u0004 (האשכים), \u0003למעלה\u0004 כוונתו — \u0003למעלה מן הביצים.\u0004","שנינו: \u0003וכשות שלא בזמנה\u0004 מזיקה. ומביאים: \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003כשם שקשה\u0004 לגוף אכילת כשות \u0003שלא בזמנה, כך יפה\u0004 כשאוכלה \u0003בזמנה. אמר רב פפא: זמנה\u0004 הוא — \u0003תמוז, שלא בזמנה\u0004 — \u0003טבת,\u0004 ואילו \u0003יומי\u0004 \u0005[ימי]\u0006 \u0003ניסן ויומי\u0004 \u0005[וימי]\u0006 \u0003תשרי\u0004 (באביב ובסתיו) — \u0003לא מעלו\u0004 \u0005[מועילים]\u0006 \u0003ולא קשו\u0004 \u0005[קשים].\u0006","מעתה חוזרים לפירוש גופי הלכה שבמשנה: \u0003אמר \"כתבו גט לאשתי\" ואחזו קורדייקוס, וחזר ואמר \"אל תכתבו\"\u0004 — \u0003אין דבריו האחרונים כלום. אמר ר' שמעון בן לקיש:\u0004 במקרה שכזה \u0003כותבין ונותנין גט לאלתר\u0004 (מייד), אף על פי שעדיין לא נצטללה דעתו ואין ממתינים לו. \u0003ור' יוחנן אמר: אין כותבין אלא לכשישתפה,\u0004 כשיעמוד על דעתו.","ומסבירים את שיטותיהם: \u0003מאי טעמא\u0004 \u0005[מהו הטעם]\u0006 של \u0003ריש לקיש?\u0004 — \u0003דקתני\u0004 \u0005[ששנה]\u0006 במשנה: \u0003אין בדבריו האחרונים כלום\u0004 ומשמע שדבריו הראשונים קיימים ונוהגים לפי הוראתו. \u0003ו\u0004לעומת זאת \u0003ר' יוחנן אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך\u0004 ולפרש כך: \u0003אין בדבריו האחרונים כלום,\u0004 הכוונה היא \u0003דלכי מתציל\u0004 \u0005[שכאשר מצטללת\u0006 דעתו\u0005]\u0006 \u0003לא צריך למיהדר אימלוכי ביה\u0004 \u0005[לחזור ולהימלך בו],\u0006 אלא סומכים על דבריו הראשונים, \u0003ו\u0004אולם \u0003לעולם אין כותבין אלא לכשישתפה.\u0004","ומסבירים: \u0003במאי קמיפלגי\u0004 \u0005[במה,\u0006 באיזה עקרון, \u0005הם חלוקים]?\u0006 — \u0003ריש לקיש מדמי ליה\u0004 \u0005[מדמה אותו],\u0006 את זה שאחזו קורדייקוס \u0003לישן,\u0004 שהרי אם אמר לכתוב גט, והלך לישון — בוודאי שכותבים את הגט ואין צריך להעירו. \u0003ור' יוחנן מדמי ליה\u0004 \u0005[מדמה אותו]\u0006 \u0003לשוטה,\u0004 שמאחר שאחזו קורדייקוס אינו ברדעת, ומי שאינו ברדעת אינו יכול לתת גט.","ושואלים: \u0003ור' יוחנן נמי לידמיה\u0004 \u0005[גם כן, שידמה אותו]\u0006 \u0003לישן!\u0004 ומשיבים: \u0003ישן לא מחוסר מעשה,\u0004 שאין צריך לעשות מעשה כדי להעירו, אלא מעצמו הוא ניעור, ואילו \u0003האי\u0004 \u0005[זה],\u0006 מי שאחזו קורדייקוס, הריהו \u0003מחוסר מעשה\u0004 של רפואה.","ושואלים: \u0003וריש לקיש נמי נידמייה\u0004 \u0005[גם כן, שידמה אותו]\u0006 \u0003לשוטה!\u0004 ומשיבים: יש להבדיל, כי \u0003שוטה לא סמיה בידן\u0004 \u0005[אין סם\u0006 רפואתו \u0005בידינו],\u0006 שאין בידינו לתקן את פגמו, ולכן בשעת שטותו אין בידו רשות לעשות דבר, ואולם \u0003האי סמיה בידן\u0004 \u0005[זה,\u0006 מי שאחזו קורדייקוס, \u0005סמו,\u0006 רפואתו, \u0005בידינו],\u0006 כפי שאמרנו: \u0003בישרא סומקא אגומרי וחמרא מרקא\u0004 \u0005[בשר אדום\u0006 שניצלה \u0005על גחלים ויין מזוג].\u0006","ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר ר' יוחנן הכי\u0004 \u0005[כך]\u0006 שממתינים לו עד שישתפה? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב יהודה אמר שמואל:\u0004 מי שחבל בו אדם ו\u0003שחט בו שנים\u0004 (שני הסימנים, קנה וושט בצווארו) \u0003או רוב שנים,\u0004 והרי אותו אדם עומד למות, ורמז האיש \u0003ואמר \"כתבו גט לאשתי\"\u0004 — \u0003הרי אלו יכתבו ויתנו,\u0004","\u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]\u0006 כעין זה: \u0003ראוהו\u0004 את האיש \u0003מגויד\u0004 (איבריו חתוכים) \u0003או צלוב על הצליבה, ורמז ואמר \"כתבו גט לאשתי\"\u0004 — \u0003הרי אלו יכתבו ויתנו!\u0004 משמע שאפילו אדם שסופו להגיע למצב של מוות, ואין לו תרופה אפשר לכתוב עבורו גט!","ודוחים: \u0003הכי השתא\u0004 \u0005[כך אתה משווה]?!\u0006 \u0003התם\u0004 \u0005[שם]\u0006 במקרים של השחוט והצלוב \u0003דעתא צילותא\u0004 \u0005[דעת צלולה]\u0006 \u0003היא\u0004 אצלו, \u0003וכחישותא הוא דאתחילה ביה\u0004 \u0005[וחולשה היא שהתחילה בו]\u0006 ולכן איננו יכול לדבר, אבל הוא כברדעת לכל ענין, ואולם \u0003הכא דעתא שגישתא\u0004 \u0005[כאן דעה משובשת]\u0006 \u0003היא,\u0004 שהרי הוא שוטה בשעה זו, ואי אפשר שיעשה דבר מדעת.","ושואלים מצד אחר: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר שמואל הכי\u0004 \u0005[כך]\u0006 שהשחוט דינו כחי, ויכול לתת גט? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב יהודה אמר שמואל: שחט בו שנים או רוב שנים\u0004 \u0003וברח\u0004 ולא ראו העדים מה היה סופו — \u0003מעידין עליו\u0004 שמת. \u0003ואי סלקא דעתך\u0004 \u0005[ואם יעלה על דעתך\u0006 לומר\u0005]\u0006 כי \u0003חי הוא, אמאי\u0004 \u0005[מדוע]\u0006 \u0003מעידין עליו\u0004 שמת?","\u0003אמרי\u0004 \u0005[אומרים]\u0006 כתשובה לכך: \u0003חי הוא\u0004 כעת ומשום כך יכול לתת גט — \u0003ו\u0004אולם \u0003סופו\u0004 בוודאי \u0003למות,\u0004 ולכן אפשר להעיד עליו בוודאות לאחר זמן שמת.","ושואלים: \u0003אלא מעתה,\u0004 כיון שנחשב שוודאי הוא מת, \u0003יהא\u0004 זה ששחט אותו \u0003גולה על ידו\u0004 אם עשה זאת בשגגה! \u0003אלמה תניא\u0004 \u0005[מפני מה שנויה\u0006 ברייתא\u0005]:\u0006 \u0003שחט בו\u0004 בשגגה \u0003שנים או רוב שנים\u0004 כגון שהפיל עליו סכין — \u0003הרי זה אינו גולה?\u0004","ומשיבים: \u0003הא איתמר עלה\u0004 \u0005[הרי נאמר על כך],\u0006 \u0003אמר ר' הושעיא: חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003שמא הרוח בלבלתו\u0004 ונגרמה מיתתו לא מחמת שחיטה בלבד, אלא שהיה גורם נוסף שאינו תלוי ברוצח. \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 שמא \u0003הוא,\u0004 הנשחט עצמו, \u0003קירב את מיתתו\u0004 בכך שפירכס ופירפר.","\u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם],\u0006 בין הסבר זה להסבר זה? \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 \u0003דשחטיה בביתא דשישא\u0004 \u0005[ששחט אותו בבית של שיש]\u0006 \u0003ופירכס\u0004 ששם אין רוח המזיקה לו, אבל לדעה האחרת יש לומר שהוא עצמו פירכס וקירב את מיתתו. \u0003אי נמי\u0004 \u0005[או גם],\u0006 \u0003דשחטיה בברא\u0004 \u0005[ששחט אותו בחוץ]\u0006 \u0003ולא פירכס,\u0004 שיש לחשוש לרוח לדעה אחת, אף שהוא לא קירב בעצמו את מיתתו.","שנינו במשנה: \u0003נשתתק, ואמרו לו נכתוב גט לאשתך\u0004 והרכין בראשו לאות הסכמה — בודקים אותו שלוש פעמים, אם אמר על דבר שהתשובה לו צריכה להיות \"הן\" — \"הן\" ועל דבר שהתשובה לו צריכה להיות \"לאו\" — \"לאו\", ונמצא איפוא מתוך כך שהוא בר דעת — כותבים גט. ושואלים: \u0003וליחוש\u0004 \u0005[ונחשוש]\u0006 \u0003דלמא שיחיא ד\"לאו\" \"לאו\" נקטיה\u0004 \u0005[שמא תנועה של \"לא\" \"לא\" תפסה אותו]\u0006 והוא מניד כל הזמן בראשו כאומר \"לא\" אף שאינו מתכוון לכך, \u0003אי נמי שיחיא ד\"הן\" \"הן\" נקטיה\u0004 \u0005[או גם כן\u0006 שמא \u0005תנועה של \"כן\" \"כן\" תפסה אותו]?\u0006","\u0003אמר רב יוסף בר מניומי אמר רב נחמן: דאמרינן ליה\u0004 \u0005[שאומרים אנו לו]\u0006 דברים \u0003בסירוגין,\u0004 כלומר, שואלים אותו פעם דברים שצריך לענות עליהם \"הן\" ופעם אחרת דברים שצריך לענות עליהם \"לא\".","ושואלים: \u0003וליחוש דלמא שיחיא\u0004 \u0005[ונחשוש שמא תנועה]\u0006 של \u0003סירוגין\u0004 \u0003נקטיה\u0004 \u0005[תפסה אותו]\u0006 שפעם מנענע בראשו כאומר \"כן\" ופעם כאומר \"לא\"! ומשיבים: \u0003דאמרינן ליה\u0004 \u0005[שאומרים אנו לו],\u0006 שואלים אותו דברים שצריך להשיב עליהם \u0003חד \"לאו\" ותרין \"הן\"\u0004 \u0005[\u0006פעם \u0005אחת \"לא\", ושתי\u0006 פעמים \u0005\"כן\"],\u0006 \u0003ותרין \"לאו\" וחד \"הן\"\u0004 \u0005[ופעמיים \"לא\" ו\u0006פעם \u0005אחת \"כן\"].\u0006 ובאופן שכזה, אם עונה כראוי על הכל אין לחשוש שמא היתה זו סתם תנועת הראש.","\u0003דבי\u0004 \u0005[בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל תנא\u0004 \u0005[שנה]:\u0006 \u0003אומרים לו\u0004 בשאלה אם רוצה \u0003דברים של ימות החמה\u0004 \u0003בימות הגשמים, ושל ימות הגשמים בימות החמה\u0004 כדי לבדוק האם דעתו צלולה.","ושואלים: \u0003מאי ניהו\u0004 \u0005[מה הם]\u0006 דברים אלה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 ששואלים אותו אם הוא רוצה \u0003גלופקרי\u0004 \u0005[מעיל חם]\u0006 בימות החמה \u0003ו\u0004כן \u0003סדיני\u0004 \u0005[סדין דק]\u0006 בימות הגשמים, והוא עונה שרוצה — אין בזה הוכחה שאין הוא בר דעת, שיש לומר: \u0003ליחוש דלמא קורא אחדיה\u0004 \u0005[נחשוש שמא קור אחז אותו]\u0006 אף שהוא ימות החמה, \u0003אי נמי חמה אחדיה\u0004 \u0005[גם כן חום תפס אותו]\u0006 בימות הגשמים, ומה שמשיב כך אינו סימן שאינו מבין, אלא שמא הוא מרגיש קור וחום באותה שעה, אבל דעתו צלולה!"],["\u0003אלא\u0004 הכוונה היא ששואלים אותו \u0003בפירי\u0004 \u0005[בפירות]\u0006 שאינם מצויים באותה עונה של השנה.","\u0003אמר רב כהנא אמר רב: חרש שיכול לדבר מתוך הכתב,\u0004 שיודע לבטא את רצונו בכתיבה — \u0003כותבין ונותנין גט לאשתו\u0004 על פי כתיבתו. \u0003אמר רב יוסף: מאי קא משמע לן\u0004 \u0005[מה השמיע לנו\u0006 בכך\u0005]?\u0006 הלא \u0003תנינא\u0004 \u0005[שנינו]:\u0006 מי שהיה פיקח ו\u0003נשתתק\u0004 ואינו יכול לדבר, \u0003ואמרו לו \"נכתוב גט לאשתך\" והרכין בראשו, בודקין אותו שלשה פעמים, אם אמר על \"לאו\" \"לאו\" ועל \"הן\" \"הן\"\u0004 — \u0003הרי אלו יכתבו ויתנו.\u0004 משמע שלא הדיבור הוא העיקר אלא אם יכול להודיע רצונו בכל דרך אחרת — די בכך!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' זירא:\u0004 לגבי \u0003אלם קאמרת\u0004 \u0005[אתה אומר]?\u0006 \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003אלם\u0004 שברור שיש לו דעת. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מדבר ואינו שומע\u0004 — \u0003זהו חרש, שומע ואינו מדבר\u0004 — \u0003זהו אלם, וזה וזה הרי הן כפקחין לכל דבריהם.\u0004 ו\"חרש\" האמור בדרך כלל בדברי חכמים ובדברי רב כהנא כאן, הוא מי שאינו שומע ואינו מדבר.","ושואלים: \u0003וממאי\u0004 \u0005[וממה,\u0006 מהיכן יודעים\u0005]\u0006 ש\u0003מדבר ואינו שומע זהו חרש, שומע ואינו מדבר זהו אלם?\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ואני כחרש לא אשמע וכאלם לא יפתח פיו\"\u0004 (תהלים לח, יד). \u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור],\u0006 \u0003כדאמרי אינשי\u0004 \u0005[כפי שאומרים אנשים]\u0006 שאילם הוא כעין ראשי התיבות \u0003אישתקיל מילוליה\u0004 \u0005[נלקח דיבורו].\u0006","\u0003אמר ר' זירא: אי קשיא\u0004 \u0005[אם קשה]\u0006 \u0003לי\u0004 בדברי רב כהנא \u0003הא קשיא\u0004 \u0005[זה קשה]\u0006 \u0003לי,\u0004 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 נאמר לגבי עונשו של מי שנתבע להעיד ולא העיד: \u0003\"אם לוא יגיד\u0004 ונשא עוונו\u0003\"\u0004 (ויקרא ה, א) — ולמדו מכאן: \u0003פרט לאלם שאינו יכול להגיד\u0004 (להעיד), שאינו מביא את הקרבן האמור בענין. ויש לשאול: \u0003אמאי\u0004 \u0005[מדוע]\u0006 אינו יכול להעיד? \u0003הא\u0004 \u0005[הרי]\u0006 \u0003יכול להגיד מתוך הכתב!\u0004 משמע מכאן שהגדה בכתב אינה נחשבת כהגדה!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 \u0003עדות קאמרת\u0004 \u0005[אומר אתה]?\u0006 \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003עדות, דרחמנא אמר\u0004 \u0005[שהתורה אמרה]:\u0006 \u0003\"מפיהם\"\u0004 (ראה דברים יז, ו) וההדגשה היא — דווקא מפי העדים \u0003ולא מפי כתבם.\u0004 ואם כן יש בענין זה גזירת הכתוב, שאינה נוגעת לשאלה האם בכלל סומכים על כתיבה כדיבור.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו בברייתא: \u0003כשם שבודקין אותו,\u0004 את מי שנשתתק, \u0003לגיטין, כך בודקין אותו למשאות ולמתנות\u0004 (קניה ומכירה, ענייני מסחר), \u0003ולעדיות,\u0004 \u0003ולירושות; קתני מיהת\u0004 \u0005[שנה על כל פנים\u0006 שם\u0005]\u0006 \u0003\"עדיות\"!\u0004 משמע שהוא יכול להעיד אף שאינו מדבר!","\u0003אמר רב יוסף בר מניומי אמר רב ששת:\u0004 אין הכוונה לסתם עדות אלא \u0003בעדות אשה,\u0004 שמעיד שמת בעלה, \u0003דאקילו\u0004 \u0005[שהקילו]\u0006 \u0003בה רבנן\u0004 \u0005[חכמים]\u0006 באופנים שונים, כדי שתוכל להינשא.","ומקשים: \u0003והא קתני\u0004 \u0005[והרי שנה]\u0006 \u0003\"ירושות\"!\u0004 ואנו מבינים שמדובר שמעיד אותו אדם מי הוא היורש בנחלה של אדם אחר, ולענין זה יש צורך בעדות גמורה! \u0003אמר ר' אבהו:\u0004 שם מדובר לגבי \u0003ירושת בנו הבכור,\u0004 כלומר, שאינו מעיד על נכסי אחרים, אלא שאומר שאחד מן הבנים שלו הוא בנו הבכור, ואין זו עדות אלא כחלוקת נכסים השייכים לו עצמו.","ומוסיפים להקשות: \u0003קתני מיהת\u0004 \u0005[שנה על כל פנים]\u0006 בברייתא \u0003\"למשאות ולמתנות\", מאי לאו\u0004 \u0005[האם לא]\u0006 שהוא יכול להעיד על משאות ומתנות \u0003לעלמא\u0004 \u0005[לעולם,\u0006 לאחרים\u0005]?\u0006 ומשיבים: \u0003לא, לדידיה\u0004 \u0005[לעצמו]\u0006 לומר שכאשר הוא נושא ונותן בודקים אותו אם יש בו דעת, ולא לענין עדות.","\u0003מיתיבי\u0004 \u0005[מקשים],\u0006 ממה ששנינו: \u0003חרש, לא הלכו בו אחר רמיזותיו ואחר קפיצותיו ואחר כתב ידו אלא\u0004 בקניה ומכירה \u0003במטלטלין, אבל לא לגיטין.\u0004 וקשה על דברי רב כהנא המתיר הוראה של חרש בכתב לגבי גיטין!","ומשיבים: \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא,\u0004 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר רבן שמעון בן גמליאל: במה דברים אמורים\u0004 שאין סומכים על כתבו של חרש בגיטין — \u0003בחרש מעיקרו, אבל\u0004 אם היה \u0003פיקח ונתחרש\u0004 אחר כך — \u0003הוא כותב\u0004 את הגט \u0003והן חותמין.\u0004 וכדעתו סבור רב כהנא.","ושואלים: \u0003וחרש מעיקרו לא,\u0004 אינו יכול לתת גט? הלא \u0003כשם שכונסה ברמיזה,\u0004 כלומר, כשם שקידש ונשא את האשה בלא דיבור הפה, אלא ברמיזה בלבד \u0003כך מוציאה ברמיזה!\u0004","ומשיבים: \u0003אי\u0004 \u0005[אם]\u0006 מדובר \u0003באשתו,\u0004 \u0003הכי נמי\u0004 \u0005[כך הוא גם כן]\u0006 שיכול לגרש אותה על פי רמיזה, שהרי גם נישואיו לא היו נישואין גמורים, אבל \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003ב\u0004קידש את \u0003יבמתו\u0004 ורוצה לגרשה.","ושואלים: \u0003יבמתו ממאן\u0004 \u0005[ממי]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003נפלה ליה\u0004 \u0005[לו]\u0006 \u0003מאחיו\u0004 שהיה גם הוא \u0003חרש,\u0004 הלא \u0003כשם שכניסתה\u0004 (נישואיה) היו \u0003ברמיזה כך יציאתה ברמיזה! אלא\u0004 צריך לומר ש\u0003נפלה ליה\u0004 \u0005[לו]\u0006 \u0003מאחיו פיקח\u0004 שנישואיה היו נישואים גמורים, וחובת הייבום שלו היא מן התורה, ואילו מעשיו של החרש כשרים רק מדברי חכמים.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003לעולם\u0004 תפרש ש\u0003נפלה ליה\u0004 \u0005[לו]\u0006 \u0003מאחיו חרש, וגזירה\u0004 גזרו חכמים ביבמה מ\u0003אחיו חרש, אטו\u0004 \u0005[משום]\u0006 יבמה שנפלה לו מ\u0003אחיו פיקח.\u0004","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה אומר, שגזרו חכמים בחרש משום פיקח, \u0003אשתו נמי\u0004 \u0005[גם כן]\u0006 נגזור שלא יוכל החרש לגרשה בגט! ומשיבים: \u0003יבמתו ביבמתו מיחלפא\u0004 \u0005[מתחלפת],\u0006 שאפשר שלא ידעו אם היא יבמתו מאח פיקח או מאח חרש, אבל \u0003אשתו ביבמתו לא מיחלפא\u0004 \u0005[מתחלפת],\u0006 ואין מקום לגזור בדבר.","ושואלים: \u0003ומי גזרינן\u0004 \u0005[והאם גוזרים אנו]\u0006 לגבי אחיו ה\u0003חרש אטו\u0004 \u0005[משום]\u0006 אחיו ה\u0003פיקח?\u0004"],["\u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003שני אחין חרשין\u0004 שנישואיהם תקפים רק מדברי סופרים, שהיו \u0003נשואין שתי אחיות פיקחות, או\u0004 שהיו נשואים \u0003שתי אחיות חרשות, או\u0004 שהיו נשואים \u0003שתי אחיות אחת פיקחת ואחת חרשת, וכן\u0004 אם היו \u0003שתי אחיות חרשות\u0004 שנישואיהן תקפים רק מדברי סופרים \u0003נשואות לשני אחין פיקחין, או לשני אחין חרשין, או לשני אחין\u0004 שהיה \u0003אחד פיקח ואחד חרש\u0004 — \u0003הרי אלו פטורות מן החליצה ומן היבום,\u0004 שהיבמה פטורה לגמרי מדין יבום משום שהיא אחות אשתו של היבם, ואסורה עליו כערוה.","\u0003ואם היו\u0004 שתי הנשים \u0003נכריות\u0004 (זרות), כלומר, שאינן קרובות זו לזו ואין איסור ערוה בנישואי שתיהן — \u0003יכנסו,\u0004 יכול האח הנשאר לכנוס אותן, \u0003ואם רצו להוציאן\u0004 (לגרשן) אחר היבום על ידי גט — \u0003יוציאו.\u0004 וכיון שנאמרו הדברים כהלכה כללית, משמע שאף האח החרש יכול להוציא את יבמתו (אשת אחיו החרש) בגט, ואין אנו גוזרים באח חרש משום אח פיקח!","\u0003אלא, מחוורתא כדשנין מעיקרא\u0004 \u0005[מחוור,\u0006 ברור, \u0005כפי שתירצנו מתחילה]\u0006 שמדובר ביבמה שנפלה לפני חרש מעיקרו מאחיו הפיקח. ומדוע להעמיד את דברי רב כהנא בשם רב כדעת רבן שמעון בן גמליאל דווקא?","ש\u0003אמר ר' יוחנן: חלוקין עליו חביריו על רבן שמעון בן גמליאל,\u0004 וסבורים שאין סומכים כלל על כתבו של החרש.","\u0003אמר אביי, אף אנן נמי תנינא\u0004 \u0005[אנו גם כן שנינו]\u0006 שאין תקנה על ידי כתיבה: אשה ש\u0003נישטת\u0004 (השתטתה, השתגעה) אחרי שהתחתנה — \u0003לא יוציא,\u0004 שאסרו חכמים לגרש אותה. אם \u0003נתחרש הוא\u0004 הבעל \u0003או נשתטה\u0004 הוא — \u0003לא יוציא עולמית.\u0004 ודנים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 מה טעם ההדגשה \u0003\"עולמית\"? לאו\u0004 \u0005[האם לא]\u0006 מדובר \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003יכול לדבר מתוך הכתב,\u0004 ובכל זאת אינו יכול לגרש?","\u0003אמר רב פפא: אי לאו דאשמועינן\u0004 \u0005[אם לא שהשמיע לנו]\u0006 \u0003ר' יוחנן\u0004 שיש כאן מחלוקת, \u0003הוה אמינא\u0004 \u0005[היינו אומרים]\u0006 ש\u0003רבן שמעון בן גמליאל\u0004 רק \u0003לפרושי טעמא\u0004 \u0005[לפרש\u0006 את \u0005הטעם]\u0006 של ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 \u0003הוא דאתא\u0004 \u0005[שבא]\u0006 ואינו חולק עליו וסומכים על הכתיבה של פיקח שנתחרש, \u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"עולמית\"?\u0004 אין הכוונה שאף מתוך הכתב לא יוכל לצוות לכתוב גט, אלא \u0003אף על גב דחזינא ליה דחריף\u0004 \u0005[אף על פי שאנו רואים בו ש\u0006הוא \u0005חריף\u0006 ומבין\u0005]\u0006 בכל זאת אין סומכים על הבנתו ורמזיו, אבל בכתב — כשר.","\u0003אי נמי\u0004 \u0005[או גם כן]\u0006 הדגישה הברייתא \"עולמית\" דווקא בבעל שנתחרש או נשתטה, \u0003לכ\u0004 פי שאמר \u0003ר' יצחק,\u0004 ש\u0003אמר ר' יצחק: דבר תורה שוטה מתגרשת, מידי דהוה\u0004 \u0005[כפי שהוא\u0006 הדין\u0005]\u0006 \u0003אפיקחת\u0004 \u0005[על,\u0006 לגבי \u0005פיקחת]\u0006 שמתגרשת \u0003בעל כרחה,\u0004 שכשם שאין צורך בדעתה כשהיא פיקחת, כך אף כשאין בה דעת כלל — יכול בעלה לגרשה.","\u0003ומה טעם אמרו\u0004 חכמים \u0003אינה מתגרשת\u0004 — כדי \u0003שלא ינהגו בה מנהג הפקר,\u0004 שאם אינה נשואה ואין בעלה שומרה והיא עצמה אינה בת דעת לשמור עצמה, תיעשה כהפקר לכל חוטא. אולם בעל חרש או שוטה אף מדין תורה אינו יכול לגרש, ולכן הדגישה הברייתא \"עולמית\".","\u0003אמרו לו\u0004 לבעל \u0003\"נכתוב גט לאשתך\"? ואמר להן \"כתובו\",\u0004 ו\u0003אמרו\u0004 אותם אנשים \u0003לסופר וכתב, ולעדים וחתמו, אף על פי שכתבוהו וחתמוהו ונתנוהו לו, וחזר\u0004 הוא עצמו \u0003ונתנו לה\u0004 — \u0003הרי הגט בטל, עד שיאמר\u0004 הוא עצמו \u0003לסופר \"כתוב\" ולעדים \"חתומו\".\u0004","מן המשנה מדייקים: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 ש\u0003לא אמר\u0004 להם \u0003\"תנו\u0004 גט לאשתי \u0003\",\u0004 ומשום כך הגט פסול, שהרי אמר להם במפורש לכתוב, \u0003הא\u0004 \u0005[הרי]\u0006 אם אמר \u0003\"תנו\"\u0004 ואמרו לסופר לכתוב ולעדים לחתום — \u0003נותנין,\u0004 \u0003מני\u0004 \u0005[\u0006שיטת \u0005מי היא]?\u0006 שיטת \u0003ר' מאיר היא,\u0004 ש\u0003אמר: מילי מימסרן\u0004 \u0005[דברים נמסרים]\u0006 \u0003לשליח,\u0004 כלומר, אדם יכול למנות שליח לא רק לעשות מעשה עבורו, אלא גם לתת לשליח הוראה (\"דברים\") והשליח יכול לומר לאחרים לעשות.","\u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005הסוף\u0006 של המשנה\u0005]:\u0006 \u0003\"עד שיאמר לסופר כתוב ולעדים חתומו\",\u0004 אם כן \u0003אתאן\u0004 \u0005[הגענו]\u0006 \u0003ל\u0004שיטת \u0003ר' יוסי,\u0004 ש\u0003אמר: מילי\u0004 \u0005[דברים]\u0006 \u0003לא מימסרן\u0004 \u0005[נמסרים]\u0006 \u0003לשליח.\u0004","ותמוה: וכי \u0003רישא\u0004 \u0005[ראש,\u0006 תחילת\u0005]\u0006 המשנה כשיטת \u0003ר' מאיר וסיפא\u0004 \u0005[והסוף]\u0006 כשיטת \u0003ר' יוסי?\u0004 ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003רישא\u0004 \u0005[הראש]\u0006 כשיטת \u0003ר' מאיר וסיפא\u0004 \u0005[והסוף]\u0006 כשיטת \u0003ר' יוסי\u0004 אף שדבר כזה אינו רגיל, מכל מקום אפשר שיהיו במשנה שתי שיטות.","\u0003אביי אמר:\u0004 כל המשנה \u0003כולה\u0004 כשיטת \u0003ר' מאיר היא, והכא במאי עסקינן\u0004 \u0005[וכאן במה אנו עוסקים]\u0006 — ש\u0003לא אמר \"תנו\"\u0004 שאם היה אומר \"תנו\" היה מועיל. ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003\"עד שיאמר תנו\" מיבעי ליה\u0004 \u0005[היה צריך לו\u0006 לומר\u0005],\u0006 שהרי די בכך כדי להכשיר את הגט, ולא כפי שיש במשנה \"עד שיאמר לסופר\"!","\u0003אלא\u0004 יש לומר: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — ש\u0003לא אמר לבי תלתא\u0004 \u0005[לשלושה]\u0006 אלא אמר לשנים, ושנים דינם כעדים ולא כבית דין, ואינם יכולים להורות לאחרים לכתוב גט, אף אם אמר להם \"תנו\", אלא הם עצמם צריכים לעשות זאת. ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 גם אז לשון המשנה אינה מדוייקת, שהרי \u0003\"עד שיאמר לשלשה\" מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]!\u0006","\u0003אלא\u0004 יש לומר באופן אחר: כל המשנה \u0003כולה\u0004 כשיטת \u0003ר' יוסי היא, והכא במאי עסקינן\u0004 \u0005[וכאן במה אנו עוסקים]\u0006 — ש\u0003לא אמר\u0004 במפורש לשליחיו \u0003\"אמרו\u0004 לסופר ויכתוב","\u0003\".\u0004 ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 הלשון \u0003\"עד שיאמר\u0004 לסופר \u0003\"\u0004אינה נכונה, אלא: עד שיאמר \u0003\"אמרו\" מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]!\u0006","\u0003ועוד,\u0004 יש להקשות לגופו של התירוץ: \u0003מי\u0004 \u0005[האם]\u0006 \u0003מודה ר' יוסי באומר \"אמרו\"\u0004 שהגט כשר? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 אם היתה עדות לגבי \u0003כתב סופר\u0004 המעיד שהוא כתבו, \u0003ו\u0004חתימת \u0003עד\u0004 אחד — הרי זה גט \u0003כשר, ואמר ר' ירמיה:\u0004 לא כתב סופר אלא דווקא \u0003חתם סופר שנינו,\u0004 שחתומים שנים בגט, הסופר ועד אחר שעימו, \u0003ואמר רב חסדא\u0004 על כך: \u0003מתניתין\u0004 \u0005[משנתנו\u0006 זו\u0005]\u0006 המכשירה חתימת סופר כעד על הגט \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]?\u0006"],["\u0003ר' יוסי היא,\u0004 ש\u0003אמר: מילי\u0004 \u0005[דברים]\u0006 \u0003לא מימסרן\u0004 \u0005[נמסרים]\u0006 \u0003לשליח\u0004 ואין לחשוש שהסופר חתם במקום אדם אחר שמינה הבעל.","\u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר כי \u0003מודה ר' יוסי באומר \"אמרו\",\u0004 אם כן \u0003נפיק מינה חורבא\u0004 \u0005[יוצא מזה נזק,\u0006 מכשול\u0005],\u0006 \u0003דזימנין דאמר להו\u0004 \u0005[שפעמים שאומר להם]\u0006 \u0003לשנים \"אמרו לסופר ויכתוב ולפלוני ופלוני ויחתמו\", ומשום כיסופא\u0004 \u0005[בושתו]\u0006 של ה\u0003סופר\u0004 שנעלב משום שאין סומכים על מהימנותו שיוכל לחתום כעד, \u0003חיישי ומחתמי ליה\u0004 \u0005[חוששים ומחתימים אותו],\u0006 \u0003ו\u0004הרי הבעל \u0003לא אמר הכי\u0004 \u0005[כך],\u0006 ובמקרה זה בטל הגט, שהרי שינו מדעת המשלח.","\u0003אלא\u0004 אין חוששים לכך משום שר' יוסי אינו מודה אף באומר \"אמרו\", ואם כן \u0003מחוורתא\u0004 \u0005[מחוור],\u0006 כפי שאמרנו כי \u0003רישא\u0004 \u0005[הראש\u0006 תחילת המשנה\u0005]\u0006 כשיטת \u0003ר' מאיר וסיפא\u0004 \u0005[והסוף]\u0006 כשיטת \u0003ר' יוסי.\u0004","\u0003רב אשי אמר:\u0004 כל המשנה \u0003כולה ר' יוסי היא,\u0004 שאין כלל שליחות בדברים, \u0003ו\u0004בלשון \u0003לא מיבעיא קאמר\u0004 \u0005[נצרכה אמר],\u0006 וכוונתו: \u0003לא מבעיא היכא\u0004 \u0005[נצרכה\u0006 לומר \u0005במקום]\u0006 ש\u0003לא אמר \"תנו\", אלא אפילו אמר \"תנו\"\u0004 — \u0003לא\u0004 כשר הגט; \u0003ולא מבעיא היכא\u0004 \u0005[נצרכה\u0006 לומר \u0005במקום]\u0006 ש\u0003לא אמר לבי תלתא\u0004 \u0005[לשלושה],\u0006 \u0003אלא אפילו אמר לבי תלתא\u0004 \u0005[לשלושה]\u0006 — \u0003לא; ולא מיבעיא היכא\u0004 \u0005[נצרכה\u0006 לומר \u0005במקום]\u0006 ש\u0003לא אמר \"אמרו\" אלא אפילו אמר \"אמרו\"\u0004 — \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003לא.\u0004","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב אשי\u0004 שלא התיר רב יוסי אף באמירת \"אמרו\". ששנינו: \u0003כתב סופר\u0004 את הגט \u0003לשמה וחתמו עדים לשמה, אף על פי שכתבוהו וחתמוהו ונתנוהו לו\u0004 לבעל \u0003ונתנו לה\u0004 — \u0003הרי הגט בטל, עד שישמעו קולו שיאמר לסופר \"כתוב\" ולעדים \"חתומו\".\u0004","ומדברי הברייתא מדייקים: מה שנאמר \u0003\"ישמעו\"\u0004 — \u0003לאפוקי ממאן דאמר\u0004 \u0005[בא להוציא מ\u0006דברי \u0005מי שאומר]:\u0006 \u0003מודה ר' יוסי באומר \"אמרו\",\u0004 אלא צריך שישמעו את הבעל עצמו. ומה שנאמר בה \u0003\"קולו\"\u0004 — \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מ\u0004דברי \u0003רב כהנא אמר רב\u0004 שאפשר לעשות זאת על ידי כתיבה, אלא דווקא בשמיעת הקול.","האומר לאשתו \"הרי \u0003זה גיטיך אם מתי\u0004 (אמות)\", או \u0003\"\u0004הרי \u0003זה גיטיך\u0004 אם לא אתרפא \u0003מחולי זה\",\u0004 או \u0003\"זה גיטיך לאחר מיתה\"\u0004 — \u0003לא אמר\u0004 (אין בדבריו) \u0003כלום,\u0004 כיון שאין גט חל לאחר מיתה. ואולם אם אמר \u0003\"\u0004הרי זה גיטך \u0003מהיום אם מתי\",\u0004 או \u0003\"\u0004הרי זה גיטך \u0003מעכשיו אם מתי\"\u0004 — \u0003הרי זה גט,\u0004 שהרי קבע תנאי שבשעת מותו יחול הגט למפרע מהיום או מעכשיו.","אם אמר \u0003\"מהיום ולאחר מיתה\"\u0004 — הרי זה ספק, אם עיקר כוונתו שיחול הגט מהיום — והרי הוא גט כשר, או שעיקר כוונתו שיחול לאחר מיתה — ואינו גט ודנים אותו שהוא \u0003גט ואינו גט\u0004 גמור. \u0003ו\u0004משום כך \u0003אם מת\u0004 ולא היו לו בנים, ונפלה האשה לפני יבם — \u0003חולצת,\u0004 שמא לא היה זה גט והריהי ככל יבמה שאינה יכולה להינשא לאחר עד שיחלוץ לה היבם, \u0003ולא מתייבמת,\u0004 שמא גט כשר היה, והריהי גרושת האח שאסורה ליבם.","אם אמר \u0003\"זה גיטיך מהיום אם מתי מחולי זה\", ועמד\u0004 מחוליו \u0003והלך בשוק, וחלה ומת\u0004 אחר כך — \u0003אומדין אותו, אם מחמת חולי הראשון מת\u0004 — \u0003הרי זה גט,\u0004 שהרי נתקיים התנאי, \u0003ואם לאו\u0004 \u0005[לא]\u0006 שאומדים שנתרפא בינתיים מחולי זה, ומפני חולי אחר מת — \u0003אינו גט.\u0004","שנינו במשנה: \"זה גיטך אם מתי\" אינו גט, ומדייקים: \u0003אלמא\u0004 \u0005[מכאן\u0006 יוצא\u0005]\u0006 שהאומר \u0003\"אם מתי\" כ\u0004אומר \u0003\"לאחר מיתה\" דמי\u0004 \u0005[נחשב].\u0006 \u0003והדר תני\u0004 \u0005[וחזר ושנה]\u0006 בהמשך המשנה: אם אמר \u0003\"מהיום אם מתי\"\u0004 או \u0003\"מעכשיו אם מתי\"\u0004 — הרי זה גט, \u0003אלמא\u0004 \u0005[מכאן]\u0006 שהלשון \u0003\"אם מתי\" לאו\u0004 \u0005[לא]\u0006 \u0003כ\"לאחר מיתה\" דמי\u0004 \u0005[נחשבת],\u0006 שהרי מייד אחר כך שנינו \"מהיום ולאחר מיתה\" גט ואינו גט. ואם כן, סותרים הדיוקים הללו זה את זה!","\u0003אמר אביי:\u0004 הביטוי \u0003\"אם מתי\"\u0004 — \u0003שתי לשונות משמע: משמע כ\"מעכשיו\"\u0004 והריהו משמש כביטוי של תנאי: שאם ימות יתקיים הגט משעת נתינתו. \u0003ומשמע \"כלאחר מיתה\",\u0004 והריהו משמש כביטוי של זמן: כאשר ימות יהא זה גט.","אם \u0003אמר לה \"מהיום\"\u0004 — \u0003כמאן\u0004 \u0005[כמו]\u0006 ש\u0003אמר לה\u0004 \u0003\"מעכשיו\" דמי\u0004 \u0005[נחשב]\u0006 ו\"אם מתי\" הוא ביטוי של תנאי, ובתחילת המשנה ש\u0003לא אמר לה \"מהיום\"\u0004 — \u0003כמאן\u0004 \u0005[כמו]\u0006 ש\u0003אמר לה \"לאחר מיתה\" דמי\u0004 \u0005[נחשב],\u0006 שכוונתו שיחול הגט לאחר מותו בלבד.","שנינו במשנה: האומר \u0003\"זה גיטך אם מתי\"\u0004 — \u0003לא אמר כלום. אמר רב הונא: ו\u0004בכל זאת אם מת בעלה בלא בנים, אשה זו \u0003חולצת\u0004 ולא מתייבמת, שמא גט הוא.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 בלשון \u0003\"לא אמר כלום\" קתני\u0004 \u0005[שנה]\u0006 במשנה, ומשמע שאין הוא גט כלל! ומתרצים: כוונת המשנה היא ש\u0003לא אמר כלום\u0004 ולא הועילו דבריו לתקנתה כלל כיון \u0003דאסירא לעלמא\u0004 \u0005[שאסורה לכל]\u0006 ככל יבמה, \u0003וליבם נמי אסירא\u0004 \u0005[גם כן אסורה]\u0006 שמא בכל זאת הריהו גט.","ומקשים: \u0003והא מדסיפא\u0004 \u0005[והרי מתוך שבסופה\u0006 של המשנה\u0005]\u0006 שנה שבמקרה של ספק \u0003חולצת, מכלל\u0004 הדברים נשמע \u0003דרישא יבומי נמי מיבמה\u0004 \u0005[ש\u0006במקרה \u0005בראשה מתייבמת גם כן],\u0006 שאין ספק בדבר שאין הוא גט! ומשיבים: אין להקשות מכאן על רב הונא שכן \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 \u0003כ\u0004דעת \u0003רבנן\u0004 \u0005[חכמים]\u0006 היא, הסבורים שהגט אינו חל כלל וכלל, והאשה מתייבמת.","\u0003ו\u0004אילו \u0003רב הונא\u0004 לא פירש את דברי המשנה, אלא בא להשמיע הלכה והוא \u0003אמר כ\u0004דעת \u0003ר' יוסי,\u0004 שאמר בכלל: \u0003זמנו של שטר מוכיח עליו.\u0004 ומשום כך, אם זמנו של הגט הוא מעכשיו — משמע שהוא רוצה שיחול הגט מעכשיו, גם אם לא נאמר הדבר במפורש בשטר.","ומקשים: \u0003אי\u0004 \u0005[אם]\u0006 כשיטת \u0003ר' יוסי\u0004 — \u0003חליצה נמי\u0004 \u0005[גם כן]\u0006 \u0003לא ת\u0004 \u0003יבעי\u0004 \u0005[תצטרך],\u0006 שהרי לדעתו גט זה הוא גט גמור ואינה עומדת כלל ליבום! \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 \u0003מספקא ליה\u0004 \u0005[מסופק לו]\u0006 \u0003לרב הונא אי הלכתא\u0004 \u0005[אם הלכה]\u0006 \u0003כ\u0004שיטת \u0003ר' יוסי או אין הלכה כ\u0004שיטת \u0003ר' יוסי\u0004 ומשום כך החמיר כשתי השיטות, לומר שחולצת (שמא הלכה כר' יוסי) ולא מתייבמת (שמא הלכה כחכמים) — על כך יש להקשות: \u0003ומי מספקא ליה\u0004 \u0005[והאם מסופק לו]?\u0006","\u0003והא\u0004 \u0005[והרי]\u0006 \u0003רבה בר אבוה חלש\u0004 \u0005[חלה],\u0006 \u0003עול לגביה\u0004 \u0005[נכנסו אליו]\u0006 \u0003רב הונא ורב נחמן, אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא לרב נחמן: בעי מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003מרבה בר אבוה\u0004 שאלה זו: \u0003הלכה כ\u0004שיטת \u0003ר' יוסי או אין הלכה\u0004 כשיטתו? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן לרב הונא: \u0003טעמא\u0004 \u0005[הטעם]\u0006 של \u0003ר' יוסי לא ידענא\u0004 \u0005[אינני יודע],\u0006 \u0003הלכה איבעי מיניה\u0004 \u0005[אשאל ממנו]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב הונא: \u0003את בעי מיניה\u0004 \u0005[אתה שאל ממנו]\u0006 מהי \u0003הלכה,\u0004 \u0003וטעמיה\u0004 \u0005[וטעמו]\u0006 של \u0003ר' יוסי אנא אמינא\u0004 \u0005[אני\u0006 \u0003אומר]\u0004 \u0003לך\u0004 אחר כך.","\u0003בעי מיניה\u0004 \u0005[שאל ממנו]\u0006 רב נחמן את רבה בר אבוה שאלה זו. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב: הלכה כר' יוסי. לבתר דנפק\u0004 \u0005[לאחר שיצא]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב הונא לרב נחמן: \u0003היינו טעמא\u0004 \u0005[זהו הטעם]\u0006 של \u0003ר' יוסי, דקסבר\u0004 \u0005[שהוא סבור]:\u0006 \u0003זמנו של שטר מוכיח עליו\u0004 שכוונת כותב השטר שיחול השטר מאותו הזמן. ומכאן שברור שרב הונא סבור שהלכה כר' יוסי, שוודאי קיבל את דעת רבו המובהק, רב! \u0003אלא\u0004 כך צריך לומר, \u0003מספקא ליה\u0004 \u0005[מסופק לו]\u0006 לרב הונא"],["\u0003אי\u0004 \u0005[אם]\u0006 מה ש\u0003אמר ר' יוסי\u0004 שכל שטר חל מן הזמן הכתוב בו הוא גם כאשר הוסיף תנאי \u0003בעל פה\u0004 בשעת מסירת השטר, \u0003אי\u0004 \u0005[או]\u0006 \u0003לא אמר\u0004 במקרה שכזה.","ושואלים: \u0003ומי מספקא ליה\u0004 \u0005[והאם מסופק לו\u0006 הדבר\u0005]?\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 האומר לאשה \u0003\"הרי זה גיטך אם לא באתי מכאן ועד שנים עשר חדש\", ומת בתוך שנים עשר חדש\u0004 — \u0003אינו גט\u0004 כיון שאין גט חל לאחר מיתה, וחייבת ביבום אם אין לבעלה בנים. \u0003ותני עלה\u0004 \u0005[ושנינו עליה]:\u0006 אבל \u0003רבותינו\u0004 חולקים והם התירוה להינשא בתורת גרושה, ואינה זקוקה ליבום,","\u0003ואמרינן\u0004 \u0005[ואמרנו]:\u0006 \u0003מאן\u0004 \u0005[מי\u0006 הם\u0005]\u0006 \u0003רבותינו\u0004 אלה? \u0003אמר רב יהודה אמר שמואל: בי דינא\u0004 \u0005[בית דין]\u0006 \u0003דשרו מישחא\u0004 \u0005[שהתירו\u0006 את \u0005השמן]\u0006 של גויים באכילה, \u0003וסברי לה\u0004 \u0005[והם סבורים]\u0006 \u0003כ\u0004שיטת \u0003ר' יוסי,\u0004 ש\u0003אמר: זמנו של שטר מוכיח עליו.\u0004 הרי שלדעת ר' יוסי דין זה קיים גם כאשר אומר את התנאי בעל פה!","\u0003אלא\u0004 צריך לומר כך: \u0003מספקא ליה\u0004 \u0005[מסופק לו]\u0006 לרב הונא \u0003אי\u0004 \u0005[אם]\u0006 \u0003הלכה כ\u0004שיטת \u0003ר' יוסי\u0004 גם כשהוסיף על השטר דברים \u0003בעל פה, או אין הלכה\u0004 כמוהו אלא בכתב בלבד.","ושואלים: \u0003ומי מספקא ליה\u0004 \u0005[והאם\u0006 זה \u0005מסופק לו]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבא:\u0004 האומר לאשתו \u0003\"הרי זה גיטיך אם מתי\" ו\u0004כן \u0003\"\u0004הרי זה גיטיך \u0003שאני מת\"\u0004 — \u0003הרי זה גט,\u0004 אם אומר לה \u0003\"כשאמות\" ו\u0004כן \u0003\"לאחר מיתה\"\u0004 — \u0003אין זה גט.\u0004","ונברר \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003אמר לה \"מהיום\u0004 אם מתי \u0003\" ו\u0004לשיטת \u0003רבנן\u0004 \u0005[חכמים,\u0006 סתם משנה\u0005],\u0006 וכי \u0003צריכא למימר\u0004 \u0005[צריך\u0006 הדבר \u0005להיאמר]?\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]\u0006 יותר מזה: \u0003\"מהיום אם מתי\"\u0004 — \u0003הרי זה גט! ואלא לאו\u0004 \u0005[האם לא\u0006 מדובר\u0005]\u0006 ש\u0003לא אמר לה \"מהיום\" ו\u0004לשיטת \u0003ר' יוסי\u0004 היא שהולכים לפי זמנו של הגט, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 \u0003הלכה כ\u0004שיטת \u0003ר' יוסי\u0004 גם בענין זה!","ודוחים: מכאן אין להוכיח מה פסק רב הונא, שכן \u0003לרבא פשיטא ליה\u0004 \u0005[פשוט לו]\u0006 שהלכה כר' יוסי גם כשאומר בעל פה, ואילו \u0003לרב הונא מספקא ליה\u0004 \u0005[מסופק היה לו].\u0006","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 תירוץ אחר: \u0003לעולם\u0004 תפרש שמדובר ש\u0003אמר לה \"מהיום\" ורבנן\u0004 \u0005[ו\u0006שיטת \u0005חכמים]\u0006 היא, \u0003ו\u0004אולם \u0003הני לישני איצטריכי ליה\u0004 \u0005[ולשונות אלה הוצרכו לו\u0006 לרבא\u0005]\u0006 לחדש לנו דבר אחר, לומר כי הלשון \u0003\"שאני מת\"\u0004 שאינה מוזכרת במשנה — \u0003כ\u0004לשון \u0003\"אם מתי\" דמי\u0004 \u0005[נחשבת],\u0006 וכן הלשון \u0003\"כשאמות\"\u0004 — \u0003כ\u0004לשון \u0003\"לאחר מיתה\" דמי\u0004 \u0005[נחשבת].\u0006","עד כאן שיטה אחת של מסירת הסוגיה הזו, \u0003ואיכא דמתני לה אסיפא\u0004 \u0005[ויש ששונים אותה\u0006 \u0005על סופה\u0006 של אותה הלכה\u0005],\u0006 האומר: \u0003\"זה גיטך לאחר מיתה\"\u0004 — \u0003לא אמר כלום. אמר רב הונא: ולדברי ר' יוסי חולצת.\u0004","ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו הדבר\u0005],\u0006 \u0003מדסיפא\u0004 \u0005[מ\u0006תוך \u0005ש\u0006שנינו \u0005בסוף\u0006 המשנה\u0005]\u0006 במקרה שהוסיף \"מהיום\" \u0003לרבנן\u0004 \u0005[ל\u0006דעת \u0005חכמים]\u0006 \u0003חולצת,\u0004 \u0003רישא נמי\u0004 \u0005[ראשה גם כן]\u0006 שלא הוסיף \"מהיום\" \u0003ל\u0004דעת \u0003ר' יוסי חולצת,\u0004 שהרי לדעתו זמנו של שטר מוכיח עליו!","ומשיבים: אין ראיה מכאן, שכן \u0003מהו דתימא\u0004 \u0005[שתאמר],\u0006 \u0003ר' יוסי בהא\u0004 \u0005[בזה]\u0006 \u0003כ\u0004דעת \u0003רבי סבירא ליה\u0004 \u0005[סבור הוא]\u0006 ש\u0003אמר: גיטא מעליא הוי\u0004 \u0005[גט מעולה,\u0006 גמור, \u0005הוא],\u0006 \u0003וחליצה נמי\u0004 \u0005גם כן]\u0006 \u0003לא תיבעי\u0004 \u0005[תצטרך],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 ש\u0003לא רבי סבר לה\u0004 \u0005[סבור]\u0006 \u0003כר' יוסי, ולא ר' יוסי סבר לה\u0004 \u0005[סבור]\u0006 \u0003כרבי,\u0004 וכל אחד יש לו שיטה לחוד.","ומסבירים את הענין: \u0003רבי לא סבר לה\u0004 \u0005[סבור]\u0006 \u0003כר' יוסי\u0004 — \u0003דקתני\u0004 \u0005[שהוא שונה]\u0006 על נוסח \"מהיום ולאחר מיתה\" \u0003\"כזה גט\",\u0004 וההדגשה \"כזה\" באה \u0003למעוטי\u0004 \u0005[למעט]\u0006 מדברי \u0003ר' יוסי\u0004 המסופק בדבר. \u0003ו\u0004כן \u0003ר' יוסי לא סבר לה\u0004 \u0005[סבור]\u0006 \u0003כרבי\u0004 — \u0003דקתני\u0004 \u0005[שהוא שונה]\u0006 בענין דומה \u0003\"כזה גט\", למעוטי\u0004 \u0005[למעט]\u0006 דברי \u0003רבי.\u0004 הזכרנו כאן את דברי רבי ור' יוסי \"כזה גט\", ואת דבריהם עצמם לא הבאנו.","ומסבירים: שיטת \u0003רבי\u0004 זו \u0003מאי\u0004 \u0005[מה]\u0006 \u0003היא?\u0004 — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 האומר \u0003\"מהיום ולאחר מיתה\"\u0004 — הרי זה \u0003גט ואינו גט,\u0004 אלו \u0003דברי חכמים, רבי אומר: כזה גט,\u0004 כלומר, גט כשר הוא בלי ספק, ואינה צריכה חליצה.","\u0003ר' יוסי מאי\u0004 \u0005[מה]\u0006 \u0003היא,\u0004 מהו המקור בו מובעת דעתו — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 האומר \u0003\"כתבו ותנו גט לאשתי אם לא באתי מיכן\u0004 (מכאן) \u0003ועד שנים עשר חדש\",\u0004 אם \u0003כתבוהו בתוך שנים עשר חדש ונתנו\u0004 אותו \u0003לאחר שנים עשר חדש\u0004 — \u0003אינו גט, ר' יוסי אומר: כזה גט.\u0004","שנינו במשנה: האומר לאשה \u0003\"זה גיטיך מהיום אם מתי מחולי זה\", ועמד\u0004 מחוליו \u0003והלך בשוק\u0004 וחלה שוב ומת, אומדין אותו אם מחמת חולי הראשון מת — הרי זה גט, ואם לאו — אינו גט.","\u0003אמר רב הונא: גיטו\u0004 של שכיב מרע דינו \u0003כמתנתו, מה מתנתו אם עמד\u0004 מחוליו — \u0003חוזר\u0004 מכל המתנות שנתן בזמן שהיה שכיב מרע, והרי הן בטלות, שהרי לא נתן אותן אלא מחמת שחשב שהוא עומד למות, \u0003אף גיטו, אם עמד\u0004 מחליו — \u0003חוזר,\u0004 שלא נתן את הגט אלא משום שחשב שהוא עתיד למות וביקש לפוטרה מיבום.","\u0003ומה גיטו,\u0004 \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא פריש\u0004 \u0005[פירש]\u0006 את כוונתו במלואה, אנו מפרשים את דבריו, ונותנים את הגט לאשה \u0003כיון\u0004 ש\u0003אמר \"כתובו\"\u0004 — \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא אמר \"תנו\",\u0004 ולמרות שלא נתמלאו הפרטים הצריכים לכך באדם בריא, \u0003אף מתנתו\u0004 דינה כן, \u0003כיון דאמר \"תנו\"\u0004 — \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא קנו מיניה\u0004 \u0005[ממנו]\u0006 על הדבר, ולא נתמלאו הפרטים הצריכים לכך מבחינה משפטית, מכל מקום מקיימים את כוונתו ורצונו.","ומקשים, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003\"זה גיטך מהיום אם מתי מחולי זה\", ועמד והלך בשוק וחלה ומת\u0004 — \u0003אומדים אותו, אם מחמת חולי הראשון מת\u0004 — \u0003הרי זה גט, אם לאו\u0004 — \u0003אינו גט; ואי אמרת\u0004 \u0005[ואם אתה אומר]\u0006 ש\u0003אם עמד חוזר, למה לי\u0004 אם כן \u0003אומדנא\u0004 \u0005[אומדן,\u0006 הערכה\u0005]\u0006 כלל? \u0003הרי עמד,\u0004 וממילא בטל הגט!","\u0003אמר מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יוסף משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא:\u0004 מדובר כאן \u0003שניתק מחולי לחולי,\u0004 כלומר, לא שהבריא לגמרי, אלא שיצא ממחלה אחת לחבירתה, וצריך אומדן אם מחמת חוליו הראשון מת.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"עמד\" קתני\u0004 \u0005[שנה]\u0006 ומשמע שהבריא לגמרי! ומשיבים: אין הכוונה \u0003עמד\u0004 והבריא לגמרי, אלא עמד \u0003מחולי זה ונפל לחולי אחר.\u0004 ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"הלך בשוק\" קתני\u0004 \u0005[שנה]!\u0006 ומשיבים: \u0003הלך על משענתו,\u0004 כלומר, אין הכוונה שהלך בבריאות הגוף, אלא שיכול ללכת כאשר הוא נשען על משענת."],["\u0003והא קא משמע לן\u0004 \u0005[ו\u0006דבר \u0005זה השמיע לנו]\u0006 ש\u0003הלך על משענתו הוא דבעינן\u0004 \u0005[שצריכים אנו]\u0006 \u0003אומדנא\u0004 \u0005[אומדן]\u0006 אם מת מחולי זה או לא, ואולם \u0003אידך\u0004 \u0005[\u0006מקרה \u0005אחר]\u0006 כאשר לא עמד מן החולי וחלה מיד במחלה אחרת \u0003אומדנא נמי לא בעינן\u0004 \u0005[אומדן גם כן אין אנו צריכים],\u0006 אלא דנים אותו כאילו מת מחולי ראשון.","ושואלים: האם \u0003שמעת מינה\u0004 \u0005[למד אתה מזה]\u0006 כי \u0003שכיב מרע שניתק מחולי לחולי\u0004 — \u0003מתנתו מתנה?\u0004 ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 שכן \u0003אמר ר' אלעזר משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: שכיב מרע שניתק מחולי לחולי\u0004 ומת — \u0003מתנתו מתנה.\u0004","ומעירים: \u0003רבה ורבא לא סבירא להו הא\u0004 \u0005[אינם סבורים\u0006 כהלכה \u0005זו]\u0006 שאמר \u0003רב הונא,\u0004 שאם עמד מחוליו — בטל הגט. ומדוע — \u0003גזירה שמא יאמרו\u0004 האנשים ש\u0003יש גט לאחר מיתה\u0004 ויבואו להתיר אף כשהתנה במפורש שיהא גט לאחר מותו, שהרי רואים אנשים שאם אינו מת אין הגט חל.","ותוהים: \u0003ומי איכא מידי, דמדאורייתא לא הוי גיטא\u0004 \u0005[והאם יש דבר שמן התורה אינו גט],\u0006 \u0003ומשום גזירה\u0004 שאנו חוששים לטעות \u0003שרינן\u0004 \u0005[מתירים אנו]\u0006 \u0003אשת איש לעלמא\u0004 \u0005[לכל]?\u0006 שהרי אף רבה ורבא מסכימים שמן התורה כיון שעמד מחוליו — בטל הגט, ובכל זאת הם דנים גט זה כגט גמור, ויכולה האשה להינשא לאחר.","ומשיבים: \u0003אין\u0004 \u0005[כן]\u0006 כך הוא, ומתירים אותה להינשא, כי \u0003כל\u0004 ש\u0003מקדש\u0004 אשה \u0003אדעתא דרבנן\u0004 \u0005[על דעת חכמים]\u0006 הוא \u0003מקדש, ואפקעינהו רבנן לקדושין מיניה\u0004 \u0005[והפקיעו חכמים את הקידושין ממנו]\u0006 במקרה זה, ולכן מותרת האשה להינשא.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי:\u0004 \u0005תי\u0006 \u0003נח דקדיש בכספא\u0004 \u0005[נניח\u0006 אם \u0005קידש בכסף]\u0006 ואז מובן כיצד מפקיעים חכמים את הקידושין — שהם מחרימים את כסף הקידושין שנתן, לפי שהפקר בית דין הפקר, ונמצא שלא קידש בכסף שלו, ולא היו אלה קידושין, אלא \u0003קדיש\u0004 \u0005[\u0006אם \u0005קידש]\u0006 \u0003בביאה מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 כיצד יכולים חכמים להפקיע מעשה זה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003שויוה רבנן\u0004 \u0005[עשוה חכמים]\u0006 \u0003לבעילתו בעילת זנות,\u0004 שהפקיעו מביאה זו את צד הקידושין, והרי היא בעילה בלבד, ובעילה כשלעצמה אינה עושה קידושין אלא אם כן היתה בכך כוונה לשם קידושין.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 האומר לאשה \u0003\"זה גיטיך מהיום אם מתי מחולי זה\", ונפל הבית עליו או הכישו נחש\u0004 — \u0003אינו גט,\u0004 שהרי לא מחולי זה מת, אלא מדבר אחר. אבל אם אמר \u0003\"אם לא אעמוד מחולי זה\", ונפל עליו בית או הכישו נחש\u0004 — \u0003הרי זה גט.\u0004","ושואלים: \u0003מאי שנא רישא ומאי שנא סיפא\u0004 \u0005[מה שונה\u0006 ב\u0005תחילה ומה שונה\u0006 ב\u0005סוף]?\u0006 שהרי בכל מקרה לא מחמת חוליו מת! ולא נמצא פתרון לשאלה זו.","ואומרים שכך \u0003שלחו מתם\u0004 \u0005[משם,\u0006 מארץ ישראל\u0005]:\u0006 אם לאחר שאמר \"אם לא אעמוד מחולי זה\" \u0003אכלו ארי\u0004 — \u0003אין לנו\u0004 לחשוש לגט זה, ואינו נחשב כגט.","מסופר: \u0003ההוא גברא דזבין ארעא לחבריה\u0004 \u0005[אדם אחד שמכר קרקע לחבירו],\u0006 \u0003קביל עליה כל אונסא דמתיליד\u0004 \u0005[קיבל על עצמו כל אונס שיוולד,\u0006 שיווצר בקרקע\u0005],\u0006 שיחזיר לקונה את דמי הנזק. \u0003לסוף אפיקו בה נהרא\u0004 \u0005[בסוף הוציאו בו נהר],\u0006 כלומר, גזרה המלכות לעשות אפיק חדש לנהר והעבירוהו דרך הקרקע שמכר.","\u0003אתא לקמיה\u0004 \u0005[הלך\u0006 הקונה \u0005לפני]\u0006 \u0003רבינא\u0004 לתבוע, \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבינא לנתבע: \u0003זיל שפי ליה\u0004 \u0005[לך, שלם לו\u0006 פיצויים\u0005]\u0006 \u0003דהא קבילת עלך כל אונסא דמתיליד\u0004 \u0005[שהרי קיבלת עליך כל אונס שיוולד].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בר תחליפא לרבינא: אונסא\u0004 \u0005[אונס]\u0006 ש\u0003לא\u0004 \u0003שכיח\u0004 \u0003הוא,\u0004 ועל אונס כגון זה לא התנה!","\u0003איגלגל מילתא\u0004 \u0005[נתגלגל הדבר]\u0006 שלא נסתיים הדיון בזה, \u0003ומטא לקמיה\u0004 \u0005[והגיע לפני]\u0006 \u0003רבא. אמר להו\u0004 \u0005[להם]:\u0006 \u0003אונסא\u0004 \u0005[אונס]\u0006 ש\u0003לא שכיח הוא. איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבינא לרבא,\u0004 הלא שנינו: \u0003\"אם לא אעמוד מחולי זה\", ונפל עליו בית או הכישו נחש\u0004 — \u0003הרי זה גט,\u0004 והרי מאורעות כאלה הם אונס שאינו שכיח, ולא חשב עליהם, ובכל זאת הריהו גט!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: ואימא מרישא\u0004 \u0005[ואמור מראש]\u0006 הברייתא דיוק הפוך: שאם נפל עליו בית \u0003אינו גט,\u0004 משמע שאונס בלתי שכיח אינו בכלל התנאי! ואם כן יש סתירה פנימית בברייתא זו ואין להוכיח ממנה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא מדפתי לרבינא: ומשום דקשיא רישא אסיפא, לא מותבינן תיובתא מינה\u0004 \u0005[שקשה\u0006 באותה ברייתא מ\u0005ראשה לסופה אין אנו מקשים\u0006 עוד \u0005קושיה ממנה]?\u0006 והרי לכאורה מה שהקשה רבינא מסוף הברייתא — יפה הקשה!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבינא: \u0003אין\u0004 \u0005[כן],\u0006 צדק רבא, \u0003כיון דקשיא רישא אסיפא\u0004 \u0005[שקשה ראשה על סופה]\u0006 \u0003לא איתמר בי מדרשא ומשבשתא\u0004 \u0005[נאמרה\u0006 ברייתא זו ב\u0005בית המדרש, ומשובשת]\u0006 \u0003היא,\u0004 והואיל ואין אתה יכול לסמוך על הברייתא, \u0003זיל בתר סברא\u0004 \u0005[לך אחר הסברה],\u0006 ומסתבר שעל אונס בלתי מצוי כלל — \u0003לא התנה. מסופר,\u0004","\u0003רב פפא ורב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע זבן שומשמי אגדא\u0004 \u0005[קנו שומשומים על חוף]\u0006 של \u0003נהר מלכא, אגור מלחי לעבורינהו\u0004 \u0005[שכרו מלחים להעביר אותם\u0006 בנהר\u0005],\u0006 \u0003קבילו עלייהו כל אונסא דמתיליד\u0004 \u0005[קיבלו עליהם\u0006 המלחים \u0005כל אונס שיוולד,\u0006 שיווצר\u0005],\u0006 \u0003לסוף איסתכר\u0004 \u0005[בסוף נסכר]\u0006 \u0003נהר מלכא,\u0004 ולא יכלו להעביר את המטען בנהר,","\u0003אמרו להו\u0004 \u0005[להם]\u0006 שני חכמים אלה: \u0003אגורו חמרי אפקעינהו ניהלן\u0004 \u0005[שכרו חמורים ותנו אותם לנו]\u0006 כדי להעביר את השומשומים, \u0003דהא קבילתו עלייכו כל אונסא דמיתליד\u0004 \u0005[שהרי קיבלתם עליכם כל אונס שיוולד].\u0006","\u0003אתו לקמיה\u0004 \u0005[באו\u0006 לדין \u0005לפני]\u0006 \u0003רבא,\u0004 \u0003אמר להו\u0004 \u0005[להם]\u0006 לשני חכמים אלה: \u0003קאקי חיורי\u0004 \u0005[אווזים לבנים]\u0006 (לפי שהיו חכמים אלו בעלי זקן לבן קרא להם כך) \u0003משלחי גלימי דאינשי\u0004 \u0005[פושטי גלימות אנשים],\u0006 כלומר, אתם עושקים את הצד האחר שלא כדין, \u0003אונסא\u0004 \u0005[אונס]\u0006 ש\u0003לא שכיח הוא\u0004 שנהר מלכא יסכר, ואונס כזה לא קיבלו עליהם.","אותה אשה שנתן לה בעלה גט, והתנה שיחול מהיום אם ימות מאותו חולי — \u0003לא תתייחד עמו,\u0004 שמא יבואו מתוך כך לידי תשמיש, \u0003אלא בפני עדים,\u0004 שאז אין מקום לחשש זה.","ולא עדים כשרים דווקא, אלא \u0003אפילו על פי עבד אפילו על פי שפחה\u0004 מותר לה להתייחד עמו, \u0003חוץ משפחתה.\u0004 והטעם הוא — \u0003מפני שלבה גס\u0004 (רגיל) \u0003בה בשפחתה,\u0004 ופעמים תיבעל לבעלה אפילו בפני שפחתה.","ואותה אשה \u0003מה היא\u0004 מה מעמדה ההלכתי \u0003באותן הימים,\u0004 בין הזמן שנתן לה גט זה ועד לזמן קיום התנאי? — \u0003ר' יהודה אומר:\u0004 הרי היא"],["\u0003כאשת איש לכל דבריה\u0004 (לכל ענייניה וכל דיניה) ולגבי איסורה לאדם אחר. \u0003ר' יוסי אומר:\u0004 דינה כ\u0003מגורשת ואינה מגורשת,\u0004 שהיא ספק נשואה, ואף לגבי אחר — איסורה הוא כספק בלבד.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003ראוה לאחר\u0004 מתן גט זה \u0003שנתייחדה עמו,\u0004 עם בעלה \u0003באפילה או שישנה עמו תחת מרגלות המטה\u0004 — \u0003אין חוששין שמא נתעסקו בדבר אחר,\u0004 כלומר, בביאה, \u0003וחוששין משום זנות ואין חוששין משום קדושין. ר' יוסי בר'\u0004 \u0003יהודה אומר: אף חוששין משום קדושין.\u0004 דברי הברייתא הזו אינם ברורים, שהרי תחילה אמר שאף שנתייחדה אין חוששים לבעילה, ואחר כך אמר שחוששים לשום זנות.","ושואלים: \u0003מאי קאמר\u0004 \u0005[מה אמר]?\u0006 \u0003אמר רב נחמן אמר רבה בר אבוה, הכי קאמר\u0004 \u0005[כך אמר]:\u0006 אם ראוה שלא רק נתייחדה עמו, אלא \u0003ראוה\u0004 \u0003שנבעלה\u0004 לו ממש — \u0003חוששין משום קידושין,\u0004 שמא היתה בעילה זו כדי לחזור ולקדשה לאחר שגירשה. אבל אם \u0003נתן לה כספים\u0004 בסמוך לבעילה — \u0003חוששין\u0004 רק \u0003משום זנות, דאמרינן\u0004 \u0005[שאומרים\u0006 אנו]: \u0003ב\u0004דמי \u0003אתננה,\u0004 כזונה, \u0003נתן לה\u0004 כסף זה, \u0003ואין חוששין משום קידושין. ר' יוסי בר' יהודה אומר: אף בזו\u0004 במקרה זה \u0003חוששין משום קידושין,\u0004 שמא נתן לה את הכסף לשם קידושין.","ואומרים: אם כן, לדרך זו של הסבר הברייתא יש לומר: \u0003כמאן אזלא\u0004 \u0005[כ\u0006דעת \u0005מי הולכת]\u0006 \u0003הא\u0004 \u0005[זו]\u0006 ש\u0003אמר רבה בר בר חנה אמר ר' יוחנן: מחלוקת\u0004 בית שמאי ובית הלל (גיטין פא,א) בגרושה שנתייחד עמה בעלה לאחר גירושין, שלדעת בית שמאי אינה צריכה גט שני, ולבית הלל צריכה, מחלוקת זו אינה אלא \u0003כשראוה שנבעלה, אבל לא ראוה שנבעלה\u0004 — \u0003דברי הכל אין צריכה הימנו גט שני, כמאן\u0004 \u0005[כמי]\u0006 מהדעות שהוזכרו בברייתא?","— \u0003כדברי הכל,\u0004 כדעת תנא קמא ור' יוסי בר' יהודה, ששניהם אומרים שכאשר לא ראוה שנבעלה אין חוששים לקידושין ואינה צריכה גט שני.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003אביי,\u0004 על העמדת הברייתא באופן זה, שנחלקו תנא קמא ור' יוסי בר' יהודה במקרה שנתן לה כספים לאחר שבעלה: \u0003מידי\u0004 \u0005[וכי]\u0006 \u0003כספים קתני\u0004 \u0005[שנה\u0006 שם\u0005]?\u0006 והרי לא הוזכר בברייתא כלל מתן כסף!","\u0003אלא אמר אביי:\u0004 יש לחזור מן ההסבר הקודם, ו\u0003הכי קאמר\u0004 \u0005[כך אמר]\u0006 בברייתא: אם \u0003ראוה שנבעלה\u0004 — \u0003חוששין משום זנות, ואין חוששין משום קידושין. ר' יוסי בר' יהודה אומר: אף חוששין משום קידושין.\u0004","ואומרים: אם כן \u0003כמאן אזלא\u0004 \u0005[כ\u0006דעת \u0005מי הולכת]\u0006 \u0003הא\u0004 \u0005[זו]\u0006 ש\u0003אמר רבה בר בר חנה אמר ר' יוחנן: מחלוקת\u0004 בית שמאי ובית הלל — \u0003כשראוה שנבעלה,\u0004 \u0003אבל לא ראוה שנבעלה\u0004 — \u0003דברי הכל אין צריכה הימנו גט שני, כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]?\u0006","\u0003— כ\u0004דעת \u0003ר' יוסי בר' יהודה,\u0004 שהוא סבור כבית הלל שאם ראוה שנבעלה — חוששים לקידושין וצריכה גט שני, שאילו לדעת התנא קמא אף כשראוה שנבעלה אין חוששים לקידושין.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבא: אם כן,\u0004 שכך אתה מפרש את הברייתא \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 לשון ר' יוסי בר' יהודה \u0003\"אף\u0004 בזו חוששין משום קידושין\u0003\"?\u0004 והרי אם חוששים לקידושין אין חוששים לזנות!","\u0003אלא אמר רבא, הכי קאמר\u0004 \u0005[כך אמר]\u0006 בברייתא: \u0003ר' יוסי בר ר' יהודה אומר: אף\u0004 אם \u0003לא ראוה שנבעלה\u0004 — \u0003חוששין משום קידושין.\u0004","ואם כן \u0003כמאן אזלא\u0004 \u0005[כ\u0006דעת \u0005מי הולכת]\u0006 \u0003הא\u0004 \u0005[זו]\u0006 ש\u0003אמר רבה בר בר חנה אמר ר' יוחנן: מחלוקת\u0004 בית שמאי ובית הלל — \u0003כשראוה שנבעלה, אבל לא ראוה שנבעלה\u0004 — \u0003דברי הכל אין צריכה הימנו גט שני, כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]?\u0006","\u0003—\u0004 ש\u0003לא כחד\u0004 \u0005[כאחד]\u0006 מן התנאים, שהרי לפי פירושו של רבא חכמים אינם חוששים לקידושין אפילו כשראוה שנבעלה, ור' יוסי בר ר' יהודה חושש גם כשלא ראוה.","שנינו במשנה: \u0003מה היא באותן הימים?\u0004 — \u0003ר' יהודה אומר: כאשת איש לכל דבריה, ר' יוסי אומר: מגורשת ואינה מגורשת.\u0004","\u0003תנא\u0004 \u0005[שנה\u0006 החכם בברייתא\u0005]:\u0006 \u0003ובלבד שימות,\u0004 שהרי אם יקום מחוליו בוודאי שלא התקיים התנאי, ואינה מגורשת כלל. ושואלים: \u0003ולכי מיית הוי גיטא\u0004 \u0005[וכאשר ימות יהיה\u0006 זה \u0005גט]?\u0006 ונמצא איפוא שר' יהודה ור' יוסי סבורים שלא חל הגט אלא לאחר מיתת הבעל? \u0003והא קיימא לן\u0004 \u0005[והרי מוחזק לנו]\u0006 ש\u0003אין גט לאחר מיתה! אמר רבה: באומר \"\u0004יהיה זה גט \u0003מעת\u0004 אחרונה \u0003שאני בעולם\",\u0004 כלומר, כל עוד אני בחיים, ויחול זמן מועט לפני המיתה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003ימים שבינתים\u0004 עד שחל הגט לפני מיתת הבעל — \u0003בעלה זכאי במציאתה,\u0004 שחפץ שמצאה שייך לו, כתקנת חכמים שמציאת אשה לבעלה, \u0003ובמעשה ידיה,\u0004 ששכר עבודתה שייך לו, \u0003ובהפרת נדריה\u0004 שיכול להפר נדר שנדרה, \u0003ויורשה\u0004 אם מתה בינתיים,"]]};
